  [8025] = { "Riscatta il ⟦iCoke Prize Voucher=Buono Premio iCola⟧", nil, nil, nil, nil, 0xfd599f6c, nil, nil, nil, nil, ".mmmm" },
  [8026] = { "Riscatta il ⟦iCoke Prize Voucher=Buono Premio iCola⟧", nil, nil, nil, nil, 0xfd599f6c, nil, nil, nil, nil, ".mmmm" },
  [8041] = { "La forza del Monte Mugamba", nil, nil, nil, "Salute, {class}. Sono Jin'rokh il Distruttore, troll di Mugamba. Noi della tribù degli Zandalari riconosciamo le tue imprese. Rendiamo omaggio alla tua tenacia e alla tua forza di volontà.\n\nPorta questo talismano al collo, {class}. Lascia che la forza del Monte Mugamba scorra in tutto il tuo essere. Che ti dia potere mentre abbatti i nostri nemici!", 0x8072a5e9, nil, nil, nil, 0x31fed87d, ".mmm." },
  [8042] = { "La forza del Monte Mugamba", nil, nil, "È bello vederti in buona salute, {name}. Le gloriose battaglie che hai combattuto toccano ogni forma di vita su questo pianeta. Hakkar non deve mai lasciare i confini di ⟦Zul'Gurub=Zul'gurub⟧, o il mondo crollerà di certo sotto la sua fame immensa.\n\nDammi il tuo talismano e ne amplificherò la forza. Usa l'⟦Strength of Mugamba=Amuleto della Forza di Mugamba⟧ per punire i nostri nemici!", "Le nostre strade si incroceranno di nuovo, {class}.", 0x8072a5e9, nil, nil, 0x71abc13c, 0xe212a238, ".mm.." },
  [8043] = { "La forza del Monte Mugamba", nil, nil, "<Maestro/Maestra> {name}, sei tornat<o/a>! Molthor ha mandato al re notizia delle tue imprese. Il tuo nome è noto persino nei ⟦South Seas=Mari del Sud⟧. Forse un giorno sarai <un/una> {class} leggendari<o/a>: una storia per i secoli.\n\nDammi il tuo talismano, così che io possa amplificarne ancora il potere.", "Usa la tua nuova forza per distruggere i Gurubashi!", 0x8072a5e9, nil, nil, 0xbefeb2f1, 0x38bf1b42, ".mm.." },
  [8044] = { "La ⟦Rage of Mugamba=Rabbia di Mugamba⟧", nil, nil, "Re Rastakhan ti manda i suoi saluti, <Maestro/Maestra> {name}. Un simile onore non è mai stato concesso a nessuno al di fuori della tribù degli Zandalari.\n\n<Jin'rokh si inchina.>\n\nDammi il tuo talismano, così che io possa potenziarlo ancora. Sappi che la ⟦Rage of Mugamba=Rabbia di Mugamba⟧ è ora legata intimamente alla tua stessa anima.", "Zul'jin ti invidierebbe, {class}. Va' e conquista!", 0x4d6cacec, nil, nil, 0x0e203fad, 0xb3a29215, ".mm.." },
  [8045] = { "Il ⟦Heathen's Brand=Marchio del Pagano⟧", nil, nil, nil, "Sappi questo, pagan<o/a>: una catastrofe ci ha uniti. Gli Zandalari non comprendono né apprezzano i tuoi costumi pagani, ma siamo un popolo giusto. Porta questo marchio al collo. Servirà sia da avvertimento per i nostri nemici sia da simbolo della tua amicizia con gli Zandalari.\n\nContinua a servire il nostro popolo e amplificherò il potere del marchio.", 0x703228db, nil, nil, nil, 0x4290a07f, ".mmm." },
  [8046] = { "Il ⟦Heathen's Brand=Marchio del Pagano⟧", nil, nil, "Forse sono stato troppo precipitoso nel giudicarti, {class}. Pare che la tua fede cieca in questa Luce abbia un qualche valore, dopotutto.\n\nDammi il tuo marchio e ne amplificherò il potere.", "Fa' ciò che devi per sconfiggere i nostri nemici, {class}. Anche se significa incanalare la Luce.\n\n<Jin'rokh rabbrividisce.>", 0x703228db, nil, nil, 0x0b7a3a34, 0xc0127eea, ".mm.." },
  [8047] = { "Il ⟦Heathen's Brand=Marchio del Pagano⟧", nil, nil, "Devo confessarlo: non credevo che avessi la determinazione per portare a termine questa causa, {class}. Ora gli Zandalari vedono in te un aiuto prezioso. Davvero ben fatto.\n\nDammi il tuo marchio e ne amplificherò ancora una volta il potere.", "Le nostre fedi sono diverse, ma la nostra causa è giusta. Abbatti i nostri nemici, nobile {class}.", 0x703228db, nil, nil, 0x5d138380, 0xfe2a5d48, ".mm.." },
  [8048] = { "Il ⟦Hero's Brand=Marchio dell'Eroe⟧", nil, nil, "Il re ha riconosciuto la tua esistenza, {class}. Sei <il/la> prim<o/a> della tua specie a essere accettat<o/a> da Rastakhan come ver<o/a> alleat<o/a> degli Zandalari.\n\nSarai ricompensat<o/a> generosamente per i tuoi sforzi. Presenta il tuo marchio e applicherò l'amplificazione finale.", "Vigilanza, onore, lealtà, coraggio... Tu incarni tutte queste qualità, e così farà il tuo marchio.", 0x2c26bbb2, nil, nil, 0x2ed0d459, 0xb1aa9f00, ".mm.." },
  [8049] = { "L'⟦The Eye of Zuldazar=Occhio di Zuldazar⟧", nil, nil, nil, "Accetta questo talismano in segno della nostra gratitudine, <sacerdote/sacerdotessa>.\n\nL'Occhio di Zuldazar crescerà in potere man mano che il tuo legame con i troll Zandalari si rafforzerà. Torna da me di tanto in tanto e infonderò nuovo potere nel gioiello.", 0xaede248e, nil, nil, nil, 0xc307eb14, ".mmm.", nil, nil, nil, nil, 0x8af55bae },
  [8050] = { "L'⟦The Eye of Zuldazar=Occhio di Zuldazar⟧", nil, nil, "Benvenut<o/a>, <sacerdote/sacerdotessa>. L'⟦The Eye of Zuldazar=Occhio di Zuldazar⟧ pulsa di energia. Sei pront<o/a> per il passo successivo. Dammi il talismano e compirò l'infusione.", "Continua la tua battaglia contro lo Scortica Anime e i suoi servitori, {name}. Non deve mai essergli permesso di lasciare i confini di ⟦Zul'Gurub=Zul'gurub⟧.", 0xaede248e, nil, nil, 0x4350ef28, 0x4a6d592c, ".mm..", nil, nil, nil, 0x0b4b8ddb, nil },
  [8051] = { "L'⟦The Eye of Zuldazar=Occhio di Zuldazar⟧", nil, nil, "I venti sussurrano i racconti delle tue battaglie contro i Gurubashi, <sacerdote/sacerdotessa>. Persino i reali cominciano a parlare delle tue imprese. Si dice che re Rastakhan abbia perfino fatto il tuo nome.\n\nÈ giunto il momento di infondere l'Occhio. Dammi il talismano e compirò il rito.", "Sii risolut<o/a> nelle tue imprese, {name}. Lo Scortica Anime cercherà di prosciugarti la volontà di vivere.", 0xaede248e, nil, nil, 0xd49d5e04, 0xd9c04d29, ".mm..", nil, nil, nil, 0x9bab358b, nil },
  [8052] = { "L'⟦The All-Seeing Eye of Zuldazar=Occhio Onnisciente di Zuldazar⟧", nil, nil, "Se solo avessimo altri diecimila come te, {name}. Gli eserciti di Hakkar sarebbero dispersi al vento in un batter d'occhio.\n\n<Al'tabim sospira.>\n\nMa ora l'Occhio è pronto a esprimere tutto il suo potenziale. Dammelo.", "Colpiscili tutti e lascia che sia Hakkar a fare la cernita...", 0x34ea2a9f, nil, nil, 0x419f87bc, 0x9210ae1d, ".mm.." },
  [8053] = { "Paragons of Power: i Bracciali Foderati del Libero Pensatore", "Porta a Jin'rokh il Distruttore le ⟦Primal Hakkari Bindings=Manette degli Hakkari Primordiali⟧. Devi inoltre avere una reputazione almeno Amichevole con la ⟦Zandalar Tribe=Tribù Zandalari⟧.\n\nJin'rokh il Distruttore si trova sull'⟦Yojamba Isle=Isola di Yojamba⟧, nella Valle di Rovotorto.", "Sei <un/una> pagan<o/a>. I pagani hanno un posto nella tribù. I pagani sono i liberi pensatori degli Zandalari. I liberi pensatori non temono l'oppressione. I liberi pensatori muoiono per ciò in cui credono. Sappiamo che tu moriresti per ciò in cui credi. Questo ti vale il nostro riconoscimento. Questo ti vale la possibilità di metterti ancora alla prova.\n\nCi servono i Paragons of Power. Va' a ⟦Zul'Gurub=Zul'gurub⟧. Uccidi i servitori di Hakkar. Torna quando avrai ciò che cerco. Reclama la prima armatura da battaglia di un libero pensatore degli Zandalari.\n\nVa'.", "Sei tornat<o/a>? Hai i Paragons of Power? Mi stai facendo perdere tempo?\n\nSpero di no, pagan<o/a>.", "Ci fai grande onore. Le tue mani grondano del sangue dei servitori di Hakkar. Sei amic<o/a> della tribù.\n\nIndossa questi bracciali. Sono i bracciali foderati del libero pensatore. Ecco cosa intendo per vero potere.", 0xde2be376, 0x4cb7e339, 0xe682da0c, 0xe0f11fe4, 0x65fa2dcb, "....." },
  [8054] = { "Paragons of Power: la Cintura del Libero Pensatore", "Porta a Jin'rokh il Distruttore uno ⟦Primal Hakkari Shawl=Scialle degli Hakkari Primordiale⟧. Devi inoltre avere una reputazione almeno Onorato con la ⟦Zandalar Tribe=Tribù Zandalari⟧.\n\nJin'rokh il Distruttore si trova sull'⟦Yojamba Isle=Isola di Yojamba⟧, nella Valle di Rovotorto.", "Le tue credenze ci sono estranee, pagan<o/a>. Un tempo gli antichi Zandalari furono marchiati come eretici. Accadde quando l'Impero dei Gurubashi era forte. I pagani osarono sfidare il sacerdote di Hakkar. Allora i pagani furono braccati e uccisi come parassiti. Quei pagani non vacillarono mai nella lotta contro il Dio del Sangue. Onoriamo il prezzo che pagarono. Sono loro i liberi pensatori.\n\nDistruggi i servitori di Hakkar a ⟦Zul'Gurub=Zul'gurub⟧. Portami i Paragons of Power che cerco. Il successo sarà ben ricompensato.\n\nVa'.", "La tua presenza significa vittoria? Hai i Paragons? Grondi dei resti dei tuoi nemici?", "Il tuo onore nella tribù è assicurato. Rivendichi molte morti a ⟦Zul'Gurub=Zul'gurub⟧. I nemici cadono davanti alle tue convinzioni. I nemici cadono davanti al tuo potere.\n\nQuesta è la cintura del libero pensatore. È un simbolo d'onore. È un mojo potente. Ora è tua.", 0x9ed27549, 0x6d075c5a, 0x86b0f105, 0x62e7a93a, 0xc4f4ee72, "....." },
  [8055] = { "Paragons of Power: il Pettorale Corazzato del Libero Pensatore", "Porta a Jin'rokh il Distruttore un'⟦Primal Hakkari Tabard=Insegna degli Hakkari Primordiale⟧. Devi inoltre avere una reputazione almeno Reverito con la ⟦Zandalar Tribe=Tribù Zandalari⟧.\n\nJin'rokh il Distruttore si trova sull'⟦Yojamba Isle=Isola di Yojamba⟧, nella Valle di Rovotorto.", "L'armatura da battaglia dà potere nella tribù. Così vengono onorati i liberi pensatori. Sono fanatici. Infondono nei loro pettorali un mojo potente. Se la loro fede vacilla davanti al nemico, il pettorale non vacilla.\n\nDevi essere reverit<o/a> tra noi per possedere un simile pettorale. Va' a ⟦Zul'Gurub=Zul'gurub⟧. Prendi i Paragons of Power che mi servono. Strappa i Paragons agli stolti che sono là dentro, nel modo più doloroso. Portameli. Dimostra una volta per tutte il tuo valore di <libero/libera> <pensatore/pensatrice>.", "Hai i Paragons? Hanno del mojo dentro. Ci servono. Tu ci aiuterai.", "Hai fatto ciò che pochi hanno mai saputo fare. Hai messo in ginocchio i servitori di Hakkar. Hai mostrato loro cosa può fare un libero pensatore. Ci hai mostrato come un eretico possa essere riverito nella tribù. Hai più del vero potere. TU SEI il vero potere.\n\nPrendi il pettorale, <libero/libera> <pensatore/pensatrice>. Schiaccia chi ti si oppone.", 0x79d60ba4, 0x3082c49f, 0xc5fe864a, 0x948d58f7, 0x0ebc9145, "....." },
  [8056] = { "Paragons of Power: i Bracciali del Profeta", "Porta a Maywiki di Zuldazar gli ⟦Primal Hakkari Armsplint=Antibracci degli Hakkari Primordiali⟧. Devi inoltre avere una reputazione almeno Amichevole con la ⟦Zandalar Tribe=Tribù Zandalari⟧.\n\nMaywiki di Zuldazar si trova sull'⟦Yojamba Isle=Isola di Yojamba⟧, nella Valle di Rovotorto.", "I profeti della nostra tribù sono riveriti per il dono della vista divina, mon. Non sono santoni: passano il tempo a gettare le ossa o a leggere le foglie per trovare risposte, mica a lanciare malocchi alla gente. Da sciaman<o/a>, sai già qualcosa del potere della divinazione; noi Zandalari teniamo molto alla saggezza che i profeti danno alla tribù.\n\nPortami un'offerta di Paragons of Power da dentro ⟦Zul'Gurub=Zul'gurub⟧ e dimostraci il tuo valore. Fallo per noi e ti darò dei bracciali che i nostri profeti apprezzano più di ogni altra cosa!", "Hai i Paragons of Power di ⟦Zul'Gurub=Zul'gurub⟧ che mi servono? Questi bracciali valgono qualsiasi fatica tu debba fare!", "Pare che tu abbia dentro un po' del profeta degli Zandalari. Sappiamo delle imprese che hai compiuto a ⟦Zul'Gurub=Zul'gurub⟧ per noi, mon. Questi Paragons of Power aiuteranno parecchio la tribù degli Zandalari: una tribù, aggiungo, che puoi chiamare amica. Prendi questi bracciali, {name}: te li sei guadagnati, e anche di più!", 0x364aa100, 0x149fe38e, 0x00ebd8ea, 0xbf46324b, 0xff612ec7, "....." },
  [8057] = { "Paragons of Power: i Bracciali dell'Aruspice", "Porta a Maywiki di Zuldazar un ⟦Primal Hakkari Stanchion=Montante degli Hakkari Primordiale⟧. Devi inoltre avere una reputazione almeno Amichevole con la ⟦Zandalar Tribe=Tribù Zandalari⟧.\n\nMaywiki di Zuldazar si trova sull'⟦Yojamba Isle=Isola di Yojamba⟧, nella Valle di Rovotorto.", "L'aruspice è un membro fondamentale della nostra tribù: farai bene ad ascoltare i suoi presagi. Comunicando con gli animali e offrendoli agli spiriti quando serve, ci dà la guida divina. In passato l'intuito e la saggezza dell'aruspice ci diedero un vantaggio nelle guerre contro le tribù frammentate dei Gurubashi.\n\nPortami un'offerta di Paragons of Power da dentro ⟦Zul'Gurub=Zul'gurub⟧ e dimostraci il tuo valore. Fallo e ti darò dei bracciali che qualsiasi aruspice degli Zandalari vorrebbe.", "Hai preso i Paragons of Power da ⟦Zul'Gurub=Zul'gurub⟧? Questi bracciali valgono la fatica, {name}. Fidati, mon!", "Ah, sento il potere che viene da questi Paragons of Power, {name}. Hai dimostrato di essere qualcuno che noi della tribù possiamo chiamare «amico». Un patto è un patto, {name}... ammira il potere dei bracciali dell'aruspice!", 0xa22f9fd5, 0xa981faf7, 0x0dca424c, 0x4cdbbfcc, 0xca41f30b, "....." },
  [8058] = { "Paragons of Power: i Bracciali Foderati del Vendicatore", "Porta a Jin'rokh il Distruttore gli ⟦Primal Hakkari Armsplint=Antibracci degli Hakkari Primordiali⟧. Devi inoltre avere una reputazione almeno Amichevole con la ⟦Zandalar Tribe=Tribù Zandalari⟧.\n\nJin'rokh il Distruttore si trova sull'⟦Yojamba Isle=Isola di Yojamba⟧, nella Valle di Rovotorto.", "La vendetta è potere. Il vendicatore degli Zandalari è quel potere. La tribù ha molti nemici. Il vendicatore li ripaga. Nessun crimine contro di noi resta impunito. Il vendicatore infligge la punizione. I nostri nemici temono la nostra vendetta. Fanno bene. La temeranno per sempre.\n\nDiventa uno dei nostri vendicatori. Cerca i Paragons of Power dentro ⟦Zul'Gurub=Zul'gurub⟧. Uccidi i servitori di Hakkar e reclama vendetta nel nome della tribù. Sarai ricompensat<o/a>.", "Hai portato i Paragons of Power? È stata reclamata vendetta nel nome degli Zandalari?", "Oggi hai compiuto molta vendetta. Hai assunto il volto del vendicatore. Hai messo in ginocchio i servitori del Dio del Sangue.\n\nPrendi questo. Alimenterà la tua vendetta in futuro. Ora sei amic<o/a> degli Zandalari.", 0x04c2f9ac, 0x61a551e6, 0x7832db1f, 0x9733e57e, 0x3d2a6524, "....." },
  [8059] = { "Paragons of Power: le Polsiere Demoniache", "Porta ad Al'tabim l'Onnisciente un ⟦Primal Hakkari Stanchion=Montante degli Hakkari Primordiale⟧. Devi inoltre avere una reputazione almeno Amichevole con la ⟦Zandalar Tribe=Tribù Zandalari⟧.\n\nAl'tabim l'Onnisciente si trova sull'⟦Yojamba Isle=Isola di Yojamba⟧, nella Valle di Rovotorto.", "Gli stregoni camminano su un terreno pericoloso trattando con i demoni, ma i nostri demoniaci si spingono oltre. Con un rituale antico e arcano permettono a un demone di entrare nel loro essere. Invece di lasciarsi possedere, però, rendono schiavo il demone dall'interno e ne assorbono il potere, piegandolo al proprio comando. È un'impresa che pochi riescono mai a padroneggiare.\n\nPerché tu possa conoscere il potere del demoniaco, mi servono dei Paragons of Power da ⟦Zul'Gurub=Zul'gurub⟧. Va' laggiù e recupera ciò che cerchiamo.", "Sei tornat<o/a> con i Paragons of Power? Sconfiggendo i diabolici servitori di Hakkar non solo ci darai prova del tuo valore, ma anche della tua volontà di imparare le vie del demoniaco.", "Ben fatto... senza dubbio li hai fatti pagare in modi atroci prima che cedessero i Paragons of Power. Prendi queste: le polsiere demoniache. Fatte con un mojo potente usato per evocare le prede del demoniaco, sono uno strumento potente nella tua conquista del potere.", 0x508f1617, 0xca4f5ed3, 0x295c5c12, 0x6c5cc3e7, 0x4af30c71, "....." },
  [8060] = { "Paragons of Power: le Polsiere dell'Illusionista", "Porta ad Al'tabim l'Onnisciente le ⟦Primal Hakkari Bindings=Manette degli Hakkari Primordiali⟧. Devi inoltre avere una reputazione almeno Amichevole con la ⟦Zandalar Tribe=Tribù Zandalari⟧.\n\nAl'tabim l'Onnisciente si trova sull'⟦Yojamba Isle=Isola di Yojamba⟧, nella Valle di Rovotorto.", "Nella nostra tribù i maghi sono chiamati illusionisti. Nei loro incantesimi usano un mojo potente, che spesso stordisce e confonde i nemici della tribù!\n\n<Al'tabim ride malignamente.>\n\nÈ davvero uno spettacolo vedere all'opera un illusionista potente, che mette in ginocchio i nostri nemici con la loro stessa follia!\n\nPer conoscere la via dei nostri illusionisti, va' a ⟦Zul'Gurub=Zul'gurub⟧ e riportami alcuni Paragons of Power scelti. In cambio ti darò le polsiere che i nostri illusionisti usano per tessere i loro incantesimi.", "{name}, sei già tornat<o/a>? Sei riuscit<o/a> a prendere i Paragons of Power che mi servono?", "Impressionante... hai sentito il mojo che scorre in loro? I Paragons of Power erano usati come una specie di moneta quando l'Impero dei Gurubashi dominava queste terre. Ora noi Zandalari useremo il mojo latente al loro interno per combattere la seconda ascesa del Dio del Sangue Hakkar!\n\nOggi hai fatto un buon lavoro: considera gli Zandalari tuoi amici. Per questo, ecco le polsiere dell'illusionista che ti avevo promesso!", 0x37267b33, 0x8c856188, 0xe3909faa, 0xf2dc1007, 0x0232e56f, "....." },
  [8061] = { "Paragons of Power: le Polsiere del Confessore", "Porta ad Al'tabim l'Onnisciente un ⟦Primal Hakkari Stanchion=Montante degli Hakkari Primordiale⟧. Devi inoltre avere una reputazione almeno Amichevole con la ⟦Zandalar Tribe=Tribù Zandalari⟧.\n\nAl'tabim l'Onnisciente si trova sull'⟦Yojamba Isle=Isola di Yojamba⟧, nella Valle di Rovotorto.", "Noi Zandalari affidiamo il potere a chi parla con l'autorità della divinità. I nostri sacerdoti sono più che semplici guaritori: sono i nostri confessori. Il male viene sia dalle minacce esterne, come Hakkar, sia dall'interno della tribù. I nostri confessori sono i giudici tra noi e ci preservano dallo stesso male che divorò i Gurubashi dall'interno.\n\nVa' a ⟦Zul'Gurub=Zul'gurub⟧ e riporta i Paragons of Power dei Gurubashi. Impara cosa significa essere il confessore e preservaci dal male.", "Di ritorno da ⟦Zul'Gurub=Zul'gurub⟧, vero? Sei riuscit<o/a> a strappare i Paragons of Power ai servitori di Hakkar?", "Eccezionale, {name}! Portarmeli non è stata un'impresa da poco. Senza dubbio oggi hai fatto da confessore della nostra tribù, preservandoci dalla minaccia di Hakkar. Queste polsiere sono degne di un amico della tribù come te!", 0x540e9544, 0xca4f5ed3, 0x86d784dd, 0xe80d1aaa, 0xca192b7f, "....." },
  [8062] = { "Paragons of Power: i Bracciali del Predatore", "Porta a Falthir il Cieco i seguenti Paragons of Power da ⟦Zul'Gurub=Zul'gurub⟧: le ⟦Primal Hakkari Bindings=Manette degli Hakkari Primordiali⟧. Devi inoltre avere una reputazione almeno Amichevole con la ⟦Zandalar Tribe=Tribù Zandalari⟧.\n\nFalthir il Cieco si trova sull'⟦Yojamba Isle=Isola di Yojamba⟧, nella Valle di Rovotorto.", "Nei tempi bui dopo la caduta dell'Impero dei Gurubashi, i predatori degli Zandalari usarono la loro abilità per procurare il sostentamento alla tribù. I cacciatori dicono di somigliare molto ai predatori della nostra tribù: cercare la caccia significa incarnare l'essenza del predatore, sì. La tua caccia a ⟦Zul'Gurub=Zul'gurub⟧, però, ci mostrerà quanto vali davvero tra i nostri migliori predatori.\n\nPortami un campione dei Paragons of Power da dentro ⟦Zul'Gurub=Zul'gurub⟧. Fallo e muoverai i primi passi per diventare il predatore supremo.", "Dai la caccia a chi, a ⟦Zul'Gurub=Zul'gurub⟧, possiede i Paragons of Power, {name}. Sono la tua preda: hanno ciò che serve a entrambi.", "Sì... non mi serve la vista per percepire la presenza dei Paragons of Power. Il tuo successo a ⟦Zul'Gurub=Zul'gurub⟧ ha impressionato molti nella tribù. Non solo ti consideriamo amic<o/a> degli Zandalari, ma anche abbastanza degn<o/a> da possedere i bracciali del predatore: oggetti potenti e simbolo di ciò che significa essere un predatore. Ben fatto, {name}.", 0x0d61fa99, 0x14ce3c6a, 0x7c14821c, 0x5e16ced3, 0xd9d5a368, "....." },
  [8063] = { "Paragons of Power: i Bracciali degli Scriteriati", "Porta a Falthir il Cieco gli ⟦Primal Hakkari Armsplint=Antibracci degli Hakkari Primordiali⟧. Devi inoltre avere una reputazione almeno Amichevole con la ⟦Zandalar Tribe=Tribù Zandalari⟧.\n\nFalthir il Cieco si trova sull'⟦Yojamba Isle=Isola di Yojamba⟧, nella Valle di Rovotorto.", "Gli scriteriati degli Zandalari somigliano ai ladri, ma più di ogni altra cosa abbracciano la follia... il caos... l'imprevedibilità dell'esistenza. Erano un terrore da vedere sul campo di battaglia: seminarono confusione e scompiglio tra i nostri nemici nei tempi selvaggi dopo la frammentazione delle tribù. Senza di loro oggi non saremmo qui.\n\nPortami i Paragons of Power di ⟦Zul'Gurub=Zul'gurub⟧ che cerco e ti concederò la prima delle preziose armature degli scriteriati. Abbraccia la follia!", "Cerca la follia dentro ⟦Zul'Gurub=Zul'gurub⟧ e oscurala con la tua, {name}! Riuscirci significa successo, e il successo significa ricompensa! Che il Dio del Sangue non regni mai più sovrano!", "Ben fatto, {name}... le tue imprese a ⟦Zul'Gurub=Zul'gurub⟧ ti hanno dato il diritto di chiamare amica la tribù degli Zandalari. Mi occuperò io dei Paragons; per il tuo impegno, accetta questa ricompensa!", 0x2329b2ef, 0x6d2ba324, 0xac62a211, 0x5ad41329, 0x3b4f87cb, "....." },
  [8064] = { "Paragons of Power: la Cintura dell'Aruspice", "Porta a Maywiki di Zuldazar una ⟦Primal Hakkari Sash=Fascia degli Hakkari Primordiale⟧. Maywiki di Zuldazar si trova sull'⟦Yojamba Isle=Isola di Yojamba⟧, nella Valle di Rovotorto. Devi inoltre avere la reputazione Onorato con gli Zandalari.", "Noi Zandalari non conosciamo le vie dei druidi: la natura va plasmata secondo i nostri bisogni, non il contrario. Eppure l'aruspice è quello di noi più in sintonia con la natura, e a ragione. Togliere lo spirito a una bestiola significa sapere cosa vuol dire essere una di loro. Questo è il vero potere della natura.\n\nPortami un'offerta di Paragons of Power da dentro ⟦Zul'Gurub=Zul'gurub⟧ e dimostraci il tuo valore. Fallo e ti darò un oggetto potente: una cintura usata da molti aruspici degli Zandalari.\n\nMojo forte, mon!", "Hai i Paragons of Power di ⟦Zul'Gurub=Zul'gurub⟧ che mi servono? Se li hai, la cintura dell'aruspice sarà tua.", "Ti ringrazio: il potere latente di questi oggetti li renderà dei veri tesori, puoi giurarci. Non solo hai fatto ciò che ti ho chiesto, ma ti sei anche dimostrat<o/a> degn<o/a> d'onore per noi qui nella tribù. Come promesso, ecco la tua ricompensa!", 0xb03aaf35, 0x4f2188d0, 0x06722f41, 0x272e39ed, 0x258bdc17, "....." },
  [8065] = { "Paragons of Power: la Giubba dell'Aruspice", "Porta a Maywiki di Zuldazar un'⟦Primal Hakkari Tabard=Insegna degli Hakkari Primordiale⟧. Maywiki di Zuldazar si trova sull'⟦Yojamba Isle=Isola di Yojamba⟧, nella Valle di Rovotorto. Devi inoltre avere la reputazione Reverito con gli Zandalari.", "Il simbolo supremo del potere di un aruspice è ciò che indossa, {name}. Tra le sue vesti, la giubba simboleggia il legame tra l'aruspice e la saggezza divina che cerca. Spesso nella giubba si intrecciano parti delle bestiole sacrificate: così l'aruspice ricorda il legame con i suoi doni.\n\nPortami un'offerta di Paragons of Power da dentro ⟦Zul'Gurub=Zul'gurub⟧ e dimostraci il tuo valore. Fallo e sarà tua una giubba intrisa del vero potere di un aruspice.", "Hai i Paragons of Power necessari da ⟦Zul'Gurub=Zul'gurub⟧? La giubba dell'aruspice vale qualsiasi fatica tu debba fare.", "Impressionante... hai raccolto i Paragons of Power richiesti, {name}. Le tue imprese a ⟦Zul'Gurub=Zul'gurub⟧ per gli Zandalari sono leggendarie; d'ora in poi sarai riverit<o/a> nella tribù. Ecco la tua giubba, possente {class}!", 0x6c23d61c, 0x14495bd9, 0xd020a584, 0xbe2aa486, 0x56d32719, "....." },
  [8080] = { "⟦Arathi Basin Mark of Honor=Contrassegno d'Onore del Bacino d'Arathi⟧!", "Vinci la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧, ottieni un ⟦Arathi Basin Mark of Honor=Contrassegno d'Onore del Bacino d'Arathi⟧ e portalo al sergente Maclear al ⟦Refuge Pointe=Fosso dei Rifugiati⟧.", "La guerra si combatte con i soldati, te lo dirà qualunque soldato. Ti diranno anche che una battaglia combattuta con un equipaggiamento scadente o a stomaco vuoto è persa prima ancora di cominciare!\n\nEcco perché il ⟦Arathi Basin=Bacino d'Arathi⟧ è importante. Nel bacino ci sono zone chiave che custodiscono risorse essenziali. Metalli, armi, cibo, legname: servono tutti, e lì si possono ottenere tutti.\n\nEcco cosa voglio da te, {name}. Entra nel ⟦Arathi Basin=Bacino d'Arathi⟧, vinci la battaglia tenendo più basi del nemico e torna da me con un Contrassegno d'Onore.", "Hai i Contrassegni d'Onore, {name}? La ⟦The League of Arathor=Lega di Arathor⟧ non può combattere una battaglia come si deve senza di loro...", "Hai il Contrassegno! Ottimo lavoro! Manderò le risorse ai nostri furieri, che potranno distribuirle in fretta alle truppe.\n\nGrazie, {name}. In effetti, è con missioni riuscite come la tua che si vincono davvero le guerre.", 0x47b434b4, 0x9a052c21, 0x52039791, 0x37247045, 0x2c6df8ea, "....." },
  [8101] = { "Il ⟦Pebble of Kajaro=Ciondolo di Kajaro⟧", nil, nil, nil, "{race}, il ciottolo racchiuso nella montatura di questo talismano viene dal Monte Kajaro, nei ⟦South Seas=Mari del Sud⟧. Il Monte Kajaro è una zona tormentata dall'instabilità, segnata da eruzioni vulcaniche violente e spesso magiche.\n\nMan mano che il tuo legame con i troll Zandalari crescerà, crescerà anche il potere di questo ciottolo. Sfrutta il potere del ciottolo per abbattere i nostri nemici. Sii come la montagna: rapid<o/a>, esplosiv<o/a>, letale...", 0x2eb0ac60, nil, nil, nil, 0xa013bec7, ".mmm." },
  [8102] = { "Il ⟦Pebble of Kajaro=Ciondolo di Kajaro⟧", nil, nil, "Bentornat<o/a>, {class}. Vedo che il ciottolo è stato molto usato. Molti dei nostri nemici sono caduti davanti alle tue abilità ultraterrene. Le loro sofferenze sono state grandi. È ora che io potenzi il ciottolo. Dammelo.", "Sii inarrestabile, come le colate di lava del Kajaro.", 0x2eb0ac60, nil, nil, 0x91f18130, 0x208ad13f, ".mm.." },
  [8103] = { "Il ⟦Pebble of Kajaro=Ciondolo di Kajaro⟧", nil, nil, "Gli Hakkari ti temono, {name}. Parlano di orrori che credevano potesse compiere solo il loro dio senza volto. Li hai bruciati con la forza di Kajaro. Ora conoscono la paura in due luoghi.\n\nÈ ora di rafforzare ancora il ciottolo. Dammi il talismano.", "Continua a decimare i troll di ⟦Zul'Gurub=Zul'gurub⟧. Hakkar deve vedere che il mondo non si piegherà sotto la sua volontà indomabile.", 0x2eb0ac60, nil, nil, 0x72c69bed, 0x1629466e, ".mm.." },
  [8104] = { "Il ⟦Jewel of Kajaro=Gioiello di Kajaro⟧", nil, nil, "Dammi il talismano, {name}. Devo mostrarti una cosa.", "<Al'tabim frantuma il ciottolo con una potente forza invisibile.>\n\nVedi? Il ciottolo è ciò che chiamiamo geode. Dentro il ciottolo ci sono potenti cristalli che hanno assorbito le energie latenti del nostro mondo. Tagliando il ciottolo a metà, ho finalmente permesso al suo pieno potenziale di realizzarsi. Usalo per devastare i nostri nemici.", 0x11c42304, nil, nil, 0x9b44ada9, 0xc32a2d4b, ".mm.." },
  [8105] = { "La battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧!", "Assalta la miniera, la segheria, la fucina e la fattoria, poi torna dal primo maresciallo Oslight al ⟦Refuge Pointe=Fosso dei Rifugiati⟧.", "{name}, la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧ è una battaglia per le risorse e il territorio. I punti chiave della zona vanno tenuti e sfruttati per rifornire le nostre forze di materie prime e provviste di cui hanno gran bisogno. Ti ordino di assaltare i punti più lontani dalla nostra base nel ⟦Arathi Basin=Bacino d'Arathi⟧.\n\nAssalta la fattoria, la miniera, la segheria e la fucina quando sono controllate dal nemico. Trova lo stendardo nemico e strappalo dal pennone!\n\nQuando l'avrai fatto in tutti e quattro i punti, torna da me.", "{name}, non hai ancora assaltato le quattro basi. Torna da me quando avrai completato i tuoi obiettivi.", "Mi sono giunti rapporti delle tue imprese nel ⟦Arathi Basin=Bacino d'Arathi⟧, {name}. Ben fatto! Con gente come te a unirsi alla lotta qui, ho fiducia che un giorno riconquisteremo la nostra patria.", 0xe8197bb2, 0x24235866, 0xc4127755, 0x735eaefc, 0x82cf24dd, "....." },
  [8106] = { "Il ⟦Kezan's Taint=Marchio di Kezan⟧", nil, nil, nil, "Accetta questo talismano, {class}. Accettalo e usa il suo potere per abbattere i nostri nemici comuni.\n\nSappi che al collo porti un pezzo di storia. Kezan era un tempo un grande territorio dell'Impero degli Zandalari. Ahimè, la corruzione dei principi mercanti goblin avrebbe scacciato i miei fieri fratelli e sorelle.\n\nOggi Kezan ospita Undermine, la capitale dei goblin; ma sappi che prima della corruzione era terra di grandezza. Ancora oggi Kezan è considerata terra sacra dal mio popolo.", 0x6067a15d, nil, nil, nil, 0xea1fab20, ".mmm." },
  [8107] = { "Il ⟦Kezan's Taint=Marchio di Kezan⟧", nil, nil, "Tra i troll Zandalari l'onore si guadagna, {name}. Con l'onore arriva la ricompensa: amicizia, alleanza...\n\nDammi il talismano, così che io possa accrescerne il potere.", "Attingi all'oscurità, {class}. Abbraccia le ombre. Lascia che il ⟦Kezan's Taint=Marchio di Kezan⟧ alimenti le tue oscure trame.", 0x6067a15d, nil, nil, 0xff7aa25c, 0xb612eed1, ".mm.." },
  [8108] = { "Il ⟦Kezan's Taint=Marchio di Kezan⟧", nil, nil, "Sono pronto per te, {class}. Ancora una volta potenzierò il tuo talismano. Ti chiedo solo di continuare a distruggere Hakkar e i suoi servitori.\n\nDammi il talismano.", "Solo unendo i nostri sforzi fermeremo lo Scortica Anime.", 0x6067a15d, nil, nil, 0x4c9d4f28, 0x4bdb4d59, ".mm.." },
  [8109] = { "Il ⟦Kezan's Unstoppable Taint=Marchio Inarrestabile di Kezan⟧", nil, nil, "Evoca i tuoi demoni, {class}. Lascia che si crogiolino nell'energia del ⟦Kezan's Taint=Marchio di Kezan⟧. Comandali sul campo di battaglia! Decima il nemico!\n\nSì... È giunto il momento di applicare il potenziamento finale al ⟦Kezan's Taint=Marchio di Kezan⟧. Dammi il talismano.", "Strappa la carne dai loro cadaveri. Guarda le ombre consumare gli Hakkari. Trai potere dalla loro paura, {class}. Lascia che il ⟦Kezan's Taint=Marchio di Kezan⟧ accresca questo potere...", 0xed8cd3ad, nil, nil, 0xa5925c38, 0xce705016, ".mm.." },
  [8110] = { "⟦Enchanted South Seas Kelp=Alga Incantata dei Mari del Sud⟧", nil, nil, nil, "Vedi quest'alga, mon? Viene dai ⟦South Seas=Mari del Sud⟧. Ci aggiungiamo solo un po' di mojo e un po' di magia, e lei prende le proprietà più adatte al suo padrone.\n\nTu sei <un/una> {class}, quindi è facile, mon. Avvolgitela al collo e pensa alla natura, agli scoiattoli o a qualsiasi cosa piaccia a voi altri.", 0xd8a92e91, nil, nil, nil, 0x08cac145, ".mmm." },
  [8111] = { "⟦Enchanted South Seas Kelp=Alga Incantata dei Mari del Sud⟧", nil, nil, nil, nil, 0xd8a92e91, nil, nil, nil, nil, ".mmmm" },
  [8112] = { "⟦Enchanted South Seas Kelp=Alga Incantata dei Mari del Sud⟧", nil, nil, nil, nil, 0xd8a92e91, nil, nil, nil, nil, ".mmmm" },
  [8120] = { "La battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧!", "Assalta la miniera, la segheria, la fucina e la stalla del ⟦Arathi Basin=Bacino d'Arathi⟧, poi torna dal maestro della morte Dwire a ⟦Hammerfall=Requie del Martello⟧.", "Come avrai di certo sentito, la Lega di Arathor sta mandando truppe numerose nel ⟦Arathi Basin=Bacino d'Arathi⟧. Affamati di cibo e provviste, quegli sciocchi dell'⟦Alliance=Alleanza⟧ intendono prendere e controllare le ricche risorse del luogo. Dobbiamo mostrar loro che Arathi non sarà mai più una casa per gli umani!\n\nVa' nel ⟦Arathi Basin=Bacino d'Arathi⟧ e assalta la miniera, la segheria, la fucina e le stalle. Abbatti gli stendardi nemici e reclama quei territori per l'⟦Horde=Orda⟧.\n\nVa', {name}. Fai rapporto da me quando avrai portato a termine il compito.", nil, "Un esploratore dei Profanatori mi ha portato il resoconto del tuo successo, {name}. Ben fatto.\n\nCome imparerai, per vincere la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧ dobbiamo restare sempre vigili e schiacciare ogni tentativo di espansione dell'⟦Alliance=Alleanza⟧. Fallo, e la nostra vittoria qui è assicurata.", 0xe8197bb2, 0x5b64eb5f, 0xf3980fbf, nil, 0x1791a775, "...m." },
  [8123] = { "Tagliare i rifornimenti degli Arathor", "Vinci la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧, ottieni una ⟦Arathi Resource Crate=Cassa di Scorte d'Arathi⟧ e portala all'⟦Deathstalker=Inseguitore della Morte⟧ Mortis a ⟦Hammerfall=Requie del Martello⟧.", "La ⟦The League of Arathor=Lega di Arathor⟧ non bada a spese nel tentativo di riprendersi Arathi. Loro, e tutte le razze dell'⟦Alliance=Alleanza⟧, ora affluiscono in questa regione lontana, decisi ad allargare il loro dominio a partire dal ⟦Refuge Pointe=Fosso dei Rifugiati⟧. Dobbiamo fermarli, e il modo migliore per farlo è prendere le loro provviste.\n\nPuoi aiutarci, {name}. Entra nel ⟦Arathi Basin=Bacino d'Arathi⟧, noto per le sue ricche miniere, la terra fertile e gli abili artigiani. Conquista e controlla ogni base che puoi, vinci la battaglia e torna da me con le risorse che ottieni.", "Che c'è, {race}? Hai i Contrassegni d'Onore? Torna nel ⟦Arathi Basin=Bacino d'Arathi⟧, uccidi quei parassiti dell'⟦Alliance=Alleanza⟧ e impadronisciti delle loro risorse per la Dama Oscura!", "<L'⟦Deathstalker=Inseguitore della Morte⟧ Mortis sorride>\n\nUn altro colpo decisivo è stato inferto ai nostri nemici, {name}. Grazie alle tue gesta, il ⟦Arathi Basin=Bacino d'Arathi⟧ cadrà presto nelle mani dei Profanatori.", 0x7b8482f8, 0x81501782, 0xd18465ad, 0xd916acfe, 0x18a5b9a3, "....." },
  [8151] = { "Il talismano del cacciatore", "Parla con Ogtinc ad Azshara.", "Ogtinc di Azshara ha lanciato un appello ai cacciatori esperti come te. È un cacciatore mezzorso che ha lasciato la sua tribù per aiutare il ⟦Cenarion Circle=Circolo Cenariano⟧. I suoi insegnamenti servono ad arricchire la saggezza di chi condivide la sua arte e a guidarlo nel mantenere l'equilibrio. Faresti bene a parlargli.\n\nOgtinc vive in cima alle scogliere di Azshara, a nord-est delle ⟦Ruins of Eldarath=Rovine di Eldarath⟧.", nil, "Il mio compito non è più cacciare, ma insegnare al cacciatore. È ciò che il destino mi ha riservato.\n\nCrea con me un talismano del cacciatore: una raccolta di trofei di prede abbattute che ti ricorderà le tue prove e i tuoi trionfi passati. Alla fine terrò io il talismano, ma ti ricompenserò con qualcos'altro.", 0x9c075c99, 0xbd527185, 0xc599dc3a, nil, 0x0a79eb42, "...m." },
  [8153] = { "Corna di cervo", "Porta un paio di Corni di Cervo Perfetti a Ogtinc ad Azshara. Ogtinc vive in cima alle scogliere a nord-est delle ⟦Ruins of Eldarath=Rovine di Eldarath⟧.", "Il cervo cornuto porta le corna più possenti delle terre conosciute. Le usa per difendersi, incornando chi lo attacca e spesso danneggiandone le punte. Corna perfette e intatte sono il segno di uno spirito animale dalla fiducia suprema.\n\nPossedere corna simili ti donerà la stessa fiducia.\n\nCaccia i Mosshoof Courser, trova le corna perfette e portamele.", "Hai trovato le corna?", "Devi avere una vista acuta e una grande pazienza per averle ottenute. Ben fatto.", 0x34c40124, 0x49ab2b8b, 0x175db876, 0x1ce9f144, 0xc6cc8dfd, "....." },
  [8154] = { "Risorse del ⟦Arathi Basin=Bacino d'Arathi⟧!", "Vinci la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧, ottieni una ⟦Arathi Resource Crate=Cassa di Scorte d'Arathi⟧ e portala al sergente Maclear al ⟦Refuge Pointe=Fosso dei Rifugiati⟧.", "La guerra si combatte con i soldati, te lo dirà qualunque soldato. Ma ti diranno anche che una battaglia combattuta con un equipaggiamento scadente o a stomaco vuoto è persa prima di cominciare!\n\nEcco perché il ⟦Arathi Basin=Bacino d'Arathi⟧ è importante. Nel bacino ci sono zone chiave che custodiscono risorse essenziali. Metalli, armi, cibo, legname: servono tutti, e lì si possono ottenere tutti.\n\nÈ questo che voglio da te, {name}. Entra nel ⟦Arathi Basin=Bacino d'Arathi⟧, vinci la battaglia tenendo più basi del nemico e torna da me con una cassa di risorse.", "Hai i Contrassegni d'Onore, {name}? La ⟦The League of Arathor=Lega di Arathor⟧ non può combattere una battaglia come si deve senza di loro...", "Hai il Contrassegno! Ottimo lavoro! Manderò le risorse ai nostri furieri, che potranno distribuirle in fretta alle truppe.\n\nGrazie, {name}. In effetti, è con missioni riuscite come la tua che si vincono davvero le guerre.", 0xa6f22932, 0x982ec307, 0xfe0a59ea, 0x37247045, 0x2c6df8ea, "....." },
  [8155] = { "Risorse del ⟦Arathi Basin=Bacino d'Arathi⟧!", "Vinci la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧, ottieni una ⟦Arathi Resource Crate=Cassa di Scorte d'Arathi⟧ e portala al sergente Maclear al ⟦Refuge Pointe=Fosso dei Rifugiati⟧.", "La guerra si combatte con i soldati, te lo dirà qualunque soldato. Ma ti diranno anche che una battaglia combattuta con un equipaggiamento scadente o a stomaco vuoto è persa prima di cominciare!\n\nEcco perché il ⟦Arathi Basin=Bacino d'Arathi⟧ è importante. Nel bacino ci sono zone chiave che custodiscono risorse essenziali. Metalli, armi, cibo, legname: servono tutti, e lì si possono ottenere tutti.\n\nÈ questo che voglio da te, {name}. Entra nel ⟦Arathi Basin=Bacino d'Arathi⟧, vinci la battaglia tenendo più basi del nemico e torna da me con una cassa di risorse.", "Hai i Contrassegni d'Onore, {name}? La ⟦The League of Arathor=Lega di Arathor⟧ non può combattere una battaglia come si deve senza di loro...", "Hai il Contrassegno! Ottimo lavoro! Manderò le risorse ai nostri furieri, che potranno distribuirle in fretta alle truppe.\n\nGrazie, {name}. In effetti, è con missioni riuscite come la tua che si vincono davvero le guerre.", 0xa6f22932, 0x982ec307, 0xfe0a59ea, 0x37247045, 0x2c6df8ea, "....." },
  [8156] = { "Risorse del ⟦Arathi Basin=Bacino d'Arathi⟧!", "Vinci la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧, ottieni una ⟦Arathi Resource Crate=Cassa di Scorte d'Arathi⟧ e portala al sergente Maclear al ⟦Refuge Pointe=Fosso dei Rifugiati⟧.", "La guerra si combatte con i soldati, te lo dirà qualunque soldato. Ma ti diranno anche che una battaglia combattuta con un equipaggiamento scadente o a stomaco vuoto è persa prima di cominciare!\n\nEcco perché il ⟦Arathi Basin=Bacino d'Arathi⟧ è importante. Nel bacino ci sono zone chiave che custodiscono risorse essenziali. Metalli, armi, cibo, legname: servono tutti, e lì si possono ottenere tutti.\n\nÈ questo che voglio da te, {name}. Entra nel ⟦Arathi Basin=Bacino d'Arathi⟧, vinci la battaglia tenendo più basi del nemico e torna da me con una cassa di risorse.", "Hai i Contrassegni d'Onore, {name}? La ⟦The League of Arathor=Lega di Arathor⟧ non può combattere una battaglia come si deve senza di loro...", "Hai il Contrassegno! Ottimo lavoro! Manderò le risorse ai nostri furieri, che potranno distribuirle in fretta alle truppe.\n\nGrazie, {name}. In effetti, è con missioni riuscite come la tua che si vincono davvero le guerre.", 0xa6f22932, 0x982ec307, 0xfe0a59ea, 0x37247045, 0x2c6df8ea, "....." },
  [8160] = { "Tagliare i rifornimenti degli Arathor", "Vinci la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧, ottieni una ⟦Arathi Resource Crate=Cassa di Scorte d'Arathi⟧ e portala all'⟦Deathstalker=Inseguitore della Morte⟧ Mortis a ⟦Hammerfall=Requie del Martello⟧.", "La ⟦The League of Arathor=Lega di Arathor⟧ non bada a spese nel tentativo di riprendersi Arathi. Loro, e tutte le razze dell'⟦Alliance=Alleanza⟧, ora affluiscono in questa regione lontana, decisi ad allargare il loro dominio a partire dal ⟦Refuge Pointe=Fosso dei Rifugiati⟧. Dobbiamo fermarli, e il modo migliore per farlo è prendere le loro provviste.\n\nPuoi aiutarci, {name}. Entra nel ⟦Arathi Basin=Bacino d'Arathi⟧, noto per le sue ricche miniere, la terra fertile e gli abili artigiani. Conquista e controlla ogni base che puoi, vinci la battaglia e torna da me con le risorse che ottieni.", "Che c'è, {race}? Hai i Contrassegni d'Onore? Torna nel ⟦Arathi Basin=Bacino d'Arathi⟧, uccidi quei parassiti dell'⟦Alliance=Alleanza⟧ e impadronisciti delle loro risorse per la Dama Oscura!", "<L'⟦Deathstalker=Inseguitore della Morte⟧ Mortis sorride>\n\nUn altro colpo decisivo è stato inferto ai nostri nemici, {name}. Grazie alle tue gesta, il ⟦Arathi Basin=Bacino d'Arathi⟧ cadrà presto nelle mani dei Profanatori.", 0x7b8482f8, 0x81501782, 0xd18465ad, 0xd916acfe, 0x18a5b9a3, "....." },
