  [8162] = { "Tagliare i rifornimenti degli Arathor", "Vinci la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧, ottieni una ⟦Arathi Resource Crate=Cassa di Scorte d'Arathi⟧ e portala all'⟦Deathstalker=Inseguitore della Morte⟧ Mortis a ⟦Hammerfall=Requie del Martello⟧.", "La ⟦The League of Arathor=Lega di Arathor⟧ non bada a spese nel tentativo di riprendersi Arathi. Loro, e tutte le razze dell'⟦Alliance=Alleanza⟧, ora affluiscono in questa regione lontana, decisi ad allargare il loro dominio a partire dal ⟦Refuge Pointe=Fosso dei Rifugiati⟧. Dobbiamo fermarli, e il modo migliore per farlo è prendere le loro provviste.\n\nPuoi aiutarci, {name}. Entra nel ⟦Arathi Basin=Bacino d'Arathi⟧, noto per le sue ricche miniere, la terra fertile e gli abili artigiani. Conquista e controlla ogni base che puoi, vinci la battaglia e torna da me con le risorse che ottieni.", "Che c'è, {race}? Hai i Contrassegni d'Onore? Torna nel ⟦Arathi Basin=Bacino d'Arathi⟧, uccidi quei parassiti dell'⟦Alliance=Alleanza⟧ e impadronisciti delle loro risorse per la Dama Oscura!", "<L'⟦Deathstalker=Inseguitore della Morte⟧ Mortis sorride>\n\nUn altro colpo decisivo è stato inferto ai nostri nemici, {name}. Grazie alle tue gesta, il ⟦Arathi Basin=Bacino d'Arathi⟧ cadrà presto nelle mani dei Profanatori.", 0x7b8482f8, 0x81501782, 0xd18465ad, 0xd916acfe, 0x18a5b9a3, "....." },
  [8166] = { "La battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧!", "Assalta la miniera, la segheria, la fucina e la fattoria, poi torna dal primo maresciallo Oslight al ⟦Refuge Pointe=Fosso dei Rifugiati⟧.", "{name}, la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧ è una battaglia per le risorse e il territorio. I punti chiave della zona vanno tenuti e sfruttati per rifornire le nostre forze di materie prime e provviste di cui hanno gran bisogno. Ti ordino di assaltare i punti più lontani dalla nostra base nel ⟦Arathi Basin=Bacino d'Arathi⟧.\n\nAssalta la fattoria, la miniera, la segheria e la fucina quando sono controllate dal nemico. Trova lo stendardo nemico e strappalo dal pennone!\n\nQuando l'avrai fatto in tutti e quattro i punti, torna da me.", nil, "Mi sono giunti rapporti delle tue imprese nel ⟦Arathi Basin=Bacino d'Arathi⟧, {name}. Ben fatto! Con gente come te a unirsi alla lotta qui, ho fiducia che un giorno riconquisteremo la nostra patria.", 0xe8197bb2, 0x24235866, 0xc4127755, nil, 0x82cf24dd, "...m." },
  [8167] = { "La battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧!", "Assalta la miniera, la segheria, la fucina e la fattoria, poi torna dal primo maresciallo Oslight al ⟦Refuge Pointe=Fosso dei Rifugiati⟧.", "{name}, la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧ è una battaglia per le risorse e il territorio. I punti chiave della zona vanno tenuti e sfruttati per rifornire le nostre forze di materie prime e provviste di cui hanno gran bisogno. Ti ordino di assaltare i punti più lontani dalla nostra base nel ⟦Arathi Basin=Bacino d'Arathi⟧.\n\nAssalta la fattoria, la miniera, la segheria e la fucina quando sono controllate dal nemico. Trova lo stendardo nemico e strappalo dal pennone!\n\nQuando l'avrai fatto in tutti e quattro i punti, torna da me.", nil, "Mi sono giunti rapporti delle tue imprese nel ⟦Arathi Basin=Bacino d'Arathi⟧, {name}. Ben fatto! Con gente come te a unirsi alla lotta qui, ho fiducia che un giorno riconquisteremo la nostra patria.", 0xe8197bb2, 0x24235866, 0xc4127755, nil, 0x82cf24dd, "...m." },
  [8168] = { "La battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧!", "Assalta la miniera, la segheria, la fucina e la fattoria, poi torna dal primo maresciallo Oslight al ⟦Refuge Pointe=Fosso dei Rifugiati⟧.", "{name}, la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧ è una battaglia per le risorse e il territorio. I punti chiave della zona vanno tenuti e sfruttati per rifornire le nostre forze di materie prime e provviste di cui hanno gran bisogno. Ti ordino di assaltare i punti più lontani dalla nostra base nel ⟦Arathi Basin=Bacino d'Arathi⟧.\n\nAssalta la fattoria, la miniera, la segheria e la fucina quando sono controllate dal nemico. Trova lo stendardo nemico e strappalo dal pennone!\n\nQuando l'avrai fatto in tutti e quattro i punti, torna da me.", nil, "Mi sono giunti rapporti delle tue imprese nel ⟦Arathi Basin=Bacino d'Arathi⟧, {name}. Ben fatto! Con gente come te a unirsi alla lotta qui, ho fiducia che un giorno riconquisteremo la nostra patria.", 0xe8197bb2, 0x24235866, 0xc4127755, nil, 0x82cf24dd, "...m." },
  [8169] = { "La battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧!", "Assalta la miniera, la segheria, la fucina e la stalla del ⟦Arathi Basin=Bacino d'Arathi⟧, poi torna dal maestro della morte Dwire a ⟦Hammerfall=Requie del Martello⟧.", "Come avrai di certo sentito, la Lega di Arathor sta mandando truppe numerose nel ⟦Arathi Basin=Bacino d'Arathi⟧. Affamati di cibo e provviste, quegli sciocchi dell'⟦Alliance=Alleanza⟧ intendono prendere e controllare le ricche risorse del luogo. Dobbiamo mostrar loro che Arathi non sarà mai più una casa per gli umani!\n\nVa' nel ⟦Arathi Basin=Bacino d'Arathi⟧ e assalta la miniera, la segheria, la fucina e le stalle. Abbatti gli stendardi nemici e reclama quei territori per l'⟦Horde=Orda⟧.\n\nVa', {name}. Fai rapporto da me quando avrai portato a termine il compito.", nil, "Un esploratore dei Profanatori mi ha portato il resoconto del tuo successo, {name}. Ben fatto.\n\nCome imparerai, per vincere la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧ dobbiamo restare sempre vigili e schiacciare ogni tentativo di espansione dell'⟦Alliance=Alleanza⟧. Fallo, e la nostra vittoria qui è assicurata.", 0xe8197bb2, 0x5b64eb5f, 0xf3980fbf, nil, 0x1791a775, "...m." },
  [8170] = { "La battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧!", "Assalta la miniera, la segheria, la fucina e la stalla del ⟦Arathi Basin=Bacino d'Arathi⟧, poi torna dal maestro della morte Dwire a ⟦Hammerfall=Requie del Martello⟧.", "Come avrai di certo sentito, la Lega di Arathor sta mandando truppe numerose nel ⟦Arathi Basin=Bacino d'Arathi⟧. Affamati di cibo e provviste, quegli sciocchi dell'⟦Alliance=Alleanza⟧ intendono prendere e controllare le ricche risorse del luogo. Dobbiamo mostrar loro che Arathi non sarà mai più una casa per gli umani!\n\nVa' nel ⟦Arathi Basin=Bacino d'Arathi⟧ e assalta la miniera, la segheria, la fucina e le stalle. Abbatti gli stendardi nemici e reclama quei territori per l'⟦Horde=Orda⟧.\n\nVa', {name}. Fai rapporto da me quando avrai portato a termine il compito.", nil, "Un esploratore dei Profanatori mi ha portato il resoconto del tuo successo, {name}. Ben fatto.\n\nCome imparerai, per vincere la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧ dobbiamo restare sempre vigili e schiacciare ogni tentativo di espansione dell'⟦Alliance=Alleanza⟧. Fallo, e la nostra vittoria qui è assicurata.", 0xe8197bb2, 0x5b64eb5f, 0xf3980fbf, nil, 0x1791a775, "...m." },
  [8171] = { "La battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧!", "Assalta la miniera, la segheria, la fucina e la stalla del ⟦Arathi Basin=Bacino d'Arathi⟧, poi torna dal maestro della morte Dwire a ⟦Hammerfall=Requie del Martello⟧.", "Come avrai di certo sentito, la Lega di Arathor sta mandando truppe numerose nel ⟦Arathi Basin=Bacino d'Arathi⟧. Affamati di cibo e provviste, quegli sciocchi dell'⟦Alliance=Alleanza⟧ intendono prendere e controllare le ricche risorse del luogo. Dobbiamo mostrar loro che Arathi non sarà mai più una casa per gli umani!\n\nVa' nel ⟦Arathi Basin=Bacino d'Arathi⟧ e assalta la miniera, la segheria, la fucina e le stalle. Abbatti gli stendardi nemici e reclama quei territori per l'⟦Horde=Orda⟧.\n\nVa', {name}. Fai rapporto da me quando avrai portato a termine il compito.", nil, "Un esploratore dei Profanatori mi ha portato il resoconto del tuo successo, {name}. Ben fatto.\n\nCome imparerai, per vincere la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧ dobbiamo restare sempre vigili e schiacciare ogni tentativo di espansione dell'⟦Alliance=Alleanza⟧. Fallo, e la nostra vittoria qui è assicurata.", 0xe8197bb2, 0x5b64eb5f, 0xf3980fbf, nil, 0x1791a775, "...m." },
  [8181] = { "Confronto con Yeh'kinya", "Parla con Yeh'kinya.", "Le mie ricerche sulle Tavolette Mosh'aru portano notizie cupe, {name}. La vera forma di Hakkar, il dio in persona, può rinascere proprio dall'uovo in cui l'hai catturato. Yeh'kinya ti ha detto che serviva a contenere il suo male, ma serve a ricrearlo! Il troll ti ha ingannat<o/a>!\n\nVa' da Yeh'kinya e pretendi che ti consegni l'uovo. Prega che non sia troppo tardi per fermare il ritorno di Hakkar!", nil, "Dunque hai parlato con quel vecchio nano di Ironboot e hai ritrovato le Tavolette Mosh'aru perdute, vero? Quel prospettore ficcanaso...\n\nNon importa. È troppo tardi per salvare questo mondo. Hakkar è rinato, e già ora cresce in potere... nel profondo dell'antico regno troll di ⟦Zul'Gurub=Zul'gurub⟧! È arrivato! E regnerà nel sangue e nel terrore!\n\nGrazie, {name}. Il tuo aiuto ha accelerato il ritorno dello Scortica Anime!", 0x2bf7824a, 0x865aa76c, 0x0bb245c9, nil, 0xe5c76923, "...m." },
  [8182] = { "La Mano di Rastakhan", "Parla con Molthor a Rovotorto.", "{name}, le nostre peggiori paure si sono avverate. La leggenda narra che lo Scortica Anime dominasse l'antico mondo dei troll con il male e il terrore, e il suo potere era assoluto. Se non lo si ferma ora, il suo nuovo regno potrebbe estendersi su tutta Azeroth!\n\nC'è un contingente di troll Zandalari che potrebbe aiutarci ad arginare questa marea di tenebre. Si sono accampati sull'⟦Yojamba Isle=Isola di Yojamba⟧, al largo della costa di Rovotorto, a ovest delle Rovine di Zul'Kunda. Parla con il loro capo, Molthor, e prega che sappia come sconfiggere Hakkar.", nil, "Ti ha mandat<o/a> il prospettore Ironboot? Quelli come lui sono saggi, e ancor più saggio è stato lui a mandarti da me, perché io e i troll Zandalari forse conosciamo un modo per sconfiggere lo Scortica Anime.\n\nParla con i troll di quest'isola, ascolta le loro parole e preparati, {name}, perché il compito che ti attende è intriso di sangue.", 0x4d2a6b24, 0xa46e0578, 0x61260b13, nil, 0x265645c2, "...m." },
  [8231] = { "Caccia allo spazzaonda", "Porta 6 ⟦Wavethrasher Scales=Scaglie di Spazzaonda⟧ a Ogtinc ad Azshara. Ogtinc vive in cima alle scogliere a nord-est delle ⟦Ruins of Eldarath=Rovine di Eldarath⟧.", "Lo spazzaonda è una bestia anfibia che vive soltanto qui, ad Azshara. Sono creature potenti e resistenti.\n\nLe scaglie dure e riflettenti di uno spazzaonda rispecchiano la forza del cacciatore.\n\nSegui le tracce degli spazzaonda lungo la costa di Azshara, cacciali e portami le loro scaglie.", "Hai avuto successo?", "Gli spazzaonda non si sconfiggono facilmente, tanto meno nel loro ambiente acquatico.\n\nHai dimostrato di essere pront<o/a> a cacciare prede ancora più letali.", 0x44de0f03, 0x4d0a92ac, 0x8169d32a, 0x7cadef78, 0x363c01ff, "....." },
  [8232] = { "Il draco verde", "Porta il ⟦Tooth of Morphaz=Dente di Morphaz⟧ a Ogtinc ad Azshara. Ogtinc vive in cima alle scogliere a nord-est delle ⟦Ruins of Eldarath=Rovine di Eldarath⟧.", "Ora ti affido una caccia pericolosa: uccidi il draco verde Morphaz e portami il suo dente. Morphaz dimora nelle profondità del Tempio di Atal'Hakkar, il cui ingresso si trova nella ⟦Swamp of Sorrows=Palude del Dolore⟧.\n\nSe vuoi sconfiggerlo, non devi andarci da sol<o/a>. Questo draco ha molti nemici: cerca altri che vogliano distruggerlo.\n\nIl dente del draco rappresenta la forza che un cacciatore trova in compagnia degli altri. Portamelo e avrai imparato molto.", "Vedo saggezza nei tuoi occhi, {name}. La tua caccia è finita?", "Hai imparato le antiche vie, {name}, e per questo ti offro un dono dei miei giorni da {class}.", 0x846c7820, 0x16ae3f61, 0x5f7dfa78, 0xa74a1750, 0x12cd986d, "....." },
  [8233] = { "Una semplice richiesta", "Parla con lord Jorach Ravenholdt al ⟦Ravenholdt Manor=Maniero dei Corvolesto⟧.", "Lord Jorach Ravenholdt ha chiesto la tua presenza. La faccenda è segreta e non posso dirti altro.\n\nIl Maniero dei ⟦Ravenholdt=Corvolesto⟧ si trova nelle ⟦Hillsbrad Foothills=Alture di Colletorto⟧: cerca un sentiero tra le montagne a nord-ovest di Forte Durnholde.", nil, "Benvenut<o/a>, benvenut<o/a>, benvenut<o/a>! Prego, {name}, accomodati e discutiamo di una semplice faccenda.\n\nVedi, {name}, di recente ho perso qualcosa a cui tengo molto e, per dirla senza giri di parole, lo rivoglio a ogni costo. Ci sarà qualcosa anche per te, non preoccuparti! Oh sì, qualcosa di molto bello.\n\nAllora, che ne dici, {name}... sei pront<o/a> per un po' d'avventura?", 0x362b8cba, 0xf045dfbf, 0xbb6a9a60, nil, 0x782fc815, "...m." },
  [8234] = { "⟦Sealed Azure Bag=Sacca Azzurra Chiusa⟧", "Recupera la ⟦Sealed Azure Bag=Sacca Azzurra Chiusa⟧ dal Timbermaw Shaman ad Azshara. Poi porta la sacca all'arcimago Xylem, che si trova anche lui ad Azshara.", "Prima le cose importanti. Ciò che ho perso è una piccola sacca blu, il cui contenuto è una faccenda privata.\n\nNon perdere tempo a inseguire i ladri, perché sono già morti. Quello che sappiamo è che quegli sciocchi non sono riusciti ad aprire la sacca, così l'hanno venduta a un timbermaw shaman ad Azshara come reliquia sacra. Astuti.\n\nHo bisogno che tu vada ad Azshara e la recuperi da quello shaman con la discrezione... o con la forza. Scommetto che avrai più fortuna con il primo metodo. Una volta presa, portala all'arcimago Xylem.", "Ci conosciamo?", "Vedo che hai la sacca di lord Ravenholdt. Perché non l'hai detto subito, <ragazzo/ragazza>?", 0x35599650, 0x0ea5890f, 0xfe836e00, 0x879570ca, 0x860f19ff, ".....", nil, nil, nil, nil, 0xf0af4ecb },
  [8235] = { "Frammenti codificati", "Porta 10 Frammento Codificato all'arcimago Xylem ad Azshara.", "Lord Ravenholdt dei ⟦Ravenholdt=Corvolesto⟧ ha chiesto un favore a entrambi. Vuole rimuovere l'incantesimo da questa sacca.\n\nPurtroppo, di recente mi hanno sottratto alcuni dei miei libri sull'arte di dissolvere gli incantesimi, solo perché dei selvaggi li distruggessero. Ciò che resta dei miei libri ha ancora valore per me.\n\nSe mi porti abbastanza frammenti codificati, potrò rimetterli insieme. La cosa migliore è uccidere le melme della foresta, che tendono a raccogliere praticamente qualsiasi cosa. Le troverai nel nord-est di Azshara.", "Hai trovato abbastanza frammenti perché io possa continuare il mio lavoro?", "Sembra che tu abbia raccolto alcuni dei frammenti migliori. Forse non sei del tutto inutile, dopotutto.", 0x61daa4e2, 0xb44304fd, 0xca562999, 0x31bec209, 0x228991d5, "....." },
  [8236] = { "La ⟦Azure Key=Chiave Azzurra⟧", "Riporta la ⟦Azure Key=Chiave Azzurra⟧ a lord Jorach Ravenholdt.", "Ci vorrà un po' di tempo per decifrare i frammenti e rimuovere l'incantesimo. Quando avrò finito, consegnerò personalmente la sacca a lord Ravenholdt dei ⟦Ravenholdt=Corvolesto⟧.\n\nResta la questione della chiave, che si dice sia custodita da un draco verde di nome Morphaz. Il draco ha fatto la sua tana nelle profondità del Tempio di Atal'Hakkar, il cui ingresso si trova nella ⟦Swamp of Sorrows=Palude del Dolore⟧.\n\nRaduna i tuoi amici e avventurati nel suo covo. Lord Ravenholdt attenderà il tuo ritorno con la chiave.", "La sacca è già arrivata dall'arcimago Xylem. Hai trovato la chiave?", "La chiave! Credevo fosse perduta per sempre. Prego, prendi un indumento incantato dalle mie riserve: sono riservati ai ladri di eccezionale abilità e lealtà. Che si sappia: con {name} non si scherza!\n\n<Jorach apre la sacca e viene avvolto da un bagliore dorato che ne proviene. Spalanca gli occhi e fissa...>", 0x6d2a6be1, 0x4cbe4fb9, 0x108758a9, 0xfef60b7a, 0x12b73a85, "....." },
  [8250] = { "Arte magica", "Cerca Sanath Lim-yo e ottieni il passaggio per incontrare l'arcimago Xylem.", "L'arcimago Xylem va chiedendo in giro, ultimamente... di qualcuno con la tua esperienza.\n\nSe vuoi cercarlo, lo troverai ad Azshara. La sua torre sorge in cima alle scogliere, e l'unico modo per salirvi è un incantesimo di teletrasporto lanciato dal suo arrogante servitore, Sanath Lim-yo.\n\nSanath è accampato ai piedi della torre del suo padrone. Per trovarlo, raggiungi il punto in cui la strada principale di Azshara si biforca all'ingresso delle ⟦Ruins of Eldarath=Rovine di Eldarath⟧. Da lì, dirigiti dritto a nord finché non arrivi alle scogliere.", nil, "<Sanath ti guarda con disprezzo.>\n\nL'arci{class} Xylem attende il tuo arrivo.", 0x63df1028, 0xe163bc1a, 0xddf08947, nil, 0x6e8ed03a, "...m." },
  [8251] = { "⟦Magic Dust=Polvere Magica⟧", "Porta 10 ⟦Glittering Dust=Polvere Risplendente⟧ all'arcimago Xylem.", "Gli Elfi del Sangue di Azshara hanno messo a punto un metodo per polverizzare gli oggetti magici di cui si impossessano. La polvere risplendente che producono è diversa dai componenti che si ottengono di solito con un incantesimo di disincanto.\n\nQuando ho mandato il mio apprendista a scambiarla, l'hanno ucciso senza esitare. Per questo, devono pagare.\n\nIl tempo delle parole è finito, {name}. Trova gli Elfi del Sangue lungo le scogliere di Azshara e usa metodi più \"persuasivi\" per prenderti la loro polvere risplendente.", "Hai la polvere?", "Ben fatto, {name}! Non smette mai di stupirmi quanto possa essere persuasiva una raffica di missili arcani.", 0x4aaccda3, 0x2fc323bf, 0xe2ab9e6d, 0x8bb6c816, 0x45b28429, "....." },
  [8252] = { "Il corallo della sirena", "Raccogli 6 ⟦Enchanted Coral=Corallo Incantato⟧ e portalo all'arcimago Xylem.", "Guardati intorno. Le rovine e le spiagge sono infestate dagli Spitelash. Di recente, quelle miserabili creature hanno imparato a riconoscere i rari componenti originari di Azshara.\n\nParlo in particolare del corallo incantato: ne sono attratte per ragioni che non conosco. Ormai nella baia è rimasto poco corallo, ed è fondamentale per le mie ricerche. Devi strappare un po' di corallo incantato alle Spitelash Siren e portarmelo.", "Le Spitelash Siren sono maghe sorprendentemente abili. Non abili quanto te, spero?", "Questo è uno splendido esemplare di corallo, {name}. Le tue abilità sono indubbiamente precise e letali.\n\nNon pensare che i tuoi sforzi siano passati inosservati. Forse sei degn<o/a> di una vera prova della tua abilità...", 0x1c65cc0b, 0x82fc4efd, 0xd1f78fea, 0x7f257375, 0x19112c98, "....." },
  [8253] = { "Distruggi Morphaz", "Recupera la ⟦Arcane Shard=Scheggia Arcana⟧ da Morphaz e torna dall'arcimago Xylem.", "Nelle profondità del Tempio di Atal'Hakkar vive un draco verde di nome Morphaz.\n\nAnni fa mi sopraffece con un'audace imboscata e divorò intero il mio apprendista. La perdita di un apprendista non mi è nuova, ma quello in particolare portava con sé una scheggia arcana di dimensioni e qualità senza pari.\n\nDevi radunare alleati potenti e addentrarti nel tempio. Distruggi Morphaz e recupera la scheggia arcana dal suo stomaco senza età.", "Hai ucciso la mia vecchia nemesi?", "Incredibile. La scheggia è cresciuta assorbendo l'energia del draco nel corso dei lunghi anni.\n\nNon posso chiederti altro, ora. Con questa scheggia mi è tornata la piena capacità di forgiare l'arcano. La mia prima creazione è tua, {name}: non devi far altro che scegliere...", 0xa048a37c, 0x2aa42635, 0x3517d339, 0xaf55bdc0, 0xa8db02cb, "....." },
  [8254] = { "Aiuto cenariano", "Cerca Ogtinc ad Azshara.", "È nella natura del divino aiutare chi è nel bisogno. Il come non conta: conta solo il perché.\n\nIl ⟦Cenarion Circle=Circolo Cenariano⟧ ha un bisogno del genere. Parla con Ogtinc per portare aiuto alla loro causa. Vive in cima alle scogliere a nord-est delle ⟦Ruins of Eldarath=Rovine di Eldarath⟧, ad Azshara.", nil, "Il tuo arrivo mi ha tolto un peso dalle spalle. Abbiamo molto da fare.", 0x4f3b88f6, 0xc18aa317, 0xcabd114b, nil, 0x4d19dd02, "...m." },
  [8255] = { "Ciò che sappiamo dei cervi", "Procurati 4 Ghiandola di Cervo Sano e portale a Ogtinc ad Azshara. Ogtinc vive in cima alle scogliere a nord-est delle ⟦Ruins of Eldarath=Rovine di Eldarath⟧.", "I Mosshoof Courser di Azshara sono animali magnifici che un tempo vivevano a ⟦Felwood=Vilbosco⟧. Resistono per natura a malattie e veleni, e la corruzione di quel luogo non li ha toccati. Nella loro saggezza ancestrale, hanno semplicemente scelto di lasciare quel posto malato.\n\nMi si spezza il cuore, ma devo chiederti di cacciare per me queste bestie possenti. Raccogli quattro ghiandole di cervo come primo ingrediente per un unguento ristoratore: un unguento che useremo per guarire ⟦Felwood=Vilbosco⟧.", "Sei tornat<o/a>. Hai avuto successo?", "È un bene che il sentiero divino ti abbia condotto da noi, {name}. Le tue convinzioni non ostacolano i compiti necessari per creare questo unguento.\n\nVedi, il cervo cornuto è sacro per il ⟦Cenarion Circle=Circolo Cenariano⟧, e ucciderne uno per qualunque ragione, per quanto necessaria, ne indebolisce lo spirito.", 0x55179e19, 0x15671a76, 0x184c7352, 0x2d56b41b, 0x17d8db5e, "....." },
  [8256] = { "L'⟦Ichor of Undeath=Icore di Non Morto⟧", "Procurati un ⟦Ichor of Undeath=Icore di Non Morto⟧ per Ogtinc ad Azshara. Ogtinc vive in cima alle scogliere a nord-est delle ⟦Ruins of Eldarath=Rovine di Eldarath⟧.", "Per questo unguento ristoratore devi seguire una formula semplice: una parte di veleno, due parti di cura. Ti sei già procurato una cura, ora devi raccogliere il veleno.\n\nI non morti potenti, come gli Alti Nobili che vagano ancora per le ⟦Ruins of Eldarath=Rovine di Eldarath⟧, sono a volte così intrisi di male che questo si condensa in una melma verdastra e malsana. Per i vivi, questa sostanza è nota come icore di non morto.\n\nVista la potenza di questo elemento immondo, mi serve un solo icore.", "Dobbiamo procurarci l'icore in fretta. L'hai trovato?", "Non posso dire di essere contento di ricevere una sostanza così ripugnante, ma è un male necessario. Grazie, {name}.", 0xfcd9e83a, 0x9bed6ac1, 0xa5b0d6ca, 0xe9551c19, 0x8b009b40, "....." },
  [8257] = { "⟦Blood of Morphaz=Sangue di Morphaz⟧", "Uccidi Morphaz nel Tempio di Atal'Hakkar e porta il suo sangue a Greta Mosshoof, a ⟦Felwood=Vilbosco⟧. L'ingresso del tempio si trova nella ⟦Swamp of Sorrows=Palude del Dolore⟧.", "Ora l'ultima parte, la seconda cura.\n\nSi sa che il draco verde Morphaz è immune a ogni forma di veleno e malattia: molti druidi sono morti per portarci questa informazione. Non c'è dubbio che il suo sangue sia abbastanza potente per ciò che ci serve.\n\nUn corriere del ⟦Cenarion Circle=Circolo Cenariano⟧ prenderà le parti che hai già raccolto mentre tu ti procuri l'ultima. Chiama a raccolta i tuoi alleati e cerca la tana del draco nel Tempio di Atal'Hakkar. Porta il suo sangue a Greta Mosshoof, a ⟦Felwood=Vilbosco⟧.", "Hai il sangue di Morphaz?", "Hai ucciso Morphaz e ci hai portato il suo sangue... stento a credere a questa bella notizia!\n\nUniremo subito gli ingredienti e cominceremo a guarire gli alberi e le creature di ⟦Felwood=Vilbosco⟧. Ci vorrà una vita intera per rimediare a ciò che è successo qui, ma tu ci hai dato i mezzi per farlo.", 0xd09e0ccc, 0x65b255da, 0x916dae97, 0x3805e63b, 0x15dafe02, "....." },
  [8258] = { "La minaccia del Razziabuio", "Usa il ⟦Divination Scryer=Veggente della Divinazione⟧ nel cuore del sotterraneo del Great Ossuary, a Scholomance. Così facendo evocherai degli spiriti che dovrai combattere. Sconfitti gli spiriti, comparirà Death Knight Darkreaver: sconfiggilo.\n\nPorta la ⟦Darkreaver's Head=Testa del Razziabuio⟧ a Sagorne Creststrider nella Valle della Saggezza, a Orgrimmar.", nil, "Il tempo stringe, {name}: sei riuscit<o/a> a fermare la minaccia del cavaliere della morte Razziabuio?", nil, 0xf4f3bcea, 0x03ae7ce9, nil, 0xc513241d, nil, "..m.m" },
  [8260] = { "⟦Arathor Basic Care Package=Kit Curativo di Base degli Arathor⟧", nil, nil, nil, "Hai certamente cominciato a dimostrarci il tuo valore, {name}. Come ricompensa, prendi questo kit curativo! Dentro troverai razioni e bende utilizzabili solo nel ⟦Arathi Basin=Bacino d'Arathi⟧.\n\nContinuando a dimostrare il tuo valore nel Bacino, scoprirai che potrai acquistare questi oggetti. Le razioni diventano disponibili quando sei Amichevole con noi, e le bende quando sei Onorato.", 0x2506a72d, nil, nil, nil, 0x837511ae, ".mmm." },
  [8261] = { "⟦Arathor Standard Care Package=Kit Curativo Standard degli Arathor⟧", nil, nil, nil, "Hai certamente cominciato a dimostrarci il tuo valore, {name}. Come ricompensa, prendi questo kit curativo! Dentro troverai razioni e bende utilizzabili solo nel ⟦Arathi Basin=Bacino d'Arathi⟧.\n\nContinuando a dimostrare il tuo valore nel Bacino, scoprirai che potrai acquistare questi oggetti. Le razioni diventano disponibili quando sei Amichevole con noi, e le bende quando sei Onorato.", 0xccaf8ee0, nil, nil, nil, 0x837511ae, ".mmm." },
  [8262] = { nil, nil, nil, nil, "Hai certamente cominciato a dimostrarci il tuo valore, {name}. Come ricompensa, prendi questo kit curativo! Dentro troverai razioni e bende utilizzabili solo nel ⟦Arathi Basin=Bacino d'Arathi⟧.\n\nContinuando a dimostrare il tuo valore nel Bacino, scoprirai che potrai acquistare questi oggetti. Le razioni diventano disponibili quando sei Amichevole con noi, e le bende quando sei Onorato.", nil, nil, nil, nil, 0x837511ae, "mmmm." },
  [8263] = { "⟦Defiler's Basic Care Package=Kit Curativo di Base dei Profanatori⟧", nil, nil, nil, "Hai certamente cominciato a dimostrarci il tuo valore, {name}. Come ricompensa, prendi questo kit curativo! Dentro troverai razioni e bende utilizzabili solo nel ⟦Arathi Basin=Bacino d'Arathi⟧.\n\nContinuando a dimostrare il tuo valore nel Bacino, scoprirai che potrai acquistare questi oggetti. Le razioni diventano disponibili quando sei Amichevole con noi, e le bende quando sei Onorato.", 0x7c3e3820, nil, nil, nil, 0x837511ae, ".mmm." },
  [8264] = { "⟦Defiler's Standard Care Package=Kit Curativo Standard dei Profanatori⟧", nil, nil, nil, "Hai certamente cominciato a dimostrarci il tuo valore, {name}. Come ricompensa, prendi questo kit curativo! Dentro troverai razioni e bende utilizzabili solo nel ⟦Arathi Basin=Bacino d'Arathi⟧.\n\nContinuando a dimostrare il tuo valore nel Bacino, scoprirai che potrai acquistare questi oggetti. Le razioni diventano disponibili quando sei Amichevole con noi, e le bende quando sei Onorato.", 0x926dd81b, nil, nil, nil, 0x837511ae, ".mmm." },
  [8273] = { "La gratitudine di Oran", nil, nil, nil, "Ma guarda, non è interessante? Dici di aver trovato questa tavoletta su un isolotto deserto presso la ⟦The Overlook Cliffs=Scogliera Altosguardo⟧, nelle ⟦The Hinterlands=Entroterre⟧, {class}? Davvero molto interessante. <Oran ripone con cura la tavoletta e si sfrega le mani.>\n\nTi ringrazio per i tuoi sforzi in questa faccenda. La nostra Dama Oscura sarà molto soddisfatta di questa scoperta. Ecco, lascia che ti ricompensi come si deve.", 0x9612f92a, nil, nil, nil, 0xd46b2373, ".mmm." },
  [8274] = { "Missione di prova di uccisione", "Uccidi 5 Murloc e torna dal personaggio di prova.", "Hai un po' di tempo libero? Uccidimi qualche Murloc e ti darò qualcosa di luccicante!", nil, nil, 0x2cbcf304, 0x00bf1e49, 0xa551eef6, nil, nil, "...mm" },
  [8275] = { "Riconquistare ⟦Silithus=Silitus⟧", "Parla con l'evocatore del vento Proudhorn alla ⟦Cenarion Hold=Fortezza Cenariana⟧, a ⟦Silithus=Silitus⟧.", "Attenzione, eroi dell'⟦Alliance=Alleanza⟧! La minaccia dei silitidi è stata ignorata troppo a lungo. Senza alcuna vera opposizione, per tutto questo tempo si sono preparati a un'espansione su larga scala.\n\nLe forze del Circolo Cenariano si stanno radunando a ⟦Silithus=Silitus⟧ per portare la battaglia a queste orribili creature, e tutti gli avventurieri in grado di combattere sono chiamati a unirsi a noi!\n\nNon aspettate che sia troppo tardi! Aiutateci a difendere Azeroth! Presentatevi all'evocatore del vento Proudhorn alla ⟦Cenarion Hold=Fortezza Cenariana⟧ per istruzioni precise!", nil, "Eccellente, una nuova recluta che risponde alla chiamata alle armi contro i silitidi. <Benvenuto/Benvenuta> alla ⟦Cenarion Hold=Fortezza Cenariana⟧, {class}. Sono lieto di vedere che le parole dei nostri emissari raggiungono eroi del tuo calibro. Non ti mancheranno le occasioni per aiutarci nei nostri sforzi qui, e mi aspetto che dimostrerai presto di essere <un/una> <prezioso/preziosa> <alleato/alleata> per la nostra causa.", 0x1f4019a6, 0xdd40063b, 0x86d6a1fd, nil, 0xe3b065a1, "...m." },
  [8276] = { "Riconquistare ⟦Silithus=Silitus⟧", "Parla con l'evocatore del vento Proudhorn alla ⟦Cenarion Hold=Fortezza Cenariana⟧, a ⟦Silithus=Silitus⟧.", "Attenzione, campioni dell'⟦Horde=Orda⟧! C'è una minaccia che abbiamo lasciato incontrastata troppo a lungo. I tremori della terra vicino agli alveari dei silitidi in tutta Azeroth ci hanno segnalato grandi spostamenti delle loro schiere, mentre si preparano a espandersi.\n\nLe forze del Circolo Cenariano si stanno radunando a ⟦Silithus=Silitus⟧ per portare la battaglia ai silitidi prima che sia troppo tardi! Non profaneranno più le nostre terre!\n\nTutti i combattenti in grado di farlo devono presentarsi all'evocatore del vento Proudhorn alla ⟦Cenarion Hold=Fortezza Cenariana⟧! I silitidi saranno sconfitti!", nil, "Eccellente, una nuova recluta che risponde alla chiamata alle armi contro i silitidi. <Benvenuto/Benvenuta> alla ⟦Cenarion Hold=Fortezza Cenariana⟧, {class}. Sono lieto di vedere che le parole dei nostri emissari raggiungono eroi del tuo calibro. Non ti mancheranno le occasioni per aiutarci nei nostri sforzi qui, e mi aspetto che dimostrerai presto di essere <un/una> <prezioso/preziosa> <alleato/alleata> per la nostra causa.", 0x1f4019a6, 0xdd40063b, 0xbcb39090, nil, 0xe3b065a1, "...m." },
  [8277] = { "Veleno letale del deserto", "Beetix Ficklespragg, alla ⟦Cenarion Hold=Fortezza Cenariana⟧ di ⟦Silithus=Silitus⟧, vuole che tu raccolga 8 Pungiglione di ⟦Scorpid=Scorpide⟧ Sferzapietra e 8 Artiglio di Ragno Saltatore delle Sabbie. Torna da lei quando avrai finito.", "Beetix Ficklespragg, al tuo servizio! Mio cugino Noggle si guadagna da vivere raccogliendo erbe rare per gli alchimisti della ⟦Cenarion Hold=Fortezza Cenariana⟧. O almeno così faceva. È tornato dal suo ultimo viaggio con un potente veleno che gli scorre nelle vene.\n\nHo rallentato l'effetto del veleno, ma per neutralizzarlo del tutto mi servono campioni di veleno di qualunque cosa l'abbia punto.\n\nNoggle è arrivato da nord, quindi ci scommetterei la camicia che sono stati gli scorpidi sferzapietra o i ragni saltatori delle sabbie. Portami un po' di pungiglioni e di zanne e cercherò di preparargli un antidoto.", "Hai finito di raccogliere quei campioni? Potremmo perdere Noggle da un momento all'altro!", "Incrocia le dita, <amico/amica>! Speriamo di riuscire a salvare Noggle!", 0xafbb460e, 0x6d92e050, 0xcbe8ea80, 0xf863dda3, 0xf920ed97, "....." },
  [8278] = { "L'ultima speranza di Noggle", "Beetix Ficklespragg, alla ⟦Cenarion Hold=Fortezza Cenariana⟧ a ⟦Silithus=Silitus⟧, vuole che tu raccolga 3 Pungiglione di Pinzatore Sferzapietra, 3 Pungiglione di Scorticatore Sferzapietra e 3 Zanna di Ragno Inseguitore della Roccia.", "Accidenti! L'antidoto non ha funzionato. Noggle dev'essere stato punto da una delle creature più forti dell'estremo sud.\n\nHo bisogno che tu vada laggiù a prendermi altri campioni, {name}. La buona notizia è che, siccome il loro veleno è più forte, me ne serviranno di meno. La cattiva è che nella zona meridionale strisciano più specie di creature velenose, quindi dovrai prenderli da più fonti.", "È la nostra ultima occasione per salvare Noggle! Sbrigati!", "Sì! Sembra che funzioni, Noggle si sta riprendendo. Ti dobbiamo un grosso favore!", 0x6331e1ef, 0x4a6d3253, 0xe2d69c0b, 0x048affa9, 0xe66a1541, "....." },
  [8280] = { "Proteggere le linee di rifornimento", "L'evocatore del vento Proudhorn, alla ⟦Cenarion Hold=Fortezza Cenariana⟧ di ⟦Silithus=Silitus⟧, vuole che tu uccida 15 Dredge Striker.", "La ⟦Cenarion Hold=Fortezza Cenariana⟧ è un luogo della massima importanza strategica. Sono convinto che finché la terremo la nostra vittoria sui silitidi sarà assicurata. Sempre che si riesca a mantenere il flusso dei rifornimenti, s'intende.\n\nI vermi del deserto si sono rivelati per le nostre carovane di rifornimenti una minaccia persino maggiore dei silitidi stessi. Proprio stamattina un grosso carico di Morrowgrain è stato devastato da un gruppo di Dredge Striker. Devi sfoltire il loro numero, perché i nostri rifornimenti non siano messi a rischio.", "I Dredge Striker sono una minaccia seria e vanno affrontati in fretta!", "Hai la mia sincera gratitudine. I tuoi sforzi in aiuto della ⟦Cenarion Hold=Fortezza Cenariana⟧ hanno dimostrato vero coraggio.", 0x9beca3f1, 0x3760efd5, 0xfceead9a, 0x939bd353, 0x0f753506, "....." },
  [8281] = { "Rafforzare la sicurezza", "L'invocatore dei venti Proudhorn, alla ⟦Cenarion Hold=Fortezza Cenariana⟧ a ⟦Silithus=Silitus⟧, vuole che tu uccida 20 Dredge Crusher.", "Finora il tuo operato è stato davvero esemplare, {name}. Le nostre linee di rifornimento però non sono ancora del tutto sicure. Senza i Dredge Striker, i loro cugini più grossi del sud verranno di certo a prenderne il posto al nord.\n\nDovrai uccidere parecchi Dredge Crusher per tenerli a bada, ma non possiamo lasciare al caso la sicurezza delle nostre linee di rifornimento.", "I Dredge Crusher sono una minaccia seria e vanno affrontati subito!", "Eccellente! Ti sei dimostrat<o/a> <un/una> alleat<o/a> <prezioso/preziosa> nei preparativi per la guerra contro i silitidi.", 0x57b863d9, 0xd662778f, 0x87d024ec, 0x0478e803, 0x607c7381, "....." },
  [8282] = { "La sacca perduta di Noggle", "Recupera la ⟦Noggle's Satchel=Sacca di Noggle⟧ sulle montagne nel sud di ⟦Silithus=Silitus⟧ e riportagliela alla ⟦Cenarion Hold=Fortezza Cenariana⟧.", "Dove sono? Dov'è la mia borsa? *ansima* Devo averla persa mentre fuggivo da Chelafunesta, lo scorpide gigante. Nella fretta di scappare sono finito dritto in un nido di scorticatori Sferzapietra.\n\nLa sacca che portavo era piena di reagenti rari di ogni tipo. Senza quelli, io e Beetix non potremo preparare le pozioni che servono alla ⟦Cenarion Hold=Fortezza Cenariana⟧. Sono ancora troppo debole per alzarmi, ma se mi riporti i reagenti ne varrà la pena.\n\nMi sono imbattuto in Chelafunesta sulla catena montuosa meridionale, dietro l'Accampamento di Barbabronzea.", "Non hai ancora trovato la mia borsa? Be', dovrei ringraziare la mia buona stella: almeno il veleno è stato eliminato.", "Sì! Mi hai riportato la sacca. E i miei reagenti rari ci sono tutti! Sarò in debito con te per molto tempo.", 0xeeeb4950, 0xea6a7314, 0x5a1c0e0e, 0x8a6d5d7b, 0xc1d43b95, "....." },
  [8283] = { "RICERCATA: Chelafunesta, il terrore delle sabbie", "Porta la ⟦Deathclasp's Pincer=Chela di Chelafunesta⟧ a Vish Kozus, capitano della guardia.", "Si ritiene che il terribile scorpide Chelafunesta si sia ritirato nella catena montuosa meridionale, a causa dell'aumento dell'attività dei silitidi. Costituisce una grave minaccia per le pattuglie e le spedizioni nelle regioni meridionali. Chi contribuirà alla sua distruzione sarà generosamente ricompensato. Per la ricompensa, rivolgersi al capitano Vish Kozus, in cima alla torre di guardia della ⟦Cenarion Hold=Fortezza Cenariana⟧.", "Mi serve la chela della creatura come prova dell'impresa. Niente chela, niente ricompensa.", "Eccellente! Senza Chelafunesta siamo liberi di usare la catena montuosa meridionale come percorso strategico per aggirare gli alveari dei silitidi. Il tuo lavoro è molto apprezzato.", 0x1653fede, 0xc66271b7, 0x2223e285, 0xe70b5da7, 0x42eb7ffd, "....." },
  [8284] = { "Il mistero del Crepuscolo", "La geologa Larksbane, alla ⟦Cenarion Hold=Fortezza Cenariana⟧ di ⟦Silithus=Silitus⟧, vuole che tu raccolga 8 Frammento di Tavoletta del Crepuscolo.", "Un tempo un accampamento di cultisti del ⟦Twilight's Hammer=Martello del Crepuscolo⟧ prosperava a nord-ovest di qui. Se ti ci avventurassi ora, troveresti la zona brulicante di elementali e nient'altro che pezzi sparsi di legno e di tela a indicare il punto in cui sorgeva l'accampamento.\n\nHo recuperato dal sito alcuni frammenti di una tavoletta d'argilla, ma sono troppo pochi per ricavarne qualcosa di utile. Vedi se riesci a trovare i frammenti rimanenti, così potremo fare luce sulla presenza del ⟦Twilight's Hammer=Martello del Crepuscolo⟧ qui a ⟦Silithus=Silitus⟧.", "L'accampamento devastato si trova a nord-ovest di qui. Torna quando avrai tutti i frammenti.", "Proprio come sospettavo. Riesco a decifrare singole parole sulle tavolette, ma sembrano prive di qualsiasi logica o significato. Non è raro che le sette del ⟦Twilight's Hammer=Martello del Crepuscolo⟧ usino un codice per nascondere il senso dei loro testi; dovremo rivolgerci a qualcuno che ne sa di più su questo genere di cose.", 0x36071092, 0x829f9721, 0xd9ad7936, 0x1f849a86, 0x45153e0e, "....." },
  [8285] = { "Il disertore", "Porta la tavoletta restaurata all'eremita Ortell, a ⟦Silithus=Silitus⟧.", "Si dice che un membro del ⟦Twilight's Hammer=Martello del Crepuscolo⟧ di nome Ortell abbia disertato la sua setta. Pare che si sia nascosto sulle montagne a sud di ⟦Southwind Village=Vento del Sud⟧, dove vive da eremita. Forse potresti convincerlo ad aiutarti a decifrare la tavoletta.\n\nPorta con te la tavoletta restaurata e cerca Ortell.", "Tu! Come mi hai trovato? Chi sei? Non ti hanno seguito, vero? Parla!", "Vedo che conosci la mia vecchia organizzazione. Devi essere della ⟦Cenarion Hold=Fortezza Cenariana⟧.\n\nCerchi informazioni da usare contro di loro? Avvicinati, forse possiamo esserci utili a vicenda.", 0xb731c8c4, 0x06d22d8c, 0x8810ae3f, 0xa4e24d3c, 0x12c99ec1, "....." },
  [8287] = { "Uno scopo terribile", "Porta il Decoded Tablet Parchment al comandante Mar'alith.", "Ecco qua... un'informazione piuttosto preziosa, devo dire! Ho visto arrivare a ⟦Silithus=Silitus⟧ le forze del ⟦Cenarion Circle=Circolo Cenariano⟧. Vogliono cacciare il ⟦Twilight's Hammer=Martello del Crepuscolo⟧, vero? Questo li aiuterà.\n\nPorta questa pergamena al loro capo, il comandante Mar'alith. Presto il ⟦Twilight's Hammer=Martello del Crepuscolo⟧ sarà sconfitto e io sarò fuori dalla sua portata per sempre!", "Che cosa mi porti, {name}?", "Sono informazioni davvero molto interessanti, {name}. Gettano un po' di luce sulla presenza del ⟦Twilight's Hammer=Martello del Crepuscolo⟧ a ⟦Silithus=Silitus⟧ e ci aiuteranno senza dubbio nella nostra lotta contro di loro. I tuoi sforzi saranno ricompensati generosamente, {class}.", 0xab3d7b65, 0x56902685, 0x534bf238, 0x69bfaecc, 0x0f045752, "....." },
  [8288] = { "Solo uno potrà ergersi", "Riporta la ⟦Head of the Broodlord Lashlayer=Testa di Fustigor il Signore della Progenie⟧ a Baristolth delle Sabbie Mutevoli, alla ⟦Cenarion Hold=Fortezza Cenariana⟧ di ⟦Silithus=Silitus⟧.", "Non c'è tempo da perdere! Bisogna trovare un eroe! Il compito che ti affido richiederà un esercito per essere portato a termine, ma solo uno potrà ergersi dalla folla degli aspiranti campioni per assumersi il fardello e la responsabilità di alleato della Stirpe.\n\nNella tana del signore di ⟦Blackrock=Roccianera⟧ si cela una bestia crudelissima. Fustigor il Signore della Progenie sorveglia le Halls of Strife e sbarra la strada verso il santuario interno di Nefarian. Uccidi quell'immonda aberrazione e portami la sua testa. Fallo e potrai cominciare la tappa successiva del tuo viaggio.", "È il favore della ⟦Brood of Nozdormu=Stirpe di Nozdormu⟧ che devi guadagnarti.", "Potresti essere tu <il/la> prim<o/a>, dopo mille anni, a guadagnarti il favore dello Stormo dei Draghi di Bronzo?", 0x2d7c676a, 0x9626bfb8, 0x2526ea32, 0x7256fa21, 0xc23d3c6a, "....." },
  [8290] = { "Sconfiggere gli invasori", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Horde=Orda⟧, ottieni un ⟦Warsong Gulch Mark of Honor=Contrassegno d'Onore della Forra dei Cantaguerra⟧ e torna dalla sentinella Farsong al ⟦Silverwing Grove=Boschetto degli Alargentea⟧.", "Oltre questa galleria troverai un campo di lotta e tumulto, giovane {class}. L'⟦Horde=Orda⟧ continua a devastare la nostra foresta sacra, abbattendo i sempreverdi per alimentare le sue macchine da guerra.\n\nEntra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difendi la ⟦Silverwing Hold=Rocca di Alargentea⟧. Respingi le forze d'invasione dell'⟦Horde=Orda⟧!\n\nFallo, e otterrai un talismano al merito. Portami un tale talismano, {name}, e ti ricompenserò.", nil, nil, 0x877db1ee, 0xfeb46d9a, 0xd5134582, nil, nil, "...mm" },
  [8291] = { "Sconfiggi gli invasori!", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Horde=Orda⟧, ottieni le ⟦Silverwing Talisman of Merit=Medaglie al Valore degli Alargentea⟧ e torna dalla sentinella Farsong al ⟦Silverwing Grove=Boschetto degli Alargentea⟧.", "Oltre questa galleria troverai un campo di lotta e tumulto, giovane {class}. L'⟦Horde=Orda⟧ continua a devastare la nostra foresta sacra, abbattendo i sempreverdi per alimentare le sue macchine da guerra.\n\nEntra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difendi la ⟦Silverwing Hold=Rocca di Alargentea⟧. Respingi le forze d'invasione dell'⟦Horde=Orda⟧!\n\nFallo, e otterrai un talismano al merito. Portami un tale talismano, {name}, e ti ricompenserò.", "Hai combattuto nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difeso la ⟦Silverwing Hold=Rocca di Alargentea⟧?", "Hai dimostrato il tuo valore nei nostri sforzi nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧. Continua a sostenere la causa e portami altri contrassegni d'onore. Fallo, e ti guadagnerai ancora di più la nostra fiducia.", 0x55520e44, 0xbdddd230, 0xd5134582, 0x71ff749c, 0xf9915c4e, "....." },
  [8294] = { "Domare gli usurpatori Alargentea", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Alliance=Alleanza⟧, ottieni un Contrassegno d'Onore dei ⟦Warsong=Cantaguerra⟧ e portalo al capitano Shatterskull all'⟦Mor'shan Base Camp=Accampamento Mor'shan⟧.", "Le terre selvagge della foresta di ⟦Ashenvale=Valtetra⟧ cederanno alla potenza dell'⟦Horde=Orda⟧, {race}. Nulla di ciò che gli Alargentea dicono o fanno può fermare il nostro imperativo sovrano. Kalimdor appartiene all'⟦Horde=Orda⟧. Come osano cercare di impedirci di raccogliere ciò che è nostro di diritto!\n\nLascia che l'orgoglio ti gonfi il petto mentre stronchi i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ e ottieni un contrassegno d'onore dei ⟦Warsong=Cantaguerra⟧. Torna da me con un tale contrassegno, {name}, e sarai ricompensat<o/a>.", "Il sangue dei nostri nemici è un contrassegno d'onore. Ce l'hai un contrassegno del genere?", "<Il capitano Shatterskull ruggisce in trionfo.>\n\nQuanto ancora possono resistere? Quanta altra feccia dell'⟦Alliance=Alleanza⟧ deve perire per mano dell'⟦Horde=Orda⟧ prima che si ritirino? Solo il tempo lo dirà, {race}...", 0x636625b4, 0x3df29510, 0x2eb6ef0c, 0xd1cff4b7, 0x160777a5, "....." },
  [8295] = { "Domare gli usurpatori Alargentea", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Alliance=Alleanza⟧, ottieni un ⟦Warsong Gulch Mark of Honor=Contrassegno d'Onore della Forra dei Cantaguerra⟧ e portalo al capitano Shatterskull all'⟦Mor'shan Base Camp=Accampamento Mor'shan⟧.", "Le terre selvagge della foresta di ⟦Ashenvale=Valtetra⟧ cederanno alla potenza dell'⟦Horde=Orda⟧, {race}. Nulla di ciò che gli Alargentea dicono o fanno può fermare il nostro imperativo sovrano. Kalimdor appartiene all'⟦Horde=Orda⟧. Come osano cercare di impedirci di raccogliere ciò che è nostro di diritto!\n\nLascia che l'orgoglio ti gonfi il petto mentre stronchi i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ e ottieni un contrassegno d'onore dei ⟦Warsong=Cantaguerra⟧. Torna da me con un tale contrassegno, {name}, e sarai ricompensat<o/a>.", nil, nil, 0x636625b4, 0xc94c2293, 0x2eb6ef0c, nil, nil, "...mm" },
  [8297] = { "Risorse del ⟦Arathi Basin=Bacino d'Arathi⟧!", "Vinci la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧, ottieni una ⟦Arathi Resource Crate=Cassa di Scorte d'Arathi⟧ e portala al sergente Maclear al ⟦Refuge Pointe=Fosso dei Rifugiati⟧.", "La guerra si combatte con i soldati, te lo dirà qualunque soldato. Ma ti diranno anche che una battaglia combattuta con un equipaggiamento scadente o a stomaco vuoto è persa prima di cominciare!\n\nEcco perché il ⟦Arathi Basin=Bacino d'Arathi⟧ è importante. Nel bacino ci sono zone chiave che custodiscono risorse essenziali. Metalli, armi, cibo, legname: servono tutti, e lì si possono ottenere tutti.\n\nÈ questo che voglio da te, {name}. Entra nel ⟦Arathi Basin=Bacino d'Arathi⟧, vinci la battaglia tenendo più basi del nemico e torna da me con una cassa di risorse.", "Hai i Contrassegni d'Onore, {name}? La ⟦The League of Arathor=Lega di Arathor⟧ non può combattere una battaglia come si deve senza di loro...", "Hai il Contrassegno! Ottimo lavoro! Manderò le risorse ai nostri furieri, che potranno distribuirle in fretta alle truppe.\n\nGrazie, {name}. In effetti, è con missioni riuscite come la tua che si vincono davvero le guerre.", 0xa6f22932, 0x982ec307, 0xfe0a59ea, 0x37247045, 0x2c6df8ea, "....." },
  [8299] = { "Tagliare i rifornimenti degli Arathor", "Vinci la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧, ottieni una ⟦Arathi Resource Crate=Cassa di Scorte d'Arathi⟧ e portala all'⟦Deathstalker=Inseguitore della Morte⟧ Mortis a ⟦Hammerfall=Requie del Martello⟧.", "La ⟦The League of Arathor=Lega di Arathor⟧ non bada a spese nel tentativo di riprendersi Arathi. Loro, e tutte le razze dell'⟦Alliance=Alleanza⟧, ora affluiscono in questa regione lontana, decisi ad allargare il loro dominio a partire dal ⟦Refuge Pointe=Fosso dei Rifugiati⟧. Dobbiamo fermarli, e il modo migliore per farlo è prendere le loro provviste.\n\nPuoi aiutarci, {name}. Entra nel ⟦Arathi Basin=Bacino d'Arathi⟧, noto per le sue ricche miniere, la terra fertile e gli abili artigiani. Conquista e controlla ogni base che puoi, vinci la battaglia e torna da me con le risorse che ottieni.", "Che c'è, {race}? Hai i Contrassegni d'Onore? Torna nel ⟦Arathi Basin=Bacino d'Arathi⟧, uccidi quei parassiti dell'⟦Alliance=Alleanza⟧ e impadronisciti delle loro risorse per la Dama Oscura!", "<L'⟦Deathstalker=Inseguitore della Morte⟧ Mortis sorride>\n\nUn altro colpo decisivo è stato inferto ai nostri nemici, {name}. Grazie alle tue gesta, il ⟦Arathi Basin=Bacino d'Arathi⟧ cadrà presto nelle mani dei Profanatori.", 0x7b8482f8, 0x81501782, 0xd18465ad, 0xd916acfe, 0x18a5b9a3, "....." },
  [8301] = { "La via dei giusti", "Raccogli 200 Frammento di Carapace di Silitide e torna da Baristolth.", "La ⟦Brood of Nozdormu=Stirpe di Nozdormu⟧ diffida per natura delle razze inferiori. Anche se mi hai dimostrato di avere la stoffa per diventare un eroe, è giunto il momento di dimostrarlo al mio signore.\n\nAlveare Ashi, ⟦Hive'Zora=Alveare Zora⟧, ⟦Hive'Regal=Alveare Regal⟧: brulicano tutti di attività e sono tutti una minaccia per la nostra esistenza. Uccidi i silitidi in questi alveari e prendi loro un frammento del carapace. Quando non potrai portarne altri, torna da me e rafforzerò la tua determinazione.", "La loro diffidenza verso le razze mortali affonda le radici in una lunga storia; ma ahimè, è un racconto che è meglio lasciar narrare alla Stirpe quando sarà il momento.", "Non sei sol<o/a>, <eroe/eroina>. Ora ti concederò il potere di nominare altri come tuoi delegati, perché ti aiutino nella tua impresa. Se vuoi essere <il/la> <campione/campionessa> del tuo popolo, avrai bisogno di aiuto nei tuoi compiti e nei tuoi doveri.", 0xf26e0d53, 0xff84c0eb, 0xc53eafdd, 0xb2f9b35d, 0x13bca8e3, "....." },
  [8303] = { nil, "Cerca Anachronos alle ⟦Caverns of Time=Caverne del Tempo⟧, a Tanaris.", "È il momento, {name}.\n\nDevo scusarmi per averti tenuto nascoste tante cose. I nemici sono ovunque, persino sotto il nostro naso. Ti prego, leggi questo tomo e impara. Prendi la conoscenza che ti do e cerca il nostro signore.", nil, "Sei la speranza di Kalimdor, {name}.", 0x822118f5, 0xcdc07b9b, 0x3578c621, nil, 0x9baa6b7d, "e..m." },
  [8304] = { "Carissima Natalia", "Il comandante Mar'alith, alla ⟦Cenarion Hold=Fortezza Cenariana⟧ di ⟦Silithus=Silitus⟧, vuole che tu interroghi gli abitanti dell'Accampamento di Barbabronzea. Troverai l'Accampamento di Barbabronzea a sud della ⟦Cenarion Hold=Fortezza Cenariana⟧.\n\nQuando avrai raccolto le informazioni richieste, torna dal comandante Mar'alith.", "La mia cara Natalia è scomparsa.\n\nA dire il vero, nelle settimane prima della sua scomparsa si comportava in modo strano. Più di una volta l'avevo sorpresa a parlare da sola quando non c'era nessuno. Insisteva che andava tutto bene e che doveva poter continuare le sue ricerche.\n\nL'ultima volta è stata vista dirigersi verso l'accampamento di Barbabronzea, a sud.\n\nI miei soldati sono sparpagliati ovunque, {name}. Ho bisogno che tu vada all'accampamento di Barbabronzea e interroghi quei nani.", "Non perdere tempo, {name}!", "<Il comandante Mar'alith china il capo, assorto.>\n\nChe sia viva o morta, devo fare ciò che è giusto. Bisogna trovarla. Ahimè, il dovere mi lega a questo avamposto. Mi aiuterai ancora una volta, {name}?", 0x58c44a73, 0x84359a18, 0x70d8d99d, 0x134e1531, 0x45e4d791, "....." },
  [8305] = { "Ricordi a lungo dimenticati", "Trova il Crystalline Tear a ⟦Silithus=Silitus⟧ e scruta nelle sue profondità.", "Nel deserto meridionale di ⟦Silithus=Silitus⟧, vicino alla barriera sacra, esiste un'unica lacrima cristallina. Questa lacrima è il simbolo delle grandi perdite che ci colpirono durante la Guerra delle Sabbie Mutevoli. Trova la lacrima e scruta nelle sue profondità per ricevere l'illuminazione.", nil, "Senti un grande dolore che avvolge questo cristallo. La sua forza è così potente che ti sembra di poter crollare e morire di tristezza.", 0xcf17fd6d, 0xceca852c, 0xa70f56fe, nil, 0x6eaab3a2, "...m." },
  [8306] = { "Nelle fauci della follia", "Il comandante Mar'alith, alla ⟦Cenarion Hold=Fortezza Cenariana⟧ di ⟦Silithus=Silitus⟧, vuole che tu trovi la sua amata Natalia. Le informazioni che hai raccolto indicano l'⟦Hive'Regal=Alveare Regal⟧, a sud, come il luogo in cui potresti trovare la signora Natalia Mar'alith.\n\nNon dimenticare di passare dai nani dell'accampamento di Barbabronzea prima di avventurarti nell'alveare. Potrebbero avere altro lavoro e qualche consiglio per te.\n\nE {name}, ricorda le parole del comandante: \"Fa' ciò che devi...\"", "Ho bisogno che tu entri nell'⟦Hive'Regal=Alveare Regal⟧ e scopra che fine ha fatto la mia carissima Natalia, {name}. Non sarà un compito facile da affrontare da sol<o/a>. Ti consiglio di portare qualche amico. Prima di tuffarti a capofitto nelle fauci della follia, assicurati di tornare a parlare con quei nani. Potrebbero darti qualche consiglio su come affrontare i silitidi che abitano quell'alveare.\n\nE {name}, se è davvero folle come dicono... fa' ciò che devi.\n\n<Il comandante Mar'alith si volta.>", nil, "<Il comandante Mar'alith si stringe il petto.>\n\nC'Thun? Che COSA significa tutto questo? Che cos'è C'Thun? Come ha potuto questo demonio trasformare la mia dolce Natalia nel mostro che hai descritto?", 0x92ee9669, 0x7e346e82, 0x892f7d43, 0x898460ac, 0x0a355935, "...e." },
  [8307] = { "Una ricetta del deserto", "Cerca informazioni su come cucinare la ⟦Sandworm Meat=Carne di Vermisabbio⟧ nell'accampamento del ⟦Twilight's Hammer=Martello del Crepuscolo⟧ a ovest della ⟦Cenarion Hold=Fortezza Cenariana⟧.", "Adattarmi alla vita nel deserto è stato difficile, a dir poco. Non solo mi mancano gli uccelli e gli alberi di Auberdine, ma questo ambiente arido limita molto la scelta del cibo. Sto cercando di imparare qualcosa sulle erbe del deserto, ma non ce ne sono molte.\n\nHo visto gruppi del ⟦Twilight's Hammer=Martello del Crepuscolo⟧, dall'accampamento a ovest di qui, cacciare vermisabbio per mangiarli. Però la carne di vermisabbio è così amara che non riesco a immaginare come la rendano commestibile. Tieni gli occhi aperti se vai al loro accampamento, e fammi sapere se scopri qualcosa.", nil, "Questo libro contiene parecchie ricette comuni e qualcuna insolita. Dopo averlo sfogliato per qualche secondo, noti una ricetta a base di carne di vermisabbio.", 0x7843e85a, 0x74626aa7, 0x3f91f730, nil, 0x0a87d34d, "...m." },
  [8308] = { "⟦Brann Bronzebeard's Lost Letter=Lettera Perduta di Brann Barbabronzea⟧", "Porta la lettera di Brann Bronzebeard all'Accampamento di Barbabronzea, nel sud di ⟦Silithus=Silitus⟧.", "A chi di dovere,\n\nse stai leggendo questa lettera, sono morto o sto per morire. Difficile dirlo. Comunque la maggior parte della squadra è morta.\n\nTrovate informazioni su un ⟦Titan=Titano⟧. Grande battaglia tra lui e un Dio Antico. Sì, un Dio Antico in carne e ossa. Trovato un antico tunnel che porta ad ⟦Ahn'Qiraj=Ahn'qiraj⟧. Lo prendo.\n\nPorta questa lettera al mio vecchio accampamento. Assicurati che la mia scimmia riceva cibo, acqua e abbracci a sufficienza.\n\n-Brann Bronzebeard, Esploratore Estremo\n\nP.S. Attenzione all'elfa della notte pazza che adora un Dio Antico.", "Oh, cielo.", "Be', questo spiega parecchie cose. Se mai trovi un modo per entrare ad ⟦Ahn'Qiraj=Ahn'qiraj⟧, tieni d'occhio il vecchio Brann. Temo che senza la sua scimmia sarà impotente.", 0x56f9f5ee, 0x21723bc0, 0x7ece6adf, 0x9e26ead5, 0x9eac4d41, "....." },
  [8309] = { "A caccia di glifi", "Rutgar Glyphshaper, all'Accampamento di Barbabronzea a ⟦Silithus=Silitus⟧, vuole che tu ti avventuri nell'⟦Hive'Ashi=Alveare Ashi⟧, nell'⟦Hive'Zora=Alveare Zora⟧ e nell'⟦Hive'Regal=Alveare Regal⟧ e recuperi le copie dei glifi dai cristalli con glifi di ciascun alveare.\n\nUsa il ⟦Geologist's Transcription Kit=Corredo da Trascrizione del Geologo⟧ per fare una copia fedele degli antichi glifi. Torna da Rutgar Glyphshaper quando avrai finito.", "Dopo la nostra prima incursione negli alveari e la conseguente follia della signora Mar'alith, i tre alveari sputano fuori insetti a non finire! L'aumento dell'attività potrebbe essere legato ai glifi che coprono quegli strani cristalli.\n\nDobbiamo ricavare una copia dai cristalli di tutti e tre gli alveari. Se riusciamo a ottenere quelle copie, forse potremo dare un senso a questa follia.\n\nPrendi questo corredo da trascrizione e qualche compagno e fai irruzione in quegli alveari, {name}. Non tornare finché non avrai le copie di ogni alveare.", "Se trovi una ragazza elfa della notte pazza in uno degli alveari, dalle un bel calcio nel sedere da parte nostra.", "Non riesco a cavare un ragno dal buco con questi glifi. Non ho mai visto niente del genere! Spero che le ricerche di Frankal gettino un po' di luce su questo pasticcio.", 0x259096b4, 0xb9b32741, 0x18f11d97, 0x68af550c, 0x5b85f00d, "....." },
  [8310] = { "Decifrare il codice", "Frankal Stonebridge, all'Accampamento di Barbabronzea a ⟦Silithus=Silitus⟧, vuole che tu recuperi un ⟦Hive'Zora Silithid Brain=Cervello di Silitide dell'Alveare Zora⟧, un ⟦Hive'Ashi Silithid Brain=Cervello di Silitide dell'Alveare Ashi⟧ e un ⟦Hive'Regal Silithid Brain=Cervello di Silitide dell'Alveare Regal⟧. Torna da Frankal quando avrai finito.", "Credo di poter preparare un elisir che ci permetta di decifrare più facilmente i glifi e la lingua dei silitidi e dei Qiraji! Cosa mi serve? Bella domanda! Mi servono cervelli! Più precisamente, un cervello di ogni tipo di silitide che abita gli alveari. Portami dei cervelli e forse il lavoro di Rutgar non sarà stato inutile.", "Va' a giocare con la scimmia, ragazz<o/a>. Non ho tempo per queste cose.", "Fantastico! Non allontanarti troppo, ragazz<o/a>. Potremmo aver bisogno che tu ti occupi di un altro compito o due.", 0xd4cb0cb3, 0x3f424a96, 0xd70a8818, 0xbce22f01, 0x08090859, "....." },
  [8311] = { "Dolcetti della Veglia delle Ombre per Jesper!", "Parla con i locandieri di ⟦Stormwind=Roccavento⟧, ⟦Ironforge=Forgiardente⟧ e Darnassus, e con Talvash del Kissel a ⟦Ironforge=Forgiardente⟧. Esegui gli scherzetti che ti chiedono in cambio dei dolcetti che offrono.\n\nTorna da Jesper all'orfanotrofio di ⟦Stormwind=Roccavento⟧ con un ⟦Darnassus Marzipan=Marzapane di Darnassus⟧, una ⟦Gnomeregan Gumdrop=Caramella Gommosa di Gnomeregan⟧, un ⟦Stormwind Nougat=Torrone di Roccavento⟧ e una ⟦Ironforge Mint=Mentina di Forgiardente⟧.", "Vorrei andare a fare dolcetto o scherzetto, ma non posso perché sono malato. Se ci vai tu al posto mio, ti scambio le caramelle che raccogli con alcune che ho già! Penso che queste caramelle ti piaceranno: ti trasformano in cose buffe e spaventose!\n\nTutti i locandieri delle grandi città hanno caramelle da dare per la Veglia delle Ombre: parla con loro e fai gli scherzetti che ti chiedono! E poi c'è un piccolo gnomo di nome Talvash, a ⟦Ironforge=Forgiardente⟧, che distribuisce caramelle anche lui. Quando avrai tutte le caramelle, riportamele qui!", "Hai finito di fare dolcetto o scherzetto? Mi dispiace non poterci andare perché sono malato, ma il tuo aiuto mi fa sentire un po' meglio...", "Wow, li hai presi tutti! Sei fantastic<o/a>!\n\nGrazie per aver fatto dolcetto o scherzetto per me. Ecco, prendi questi dolcetti alla zucca: penso che ti piaceranno un sacco!\n\nBuona Veglia delle Ombre, {name}!", 0x52c1029c, 0xf583861b, 0x4f387161, 0xee372d69, 0xc67a4faf, "....." },
  [8312] = { "Dolcetti della Veglia delle Ombre per Spoops!", "Parla con i locandieri di Orgrimmar, ⟦Undercity=Sepulcra⟧ e ⟦Thunder Bluff=Picco del Tuono⟧, e con Kali Remik al ⟦Sen'jin Village=Villaggio di Sen'jin⟧. Esegui gli scherzetti che ti chiedono in cambio dei dolcetti che offrono.\n\nTorna da Spoops all'orfanotrofio di Orgrimmar con un ⟦Thunder Bluff Marzipan=Marzapane di Picco del Tuono⟧, una ⟦Darkspear Gumdrop=Caramella Gommosa dei Lanciascura⟧, un ⟦Orgrimmar Nougat=Torrone di Orgrimmar⟧ e una ⟦Undercity Mint=Mentina di Sepulcra⟧.", "Vorrei andare a fare dolcetto o scherzetto, ma non posso perché sono malato. Se ci vai tu al posto mio, ti scambio le caramelle che raccogli con alcune che ho già! Penso che queste caramelle ti piaceranno: ti trasformano in cose buffe e spaventose!\n\nTutti i locandieri delle grandi città hanno caramelle da dare per la Veglia delle Ombre: parla con loro e fai gli scherzetti che ti chiedono! E poi c'è un troll di nome Kali Remik, al ⟦Sen'jin Village=Villaggio di Sen'jin⟧, che distribuisce caramelle anche lui. Quando avrai tutte le caramelle, riportamele qui!", "Hai finito di fare dolcetto o scherzetto? Mi dispiace non poterci andare perché sono malato, ma il tuo aiuto mi fa sentire un po' meglio...", "Wow, li hai presi tutti! Sei fantastic<o/a>!\n\nGrazie per aver fatto dolcetto o scherzetto per me. Ecco, prendi questi dolcetti alla zucca: penso che ti piaceranno un sacco!\n\nBuona Veglia delle Ombre, {name}!", 0x356246fa, 0xb4c3c494, 0xc588d4fb, 0xee372d69, 0xc67a4faf, "....." },
  [8313] = { "Condividere il sapere", "Porta la ⟦Torn Recipe Page=Pagina Strappata del Ricettario⟧ a Calandrath, alla locanda della ⟦Cenarion Hold=Fortezza Cenariana⟧.", "La ricetta per cucinare la carne di vermisabbio è leggibile, ma cita erbe e spezie di cui non hai mai sentito parlare. Forse Calandrath conosce abbastanza le piante che crescono nel deserto da capirci qualcosa.", "Hai imparato la ricetta? Spero che non te la terrai per te!", "Diamo un'occhiata...\n\nSembra abbastanza semplice. Per alcune erbe usano nomi tutti loro, ma non è difficile capire quali siano. Ecco, lascia che ti mostri!", 0x7d8138bc, 0xc1449f9f, 0xe87c28b0, 0x91af6a8c, 0xde68a832, "....." },
  [8314] = { "Svelare il mistero", "Rutgar Glyphshaper, all'Accampamento di Barbabronzea, vuole che tu consegni il ⟦Glyphed Crystal Prism=Prisma di Cristallo con Glifi⟧ alla geologa Larksbane, alla ⟦Cenarion Hold=Fortezza Cenariana⟧ di ⟦Silithus=Silitus⟧.", "Siamo a un passo da una scoperta, {name}! Le copie che hai recuperato ci hanno permesso di ricreare i glifi su questo prisma di cristallo. A quanto pare servono ai Qiraji e ad altre entità sconosciute per comunicare vari messaggi ai silitidi.\n\nPurtroppo è tutto ciò che siamo riusciti a ricavare dai glifi. Dobbiamo trovare un modo per sbloccare i messaggi nascosti nei cristalli.\n\nPorta il prisma di cristallo con glifi alla geologa Larksbane, alla ⟦Cenarion Hold=Fortezza Cenariana⟧. Forse lei può aiutarci.", "Oh, cielo! Che cos'hai lì, {name}?", "I nani non riuscivano a decifrare i glifi perché non c'è niente da decifrare. Lo strato esterno mobile del prisma deve allinearsi correttamente con i segni del cristallo interno perché il messaggio venga trasmesso. Ingegnoso...\n\nAnche se dovremmo riuscire a tradurre questi dati, prima dobbiamo sbloccare il codice. Sulla superficie del prisma c'è un solo indizio, ammesso che le copie siano state trasferite correttamente, e non promette nulla di buono.", 0x315cbd5b, 0xc8213121, 0x24ba33a6, 0x7bcfced9, 0x62edee0d, "....." },
  [8315] = { "Il richiamo", "La geologa Larksbane, alla ⟦Cenarion Hold=Fortezza Cenariana⟧ di ⟦Silithus=Silitus⟧, vuole che tu recuperi il ⟦Crystal Unlocking Mechanism=Meccanismo di Sblocco di Cristallo⟧ dal Qiraji Emissary.\n\nTi è stato chiesto di portare i ⟦Glyphs of Calling=Glifi del Richiamo⟧ alle ⟦Bones of Grakkarond=Ossa di Grakkarond⟧, a sud della ⟦Cenarion Hold=Fortezza Cenariana⟧, e di tracciarli nella sabbia. Se il Qiraji Emissary dovesse comparire, uccidilo e recupera il ⟦Crystal Unlocking Mechanism=Meccanismo di Sblocco di Cristallo⟧. Se ci riesci, torna dalla geologa Larksbane.\n\nRaduna un esercito per questo compito, {name}!", "I glifi mostrano un emissario dei Qiraji che incontra tre silitidi presso le ossa di un grande drago. Sopra i glifi c'è quello che posso solo supporre sia una specie di codice. Questo codice potrebbe benissimo essere la chiave per evocare l'emissario.\n\nCreerò una copia del codice dei glifi, che dovrai tracciare nella sabbia alle ⟦Bones of Grakkarond=Ossa di Grakkarond⟧. Se ho ragione, i signori supremi arriveranno pensando che ci siano nuovi dati pronti da trasmettere. Abbattili e affronta l'emissario. È lui che ha la chiave dei cristalli...", "Devi cogliere l'occasione quando si presenta e colpire!", "Ho tra le mani 20.000 anni di storia, {name}!", 0x0fadee9b, 0x53eef4e3, 0x39406323, 0x932486cd, 0xcda7abbd, "....." },
  [8316] = { "Armamenti di guerra", nil, nil, nil, "La guerra si avvicina, {name}, e con essa orrori indicibili. Hai fatto tutto ciò che ti si poteva chiedere, e per questo meriti una ricompensa.\n\nSe questa... questa profezia dovesse mai avverarsi...\n\n<La geologa Larksbane impallidisce.>\n\nIl futuro di tutti noi potrebbe giungere alla fine.\n\nQuesti armamenti si riveleranno preziosissimi per la tua campagna in questo deserto.", 0x9aacc572, nil, nil, nil, 0x7f77ec54, ".mmm." },
  [8317] = { "Un aiuto in cucina", "Calandrath, alla ⟦Cenarion Hold=Fortezza Cenariana⟧, ha bisogno di 10 ⟦Smoked Desert Dumplings=Gnocchi di Verme Affumicati⟧.", "Quella ricetta tornerà proprio utile. Sarà meglio che mi metta al lavoro, così avrò degli gnocchi di verme affumicati pronti per oggi. Mi farebbe comodo una mano a prepararli: saprò ricompensarti.", "Come vanno quegli gnocchi?", "Eccellente! Mi hai salvato la vita. Questi gnocchi sono venuti proprio buoni. Non mi aspettavo tanto buon gusto dal ⟦Twilight's Hammer=Martello del Crepuscolo⟧.", 0x34700d3b, 0x467ee680, 0x1a909fbf, 0x1999061b, 0x9febcb59, "....." },
  [8318] = { "Comunicazioni segrete", "Porta 10 Testo Crepuscolare Codificato a Bor Wildmane, alla ⟦Cenarion Hold=Fortezza Cenariana⟧.", "Alcuni cultisti del ⟦Twilight's Hammer=Martello del Crepuscolo⟧ si portano dietro dei foglietti pieni di scarabocchi senza senso. Voglio che tu me ne porti una pila, {class}.\n\nNon riesco a capire cosa vogliano dire, ma non è questo il punto! Con questi fogli i loro vari gruppi comunicano in segreto. Più testi togliamo dalla circolazione, meno potranno comunicare!", "Mi hai portato dei testi?", "Eccellente! Li metterò da parte, magari torneranno utili più avanti.", 0xcc494cd2, 0x5c6002b3, 0xefa328b9, 0x1713c156, 0x59845fa1, "....." },
  [8320] = { "I geosignori del Crepuscolo", "Uccidi 10 Twilight Geolord, poi torna da Huum Wildmane alla ⟦Cenarion Hold=Fortezza Cenariana⟧.", "Il ⟦Twilight's Hammer=Martello del Crepuscolo⟧, un culto folle votato alla distruzione, ha piantato i suoi accampamenti a ⟦Silithus=Silitus⟧ e compie rituali giorno e notte. Non conosciamo ancora i loro piani, ma pensiamo che siano in qualche modo legati ai cristalli rossi pulsanti sparsi per il deserto.\n\nAnche se un giorno il loro mistero potrebbe essere svelato, prima dobbiamo affrontare la minaccia immediata. Va' ai loro accampamenti a ovest e cerca i geosignori del Crepuscolo. Sono le teste di queste serpi: è lì che dobbiamo colpire!", "Addentrati nel deserto e trova i geosignori del Crepuscolo, {name}. Torna da me dopo averli uccisi.", "Un compito svolto bene, {name}. L'uccisione dei geosignori del Crepuscolo dev'essere stata un duro colpo per il culto. Speriamo che i loro piani rallentino...", 0x4a8a9dd6, 0xf3c8c0c8, 0x7b7b95be, 0x776cba1a, 0x16794f7f, "....." },
  [8321] = { "Vyral il Vile", "Porta l'⟦Vyral's Signet Ring=Anello con Sigillo di Vyral⟧ a Huum Wildmane, alla ⟦Cenarion Hold=Fortezza Cenariana⟧.", "Abbiamo scoperto un'altra base operativa del ⟦Twilight's Hammer=Martello del Crepuscolo⟧. Si chiama ⟦Twilight's Run=Grotta del Crepuscolo⟧ ed è una caverna nascosta nell'angolo nord-orientale di ⟦Silithus=Silitus⟧. Il capo locale del culto, Vyral il Vile, infesta quella caverna: è lui che dovrai sconfiggere ora. Quando ci sarai riuscit<o/a>, portami il suo anello con sigillo.\n\nChe la fortuna ti accompagni, {name}. Gli orrori della ⟦Twilight's Run=Grotta del Crepuscolo⟧ sono davvero temibili.", "{name}, hai già sconfitto Vyral il Vile? Hai il suo anello con sigillo?", "Ce l'hai fatta! Vyral è morto! Questo non può che significare la rovina per le operazioni del Martello del Crepuscolo a ⟦Silithus=Silitus⟧. Forse ce ne sono ancora altri che si aggirano in giro, ma il colpo che hai inferto oggi al culto è di quelli da cui non si riprenderanno facilmente.", 0xaa8e73ba, 0x5a2d88b7, 0x78859cd1, 0xacfae899, 0x7b7437ca, "....." },
  [8322] = { "⟦Rotten Eggs=Uova Marce⟧", "Metti le ⟦Rotten Eggs=Uova Marce⟧ nel barile di birra principale, dentro la locanda di ⟦Southshore=Riva del Sud⟧.", "Gli umani di ⟦Southshore=Riva del Sud⟧ adorano la loro birra, e per questo tengono moltissimo a quella servita alla locanda di ⟦Southshore=Riva del Sud⟧. Con il caos della Veglia delle Ombre ormai alle porte, possiamo approfittarne per rovinare la loro ultima partita di bevande per settimane, se non per mesi!\n\nPrendi queste uova marce e mettile nel barile di birra principale, dentro la locanda di ⟦Southshore=Riva del Sud⟧. Già la tua sola presenza scatenerà un putiferio, quindi preparati a difenderti!\n\nQuando avrai dato a ⟦Southshore=Riva del Sud⟧ un assaggio che non dimenticherà presto, torna da me qui alla festa!", "Il barile è pieno di birra.", "Dopo esserti fatt<o/a> strada combattendo fin dentro la locanda, metti le uova nel barile. Senti il fetore che impregna l'aria...", 0x4f60af90, 0x6cdb041f, 0x402db487, 0xa6ca951a, 0xce03c268, "....." },
  [8323] = { "Veri credenti", "L'eremita Ortell vuole che tu gli porti 10 Testo Crepuscolare Codificato", "Ora che ho il Dizionario del Crepuscolo, vorrei chiederti un piccolo favore.\n\nLa mia vecchia organizzazione fa circolare ogni mese un bollettino segreto in codice.\n\nSe fanno progressi nella loro caccia contro di me, o se la sospendono, la notizia sarà pubblicata sul Vero Credente.\n\nAnche se queste informazioni sono ovviamente preziose per me, la pubblicazione contiene altre notizie utili che posso condividere. Portami tutti i testi codificati che trovi addosso ai membri del ⟦Twilight's Hammer=Martello del Crepuscolo⟧.", "Hai trovato dei testi codificati? Sono proprio curioso di leggere il Vero Credente di questo mese.", "Eccellente! Mi metterò a decifrarli il prima possibile. Se trovo qualcosa di interessante, troverò il modo di fartelo sapere.", 0x434403a9, 0x9ae5220c, 0x74ecfba2, 0x4afa1bcf, 0xf07c403b, "....." },
  [8331] = { nil, "Parla con Aurel Goldleaf alla ⟦Cenarion Hold=Fortezza Cenariana⟧.", "{name}, speravamo che le operazioni del Martello del Crepuscolo a ⟦Silithus=Silitus⟧ stessero rallentando... ma purtroppo ci sbagliavamo. Grazie alle continue incursioni contro il culto, abbiamo scoperto che un potere ancora più oscuro, l'Abyssal Council, controlla il Martello attraverso le pietre del vento arcane sparse tra gli accampamenti del culto. La tua prossima azione, {name}, sarà contro l'Abyssal Council.\n\nParla con l'artigiana Aurel Goldleaf, nella parte orientale della ⟦Cenarion Hold=Fortezza Cenariana⟧. Per questa prossima mossa servirà la sua abilità.", nil, "{name}, buongiorno. Mi hanno detto che affronterai l'Abyssal Council. Se è così, ascolta bene le mie prossime parole...", 0x1df6d82e, 0x00d99f06, 0x9ee316b2, nil, 0x5b91bb58, "e..m." },
  [8332] = { "I duchi del concilio", "Porta 1 ⟦Large Brilliant Shard=Frammento Splendente Grande⟧ e 3 Abyssal Crest ad Aurel Goldleaf, alla ⟦Cenarion Hold=Fortezza Cenariana⟧.", "Pensiamo che sia possibile usare una pietra del vento per tendere un'imboscata a un duca dell'Abyssal Council. Per farlo, però, bisogna comunicare attraverso la pietra del vento e convincere il concilio di essere un capo di medio rango del ⟦Twilight's Hammer=Martello del Crepuscolo⟧.\n\nUna mossa simile richiede una copia del medaglione della ricezione del culto. Posso creare il medaglione, ma mi serviranno un frammento splendente grande e le insegne indossate dagli Abyssal Templar.\n\nPortami queste cose e al resto penserò io.", "Hai il frammento e le insegne, {name}? Mi servono per creare il medaglione della ricezione dei cultisti del Crepuscolo.", "Ah, molto bene. Stavo lavorando al medaglione: ora, con questi ultimi ingredienti, avrò finito in pochi istanti...\n\nEcco fatto. Ecco il medaglione, {name}.\n\nDovrai indossarlo quando attiverai una delle pietre del vento del Martello del Crepuscolo. Indossalo insieme al resto dei paramenti del Crepuscolo, e l'Abyssal Council ti scambierà per uno dei suoi cultisti sottoposti.", 0xf889dd83, 0xc49a16ec, 0xbc8d35c2, 0x5f3a2d03, 0xf6a2e4a0, "....." },
  [8341] = { "I signori del concilio", "Porta 5 Frammento Splendente Grande e 3 Anello con Sigillo Abissale ad Aurel Goldleaf, alla ⟦Cenarion Hold=Fortezza Cenariana⟧.", "I signori dell'Abyssal Council possono essere evocati solo attraverso le pietre del vento superiori, e solo i membri di rango più alto del Twilight's Council possono parlare con loro. Ma... ho trovato un modo per migliorare il tuo travestimento e ingannare gli Abyssal Lord!\n\nIl travestimento richiede un anello del comando, portato solo dai membri più alti del culto. Te ne forgerò uno se mi porterai dei frammenti splendenti grandi e degli anelli con sigillo abissali.", "Hai i frammenti e gli anelli con sigillo, {name}? Mi servono per creare l'anello del comando.", "Grazie. Un attimo solo e il tuo anello sarà pronto...\n\nEccolo. Ora sei pront<o/a>.\n\nAssicurati di indossare questo anello, insieme a un medaglione della ricezione e al resto dei paramenti del Crepuscolo, quando attiverai una pietra del vento superiore. Fallo, e l'Abyssal Council ti crederà uno dei suoi servitori. Allora, forse, potrai attirarne uno in un'imboscata!", 0x1a3e1df3, 0xc80f03d3, 0xaab9abe2, 0x7d648603, 0xac008b57, "....." },
  [8343] = { "La scoperta di Goldleaf", "Parla con Aurel Goldleaf alla ⟦Cenarion Hold=Fortezza Cenariana⟧.", "{name}, Aurel Goldleaf pensa di aver trovato un modo per evocare e sconfiggere un membro dominante dell'Abyssal Council! Sarà un compito pericoloso, ma ti sei guadagnat<o/a> grande rispetto presso il ⟦Cenarion Circle=Circolo Cenariano⟧. Sappiamo che se qualcuno può farcela, quel qualcuno sei tu.\n\nChe la fortuna ti accompagni, {name}. Parla con Aurel quando sarai pront<o/a>.", nil, "Huum dice il vero. Credo di sapere come evocare un signore dell'Abyssal Council! Ascolta, e ti spiegherò...", 0x7d06092e, 0x00d99f06, 0x94672e87, nil, 0x9a7b0a81, "...m." },
  [8348] = { "Il sigillo dei duchi", "Porta l'⟦Abyssal Signet=Anello con Sigillo Abissale⟧ a Bor Wildmane, alla ⟦Cenarion Hold=Fortezza Cenariana⟧.", "Huum mi dice che hai capito come evocare gli Abyssal Duke! È una bella impresa.\n\nSai cos'altro sarebbe una bella impresa? Fare a pezzi per bene una di quelle cose. Così i loro sottoposti si faranno un'idea, se capisci cosa intendo. Portami il suo anello con sigillo come prova dell'impresa.", "Com'è andata con l'Abyssal Duke? Picchiava duro?", "Ho capito che eri <un/una> {class} con la scorza dura nel momento in cui ti ho vist<o/a> entrare nella ⟦Cenarion Hold=Fortezza Cenariana⟧. Continua così!", 0xa8c6f6c8, 0xf6ee6096, 0x2ae1a524, 0xa61739e1, 0x8abe4588, "....." },
  [8349] = { nil, "Parla con Bor Wildmane alla ⟦Cenarion Hold=Fortezza Cenariana⟧.", "Ora che hai un medaglione e puoi evocare un Abyssal Duke, parla con Bor Wildmane. Ti affiderà un compito contro l'Abyssal Council.\n\nBuona fortuna, {name}. E se ti serviranno altri medaglioni, torna da me.", nil, "Felice di rivederti, {class}! Allora ti sei fatt<o/a> fare un medaglione? Bene: ti servirà per la tua prossima missione...", 0xc71f0889, 0xed9857d3, 0xaa46e222, nil, 0x03634dd9, "e..m." },
  [8351] = { "Bor vuole parlarti", "Parla con Bor Wildmane alla ⟦Cenarion Hold=Fortezza Cenariana⟧.", "Ora che puoi travestirti da membro dominante del Twilight Council, sono certa che Bor Wildmane vorrà parlarti. Va' da lui e preparati a una missione molto difficile...", nil, "Sì, esatto, {name}. Ti aspetta un compito molto duro...", 0x9e79a2ab, 0xed9857d3, 0x84b44369, nil, 0x19d6e4b2, "...m." },
  [8352] = { "Lo scettro del concilio", "Porta uno ⟦Abyssal Scepter=Scettro Abissale⟧ a Bor Wildmane, alla ⟦Cenarion Hold=Fortezza Cenariana⟧.", "Huum e io stavamo proprio parlando di te. Mi dice che sei quasi pront<o/a> a cimentarti contro un Abyssal Lord!\n\nDevo dirti che è un'impresa molto pericolosa. Faresti meglio a portarti dei rinforzi. E non parlo di uno o due amici, parlo di una forza di combattimento di prim'ordine, pronta alla battaglia. Se i tuoi amici sono bravi quanto te, potreste persino sconfiggerlo!\n\nSe ci riuscirai, e come sempre vorrò delle prove, ti darò una ricompensa davvero grande.", "Allora, com'è andata? Darei qualsiasi cosa per lasciare il mio posto e lottare io stesso con una di quelle cose!", "Tu... ce l'hai fatta! Ce l'hai fatta, {name}! Ecco! Prendi questo. È il forziere più grande che avessimo in giro e l'ho riempito con un po' della roba migliore che abbiamo trovato.", 0x9215b008, 0xf0fb4cb2, 0x271213d0, 0xda78e943, 0xece272ca, "....." },
  [8361] = { "Contatti abissali", "Bor Wildmane, alla ⟦Cenarion Hold=Fortezza Cenariana⟧ di ⟦Silithus=Silitus⟧, vuole che tu distrugga un Abyssal Templar e gli porti un Abyssal Crest come prova dell'impresa.", "Abbiamo visto i cultisti del ⟦Twilight's Hammer=Martello del Crepuscolo⟧ compiere rituali per evocare potenti nobili elementali. Non sappiamo se siano gli esseri che i cultisti adorano o se facciano da intermediari per forze ancora più potenti. Una cosa è certa: ricevono ordini da questi elementali.\n\nVoglio che tu trovi un modo per contattare un Abyssal Templar e dargli una bella lezione! Niente getta le truppe nello scompiglio come eliminare la catena di comando. E già che ci sei, portami una prova.", "Hai finito il lavoro?", "Ah! Ce l'hai fatta, {name}! Il ⟦Twilight's Hammer=Martello del Crepuscolo⟧ sarà presto schiacciato!", 0xb08857d9, 0x172cfbe4, 0x8438e952, 0x1650733d, 0x5b14bd4d, "....." },
  [8365] = { "Cappelli da pirata, ohoi!", "Haughty Modiste vuole che tu raccolga 20 Cappello da Pirata dei Mari del Sud e glieli riporti al ⟦Steamwheedle Port=Porto degli Spargifumo⟧, a Tanaris.", "Sei tu l'aiuto che ha mandato il Cartello? Immagino che andrai bene. Ascolta attentamente, {class}. Come sai, procuro abiti alla moda per l'élite della società di Azeroth. Re e regine, Capoguerra e, be', come diavolo l'⟦Horde=Orda⟧ chiama le sue regine, indossano tutti ciò che io decido sia di moda. E lo pagano a peso d'oro, che è la parte migliore.\n\nEcco cosa succederà. Andrai alla ⟦Lost Rigger Cove=Cala del Sartiame⟧ e ti procurerai un bel po' di cappelli da pirata, con qualunque mezzo. Pensi di farcela?", "Hai tutti e 20 i cappelli? Non ti credo, fammeli vedere. Sarà meglio che siano in perfette condizioni!", "Oh, sei un tesoro, anche se ci hai messo più di quanto io sia abituata. Questa partita dovrebbe farmi guadagnare un bel po' di soldi, una volta che avrò pulito e personalizzato questi cappelli. E visto che sono sempre disposta a ricompensare un lavoro ben fatto, ecco qualcosina per te. Ti consiglio di spenderne una parte per un bagno, tesoro.", 0x87f5d54e, 0x5cbcdcb7, 0x07521fb1, 0xd83e1745, 0x6c24e923, "....." },
  [8366] = { "Repulisti ai Mari del Sud", "Il capo della sicurezza Bilgewhizzle, del ⟦Steamwheedle Port=Porto degli Spargifumo⟧ a Tanaris, vuole che tu uccida 10 Southsea Pirate, 10 ⟦Southsea Freebooters=Filibustieri dei Mari del Sud⟧, 10 Southsea Dock Worker e 10 Southsea Swashbuckler.", "Argh! Vogliono l'impossibile da me!\n\nIl ⟦Steamwheedle Cartel=Cartello degli Spargifumo⟧ vuole che io dia una lezione ai pirati dei Mari del Sud. Il problema è che non posso stare in due posti contemporaneamente; devo restare qui a mantenere l'ordine.\n\nUltimamente i pirati se ne infischiano del denaro per la protezione che il cartello sborsa regolarmente. Quindi vorrei nominarti mio vice temporaneo, perché tu vada laggiù a fargliela vedere.\n\nLi troverai alla ⟦Lost Rigger Cove=Cala del Sartiame⟧, non troppo lontano, a sud. Grazie, {name}, te ne devo una!", "Già di ritorno? Spero che tu abbia dato a quei teppisti dei Mari del Sud una lezione che non dimenticheranno presto.", "{name}! Sei <il/la> migliore!!!\n\nSono sicuro che ora il Cartello mi lascerà respirare, visto che hai sistemato quella feccia dei Mari del Sud. Vediamo, cosa posso darti come ricompensa? Che ne dici di qualche moneta e di scegliere uno di questi per il disturbo?", 0x2069567b, 0xd79ddcd5, 0x5344aa45, 0x6b651691, 0xb71e97a7, ".....", nil, nil, nil, nil, 0x3be240a2 },
  [8367] = { "Per un grande onore", "Porta 3 Contrassegno d'Onore della ⟦Alterac Valley=Valle d'Alterac⟧, 3 Contrassegno d'Onore del ⟦Arathi Basin=Bacino d'Arathi⟧ e 3 Contrassegno d'Onore della ⟦Warsong Gulch=Forra dei Cantaguerra⟧ a un araldo della guerra dell'⟦Horde=Orda⟧ fuori dai campi di battaglia.", "Servire l'⟦Horde=Orda⟧ in una delle grandi battaglie contro l'⟦Alliance=Alleanza⟧ è fonte di grande onore! I pochi, però, che hanno servito l'⟦Horde=Orda⟧ su TUTTI i nostri fronti attivi sono i nostri combattenti davvero grandi. Sconfiggeremo i nostri avversari non combattendo schermaglie isolate, ma conducendo una guerra ben coordinata.\n\nVa' e schiaccia l'⟦Alliance=Alleanza⟧ nel ⟦Arathi Basin=Bacino d'Arathi⟧, nella ⟦Alterac Valley=Valle d'Alterac⟧ e nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧! Per l'onore! Per l'⟦Horde=Orda⟧!", "Arathi è ancora bagnata dal sangue di grandi guerrieri e il cozzare dell'acciaio risuona ancora per tutta Alterac. Non farmi perdere tempo, a meno che tu non porti notizie dal fronte!", "Le tue prove non sono state facili, ma il coraggio non ti ha abbandonato e la tua forza non è venuta meno. Separati dai vecchi pegni di vittoria, {class}. Nessuno ne avrà bisogno per ricordare il tuo valore. Sta' dritt<o/a>, {name}. Oggi camminerai pien<o/a> d'orgoglio, perché sei <un/una> <eroe/eroina>!", 0x9131d27a, 0x10d01bbf, 0xf4c6ab84, 0x18bb2fc6, 0x426129ba, "....." },
  [8368] = { "La battaglia della ⟦Warsong Gulch=Forra dei Cantaguerra⟧", "Porta 3 Marchi d'Onore dei ⟦Warsong=Cantaguerra⟧ a un Warbringer dell'⟦Horde=Orda⟧ fuori dai campi di battaglia.", "La battaglia nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ contro le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ è di grande importanza. Con il pretesto di proteggere una foresta che non le appartiene, l'⟦Alliance=Alleanza⟧ cerca di negare all'⟦Horde=Orda⟧ una delle nostre maggiori fonti di legname.\n\nNon permettere che accada, {name}! Torna da me con la prova di aver servito l'⟦Horde=Orda⟧ in modo degno!", "Porti notizie dalla ⟦Warsong Gulch=Forra dei Cantaguerra⟧, {name}?", "Eccellente! Hai dimostrato il tuo valore difendendo le nostre operazioni nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧! Che la fama del tuo onore si diffonda in lungo e in largo per le nostre terre.", 0x6925d544, 0xdd9a4a31, 0x134a3898, 0x5bb7b09a, 0xf832f61b, "....." },
  [8369] = { "Invasori della ⟦Alterac Valley=Valle d'Alterac⟧", "Porta 3 Contrassegno d'Onore della ⟦Alterac Valley=Valle d'Alterac⟧ a un araldo della guerra dell'⟦Horde=Orda⟧ fuori dai campi di battaglia.", "Ascolta bene, {name}. Qualunque cosa tu abbia sentito sulla battaglia che infuria nella ⟦Alterac Valley=Valle d'Alterac⟧, una cosa resta vera: la spedizione dei Piccatonante ha invaso il territorio dei Lupi Bianchi. Il giorno in cui permetteremo all'⟦Alliance=Alleanza⟧ di invadere le terre dell'⟦Horde=Orda⟧ senza una risposta decisa sarà il giorno in cui appenderò l'ascia al chiodo e vivrò il resto della mia vita nella vergogna. Va' e caccia gli invasori!", "Che notizie porti dalle terre dei Lupi Bianchi? Come va la battaglia per la ⟦Alterac Valley=Valle d'Alterac⟧?", "Hai dimostrato grande coraggio nel proteggere le nostre terre nella ⟦Alterac Valley=Valle d'Alterac⟧! Riferirò le tue gesta ai miei superiori.", 0x40e3f888, 0x6cc748f3, 0xe01ce18b, 0x5f4a67f5, 0xc67d587b, "....." },
  [8370] = { "Conquistare il ⟦Arathi Basin=Bacino d'Arathi⟧", "Porta 3 Contrassegni d'Onore del Bacino d'Arathi a un araldo della guerra dell'⟦Horde=Orda⟧ fuori dai campi di battaglia.", "Il nostro conflitto con l'⟦Alliance=Alleanza⟧ è diventato una vera guerra. Ormai nessuna delle due parti usa o si aspetta falsi pretesti per scendere in battaglia.\n\nLa battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧ è una questione di risorse, né più né meno. O l'⟦Alliance=Alleanza⟧ ottiene le risorse e le usa contro di noi, o le otteniamo noi e le usiamo per sostenere il nostro sforzo bellico. Aiuta i Profanatori a mantenere il flusso di risorse di cui abbiamo bisogno, {name}!", "Sei tornat<o/a> con notizie da Arathi, {class}?", "Mettere al sicuro le nostre risorse ad Arathi è un compito importante! Hai fatto un buon lavoro, {name}.", 0xc2935afd, 0xf88113df, 0x67a7e231, 0x294fb6ca, 0xb1dc9ed2, "....." },
  [8371] = { "Sforzi concertati", "Porta 3 ⟦Alterac Valley Mark of Honor=Contrassegno d'Onore della Valle d'Alterac⟧, 3 ⟦Arathi Basin Mark of Honor=Contrassegno d'Onore del Bacino d'Arathi⟧ e 3 ⟦Warsong Gulch Mark of Honor=Contrassegno d'Onore della Forra dei Cantaguerra⟧ a un generale di brigata dell'⟦Alliance=Alleanza⟧ fuori dai campi di battaglia.", "Non combattiamo più battaglie isolate contro l'⟦Horde=Orda⟧, ragazz<o/a>.\n\nUna vittoria su un fronte significa negare all'⟦Horde=Orda⟧ risorse che userebbe contro di noi in un'altra battaglia. Allo stesso modo, perdere una qualsiasi battaglia potrebbe dare un vantaggio al nostro avversario da qualche altra parte del mondo.\n\nL'⟦Alliance=Alleanza⟧ ha bisogno di più combattenti con questa visione d'insieme... veri veterani navigati! {name}, torna da me dopo aver combattuto contro l'⟦Horde=Orda⟧ su tutti i nostri campi di battaglia attivi.", "Come vanno i tuoi viaggi, ragazz<o/a>?", "Non sei tipo da deludere, {name}! Ciò che hai imparato va oltre medaglie ed encomi da quattro soldi. Ciò che hai imparato può venire solo con l'esperienza e con la tempra forgiata sul campo di battaglia.\n\nHai fatto bene, {class}. Sei <un/una> <vero/vera> <eroe/eroina> dell'⟦Alliance=Alleanza⟧!", 0x3f0cde75, 0x1c33d9eb, 0xc60bec64, 0x8f1e0c1a, 0xe9fc3fdf, ".....", nil, nil, 0x678d2ae6, 0xbdf4388a, nil },
  [8372] = { "Lotta per la ⟦Warsong Gulch=Forra dei Cantaguerra⟧", "Porta 3 Marchi d'Onore della ⟦Warsong Gulch=Forra dei Cantaguerra⟧ a un generale di brigata dell'⟦Alliance=Alleanza⟧ fuori dai campi di battaglia.", "Le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ sono in guerra con i ⟦Warsong Outriders=Predoni Cantaguerra⟧ per la distruzione che gli orchi stanno causando alla foresta. Tuttavia, ci sono più ragioni per difendere questa foresta in particolare del semplice amore per la natura.\n\nLa foresta forma una barriera strategica che rende ⟦Ashenvale=Valtetra⟧ difendibile da un attacco su larga scala. Senza di essa, Astranaar resisterebbe un giorno o due prima di essere annessa alle ⟦Barrens=Savane⟧.\n\nFa' la tua parte nella lotta contro i ⟦Warsong Outriders=Predoni Cantaguerra⟧, {name}! Per l'⟦Alliance=Alleanza⟧!", "Sei <tornato/tornata> con notizie dal fronte, {name}?", "Ben fatto, {name}! Hai servito bene l'⟦Alliance=Alleanza⟧.", 0xbeadcb52, 0x169d4275, 0xd15c0916, 0x378bede6, 0xa2a5cb89, "....." },
  [8373] = { "Il potere del pino", "Usa un ⟦Stink Bomb Cleaner=Purificatore per Bombe Puzzolenti⟧ per rimuovere ogni Forsaken Stink Bomb lanciata su ⟦Southshore=Riva del Sud⟧. Quando hai finito, torna dal sergente Hartman a ⟦Southshore=Riva del Sud⟧.", "La cosa che odio di più della Veglia delle Ombre sono le bombe puzzolenti che i Reietti usano su ⟦Southshore=Riva del Sud⟧. Chi l'avrebbe detto che festeggiare la liberazione dovesse comportare un pasticcio così puzzolente?\n\nDurante la Veglia delle Ombre, usa questo purificatore per rimuovere le schifose bombe puzzolenti che l'⟦Horde=Orda⟧ potrebbe lanciare qui in paese. Usa il potere del pino per combattere gli odori sgradevoli.\n\nFa' la tua parte per tenere pulita ⟦Southshore=Riva del Sud⟧ e ti darò qualche dolcetto della Veglia delle Ombre che di certo ti piacerà. Affare fatto?", "Quei maledetti Reietti... è già abbastanza grave che siano non morti, ma poi si scaldano e cominciano a creare guai nel MIO paese!", "Ah, quasi quasi qui intorno si respira già meglio. Quasi.\n\nGrazie a te, {name}, ⟦Southshore=Riva del Sud⟧ forse riuscirà a superare un'altra Veglia delle Ombre. Ecco i tuoi dolcetti, con i miei ringraziamenti! Se finisci le caramelle, credo che a ⟦Ironforge=Forgiardente⟧ ci sia una gnoma di nome Katrina Shimmerstar che può vendertene altre; mi pare che si faccia vedere solo durante la Veglia delle Ombre.", 0x6e6d4a39, 0x689dd20c, 0x33ac3eda, 0x6af39b38, 0xb45d1953, "....." },
  [8374] = { "Rivendicare il ⟦Arathi Basin=Bacino d'Arathi⟧", "Porta 3 Contrassegni d'Onore del ⟦Arathi Basin=Bacino d'Arathi⟧ a un generale di brigata dell'⟦Alliance=Alleanza⟧ fuori dai campi di battaglia.", "Vincere una guerra non significa solo essere più astuti dell'avversario e combattere meglio di lui. Spesso la vittoria si riduce semplicemente a produrre più del nemico.\n\nNel ⟦Arathi Basin=Bacino d'Arathi⟧ c'è una notevole riserva di risorse per chiunque riesca a conquistarla per primo.\n\nSe vince l'⟦Alliance=Alleanza⟧, ci saranno più spade e picche per le nostre truppe. Se dovesse vincere l'⟦Horde=Orda⟧, quelle spade e quelle picche verrebbero forgiate comunque, solo che sarebbero puntate contro di noi! Ora è il momento di aiutare l'⟦Alliance=Alleanza⟧ nel ⟦Arathi Basin=Bacino d'Arathi⟧, {name}.", "Dimmi, che notizie ci sono dal fronte?", "Ottimo lavoro, soldato! Continua così e faremo correre l'⟦Horde=Orda⟧ fino a Orgrimmar.", 0x637e1f39, 0x81168a73, 0x9452b6af, 0xa2aee952, 0x43526442, "....." },
  [8375] = { "Ricorda la ⟦Alterac Valley=Valle d'Alterac⟧!", "Porta 3 Contrassegno d'Onore della ⟦Alterac Valley=Valle d'Alterac⟧ a un generale di brigata dell'⟦Alliance=Alleanza⟧ fuori dai campi di battaglia.", "Non fraintendermi, {name}. L'⟦Horde=Orda⟧ ha perfettamente ragione quando dice che la ⟦Alterac Valley=Valle d'Alterac⟧ è territorio dei Lupi Bianchi.\n\nVedi, la spedizione dei Piccatonante arrivò nella zona come visitatori pacifici, in cerca di minerali e reliquie. I Lupi Bianchi reagirono con l'atto d'aggressione più brutale e incivile che l'⟦Alliance=Alleanza⟧ abbia mai subito.\n\nNon dimentichiamo mai i coraggiosi nani che morirono in quel vile attacco a tradimento. Ora va', {class}, fa' la tua parte nella battaglia per la ⟦Alterac Valley=Valle d'Alterac⟧. Per l'⟦Alliance=Alleanza⟧!", "Che notizie porti, {name}?", "Hai fatto la tua parte, {name}. L'⟦Alliance=Alleanza⟧ non può lasciare impuniti gli atti incivili dell'Orda!", 0xea2379c4, 0xf5a75bb8, 0x1106d7d2, 0x816d03be, 0x0945fff6, "....." },
  [8376] = { "Armamenti di guerra", nil, nil, nil, "La guerra si avvicina, {name}, e con essa orrori indicibili. Hai fatto tutto ciò che ti si poteva chiedere, e per questo meriti una ricompensa.\n\nSe questa... questa profezia dovesse mai avverarsi...\n\n<La geologa Larksbane impallidisce.>\n\nIl futuro di tutti noi potrebbe giungere alla fine.\n\nQuesti armamenti si riveleranno preziosissimi per la tua campagna in questo deserto.", 0x9aacc572, nil, nil, nil, 0x7f77ec54, ".mmm." },
