  [8399] = { "Lotta per la ⟦Warsong Gulch=Forra dei Cantaguerra⟧", "Porta 3 Marchi d'Onore della ⟦Warsong Gulch=Forra dei Cantaguerra⟧ a un generale di brigata dell'⟦Alliance=Alleanza⟧ fuori dai campi di battaglia.", "Le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ sono in guerra con i ⟦Warsong Outriders=Predoni Cantaguerra⟧ per la distruzione che gli orchi stanno causando alla foresta. Tuttavia, ci sono più ragioni per difendere questa foresta in particolare del semplice amore per la natura.\n\nLa foresta forma una barriera strategica che rende ⟦Ashenvale=Valtetra⟧ difendibile da un attacco su larga scala. Senza di essa, Astranaar resisterebbe un giorno o due prima di essere annessa alle ⟦Barrens=Savane⟧.\n\nFa' la tua parte nella lotta contro i ⟦Warsong Outriders=Predoni Cantaguerra⟧, {name}! Per l'⟦Alliance=Alleanza⟧!", "Sei <tornato/tornata> con notizie dal fronte, {name}?", "Ottimo lavoro, {name}. Grazie a te, le nostre difese naturali a ⟦Ashenvale=Valtetra⟧ resteranno intatte per un altro giorno.", 0xbeadcb52, 0x169d4275, 0xd15c0916, 0x378bede6, 0x83c232b5, "....." },
  [8400] = { "Lotta per la ⟦Warsong Gulch=Forra dei Cantaguerra⟧", "Porta 3 Marchi d'Onore della ⟦Warsong Gulch=Forra dei Cantaguerra⟧ a un generale di brigata dell'⟦Alliance=Alleanza⟧ fuori dai campi di battaglia.", "Le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ sono in guerra con i ⟦Warsong Outriders=Predoni Cantaguerra⟧ per la distruzione che gli orchi stanno causando alla foresta. Tuttavia, ci sono più ragioni per difendere questa foresta in particolare del semplice amore per la natura.\n\nLa foresta forma una barriera strategica che rende ⟦Ashenvale=Valtetra⟧ difendibile da un attacco su larga scala. Senza di essa, Astranaar resisterebbe un giorno o due prima di essere annessa alle ⟦Barrens=Savane⟧.\n\nFa' la tua parte nella lotta contro i ⟦Warsong Outriders=Predoni Cantaguerra⟧, {name}! Per l'⟦Alliance=Alleanza⟧!", "Sei <tornato/tornata> con notizie dal fronte, {name}?", "Ben fatto, {name}! Hai servito bene l'⟦Alliance=Alleanza⟧.", 0xbeadcb52, 0x169d4275, 0xd15c0916, 0x378bede6, 0xa2a5cb89, "....." },
  [8401] = { "Lotta per la ⟦Warsong Gulch=Forra dei Cantaguerra⟧", "Porta 3 Marchi d'Onore della ⟦Warsong Gulch=Forra dei Cantaguerra⟧ a un generale di brigata dell'⟦Alliance=Alleanza⟧ fuori dai campi di battaglia.", "Le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ sono in guerra con i ⟦Warsong Outriders=Predoni Cantaguerra⟧ per la distruzione che gli orchi stanno causando alla foresta. Tuttavia, ci sono più ragioni per difendere questa foresta in particolare della filosofia conservazionista sposata dagli Alargentea.\n\nLa foresta forma una barriera strategica che rende ⟦Ashenvale=Valtetra⟧ difendibile da un attacco su larga scala. Senza di essa, Astranaar resisterebbe un giorno o due prima di essere annessa alle ⟦Barrens=Savane⟧. Fa' la tua parte nella lotta contro i ⟦Warsong Outriders=Predoni Cantaguerra⟧! Per l'⟦Alliance=Alleanza⟧!", "Sei <tornato/tornata> con notizie dal fronte, {name}?", "Ottimo lavoro, {name}. Grazie a te, le nostre difese naturali a ⟦Ashenvale=Valtetra⟧ resteranno intatte per un altro giorno.", 0xbeadcb52, 0x169d4275, 0x82248f89, 0x378bede6, 0x83c232b5, "....." },
  [8402] = { "Lotta per la ⟦Warsong Gulch=Forra dei Cantaguerra⟧", "Porta 3 Marchi d'Onore della ⟦Warsong Gulch=Forra dei Cantaguerra⟧ a un generale di brigata dell'⟦Alliance=Alleanza⟧ fuori dai campi di battaglia.", "Le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ sono in guerra con i ⟦Warsong Outriders=Predoni Cantaguerra⟧ per la distruzione che gli orchi stanno causando alla foresta. Tuttavia, ci sono più ragioni per difendere questa foresta in particolare del semplice amore per la natura.\n\nLa foresta forma una barriera strategica che rende ⟦Ashenvale=Valtetra⟧ difendibile da un attacco su larga scala. Senza di essa, Astranaar resisterebbe un giorno o due prima di essere annessa alle ⟦Barrens=Savane⟧.\n\nFa' la tua parte nella lotta contro i ⟦Warsong Outriders=Predoni Cantaguerra⟧, {name}! Per l'⟦Alliance=Alleanza⟧!", "Sei <tornato/tornata> con notizie dal fronte, {name}?", "Ben fatto, {name}! Hai servito bene l'⟦Alliance=Alleanza⟧.", 0xbeadcb52, 0x169d4275, 0xd15c0916, 0x378bede6, 0xa2a5cb89, "....." },
  [8403] = { "Lotta per la ⟦Warsong Gulch=Forra dei Cantaguerra⟧", "Porta 3 Marchi d'Onore della ⟦Warsong Gulch=Forra dei Cantaguerra⟧ a un generale di brigata dell'⟦Alliance=Alleanza⟧ fuori dai campi di battaglia.", "Le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ sono in guerra con i ⟦Warsong Outriders=Predoni Cantaguerra⟧ per la distruzione che gli orchi stanno causando alla foresta. Tuttavia, ci sono più ragioni per difendere questa foresta in particolare del semplice amore per la natura.\n\nLa foresta forma una barriera strategica che rende ⟦Ashenvale=Valtetra⟧ difendibile da un attacco su larga scala. Senza di essa, Astranaar resisterebbe un giorno o due prima di essere annessa alle ⟦Barrens=Savane⟧.\n\nFa' la tua parte nella lotta contro i ⟦Warsong Outriders=Predoni Cantaguerra⟧, {name}! Per l'⟦Alliance=Alleanza⟧!", "Sei <tornato/tornata> con notizie dal fronte, {name}?", "Ben fatto, {name}! Hai servito bene l'⟦Alliance=Alleanza⟧.", 0xbeadcb52, 0x169d4275, 0xd15c0916, 0x378bede6, 0xa2a5cb89, "....." },
  [8410] = { "Maestria elementale", "Raccogli un campione di aria, fuoco, terra e acqua per Bath'rah l'osservatore dei venti.", "Bath'rah l'osservatore dei venti ha mandato a chiamare <uno/una> <sciamano/sciamana> della tua saggezza. Chiede che tu gli porti un campione di ciascuno degli elementi, per dimostrare che sei pront<o/a>.\n\nPer trovare Bath'rah, raggiungi il fiume a est del ⟦Tarren Mill=Mulino di Tarren⟧. Seguilo verso nord finché non arrivi alle rovine dove vive Bath'rah.", "Cos'hai per me, {class}?", "Eccellente, mon. Ora sì che si parla.", 0x04bb928b, 0x52c37279, 0x7bb34efb, 0x4e4f40f9, 0x2e232784, "....." },
  [8411] = { "Padroneggiare gli elementi", "Porta gli elementi terra, aria, fuoco e acqua a Bath'rah l'osservatore dei venti.", "Benvenut<o/a>, mon. Tu mi porti gli elementi e poi parliamo.", "Dove sono gli elementi, mon?", "Questi sono gli elementi che mi servono. Ora parliamo.", 0xc6de61cd, 0x53ec0188, 0xf3c3ef42, 0xc83605a1, 0xbf2f0684, "....." },
  [8412] = { "⟦Spirit Totem=Totem dello Spirito⟧", "Porta i pezzi per il totem dello spirito a Bath'rah l'osservatore dei venti.", "Gli spiriti elementali di questo posto non mi sopportano più.\n\nTu dei totem ne sai più di chiunque, e a me serve un totem dello spirito per proteggermi. Gli elementi ce li abbiamo già, ora ci serve qualcosa di più... con più natura. Più primordiale.\n\nNelle ⟦Western Plaguelands=Terre Infette Occidentali⟧ puoi uccidere gli orsi per gli artigli e i ragni per gli occhi. Gli uccelli spazzini mangiano di tutto, quindi potrebbero avere l'uno o l'altro.", "Gli spiriti sanno cosa stiamo combinando, e stanno cercando di uccidermi! Spero che tu abbia i pezzi.", "Grande, mon! Proviamolo...", 0xb513abac, 0xfad1dd4d, 0xfa023a9f, 0xdcff1581, 0x4f7f69ce, "....." },
  [8413] = { "Il vudù", "Porta le piume vudù a Bath'rah l'osservatore dei venti.", "Il totem dello spirito non basta. Ci serve un po' di magia vudù per farlo funzionare a dovere.\n\nI troll del Tempio di Atal'Hakkar hanno piume piene di magia vudù. Vai là e uccidi Gasher, Mijan, Zolo, Hukku, Zul'lor e Loro. Poi avremo magia abbastanza per un vero totem dello spirito.", "Dove sono le piume, mon?", "Era ora che questo troll si facesse una notte di sonno intera! Il totem dello spirito veglierà su di me.\n\nÈ da tanto che colleziono cose: forse vuoi qualcosa per tutto il disturbo?", 0x44084925, 0x7d0d0c69, 0x438ab205, 0x4e430c1d, 0xccb3a8ea, "....." },
  [8414] = { "Scacciare il male", "Raccogli 20 Minion's Scourgestone e portale al sommo sacerdote Thel'danis, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Salute, {class}. I crociati come te sono una vista gradita in queste lande desolate.\n\nLa tua forza sacra serve a combattere gli infiniti non morti di qui. Devi raccogliere un gran numero di pietre del Flagello e portarle al sommo sacerdote Thel'danis. Il sommo sacerdote si trova a guardia del ⟦Uther's Tomb=Sepolcro di Uther⟧, sulla ⟦Sorrow Hill=Collina del Cordoglio⟧, non lontano da qui.\n\nSolo chi possiede un ⟦Argent Dawn Commission=Distintivo dell'Alba d'Argento⟧ può sperare di trovare le pietre del Flagello, quindi parla con l'ufficiale Pureheart, se non l'hai già fatto.", "Quale male mi hai portato?", "C'è un rischio nel dissolvere il male da una pietra del Flagello, perché attira l'attenzione dei non morti per miglia e miglia. Ma tu sei forte nella Luce, {name}, e non temo per te...", 0x33cb58b8, 0xc904dac3, 0x8a383c2e, 0x28a0867e, 0x8d4531d5, "....." },
  [8415] = { "⟦Chillwind Point=Gola di Ventofreddo⟧", "Parla con il comandante Ashlam Valorfist alla ⟦Chillwind Point=Gola di Ventofreddo⟧.", "Il comandante Ashlam Valorfist ha lanciato un appello a <un/una> <paladino/paladina> della tua purezza e del tuo valore, {name}. Lo troverai alla ⟦Chillwind Point=Gola di Ventofreddo⟧, nella parte meridionale delle ⟦Western Plaguelands=Terre Infette Occidentali⟧. Cercalo e aiutalo nella sua causa per la Luce!", nil, "Molto bene, {class}! Vediamo di che pasta sei fatt<o/a>.", 0xe3f1bb3e, 0x68fa4270, 0x9b5889f4, nil, 0xb58b885c, "...m." },
  [8416] = { "Pietre del Flagello inerti", "Porta la ⟦Inert Scourgestone=Pietra del Flagello Inerte⟧ al comandante Ashlan Valorfist alla ⟦Chillwind Point=Gola di Ventofreddo⟧.", "Il male è stato purgato dalle pietre, {name}.\n\nConosco i piani del comandante Ashlam, e gli servirà una sola pietra inerte. Portagliela, così potremo immergere il Flagello nel fuoco della giustizia.", "Thal'danis è riuscito a purificare le pietre del Flagello?", "Hai fatto ciò che ti ho chiesto senza fare domande, {name}.\n\nSembra che la fiducia sia stata conquistata. Forse ora posso rivelarti il nostro piano più nel dettaglio.", 0x23c63ec5, 0xd6823c95, 0x5bd75dd5, 0x2f416567, 0xb3ba619c, "....." },
  [8417] = { "Uno spirito tormentato", "Parla con l'Eroe Caduto dell'⟦Horde=Orda⟧ all'ingresso delle ⟦Blasted Lands=Terre Devastate⟧.", "Nelle ⟦Blasted Lands=Terre Devastate⟧ c'è uno spirito tormentato che un tempo fu un grande eroe dell'Orda. L'onore di un guerriero non muore con il corpo, e ti farebbe bene parlare con lui.", "Allora, Stoley ha sganciato il mio liquore?", "Dunque sei venut<o/a> ad alleviare il mio dolore. Vorrei che bastasse abbattermi, ma non è così semplice...", 0xe07b8903, 0x95a03fae, 0xb5739780, 0xfdfa4434, 0xa46758be, "....." },
  [8418] = { "Forgiare la Pietragrossa", "Porta le piume vudù ad Ashlam Valorfist.", "Ora dobbiamo unire le pietre del Flagello inerti e creare un'arma che frantumi le file dei non morti. Non è un compito da poco, {name}. Solo i troll del Tempio di Atal'Hakkar possiedono quella rara magia capace di rivolgere il male di una cosa contro sé stessa.\n\nNel tempio, i troll sono noti come Gasher, Mijan, Zolo, Hukku, Zul'lor e Loro. Non provare rimorso per le loro anime corrotte... non sono privi di malvagità.", "Hai ucciso quei troll miserabili?", "Eccellente, {name}. Direi di essere sorpreso, ma sapevo senza alcun dubbio che non ci avresti delusi.\n\nÈ un onore per me consegnarti una delle Pietregrosse Sacre. Usala bene.", 0x7dd6edce, 0x78b14100, 0xbeb50915, 0x35661f33, 0xd6031f34, "....." },
  [8419] = { "La richiesta di un imp", "Porta un pezzo di telavile a Impsy, a ⟦Felwood=Vilbosco⟧.", "{name}, un imp di ⟦Felwood=Vilbosco⟧ di nome Impsy ha chiesto la tua presenza. È un po' strano, perché ha chiesto che tu porti un pezzo di telavile come segno di buona fede. Considerando il potere che già possiedi come <stregone/strega>, posso solo supporre che tu sappia che i satiri di ⟦Felwood=Vilbosco⟧ portano con sé questa telavile.\n\nTroverai Impsy appena a nord delle ⟦Bloodvenom Falls=Cascate Sanguemarcio⟧, che a quanto ho sentito sono piuttosto belle in questo periodo dell'anno.", "Hai la mia telavile?", "Che <splendido/splendida> {class} sei!\n\n<Impsy si porta la telavile al viso.>\n\nOh, come adoro sentirla, il modo in cui ti brucia la pelle e intreccia pensieri malvagi nella mente...", 0x8f923b54, 0xcaccde4e, 0xba1e506c, 0xe4cd415e, 0x051f42a7, "....." },
  [8420] = { "Brucia e pizzica", "Porta un pezzo di telavile a Impsy, a ⟦Felwood=Vilbosco⟧.", "Forse suona strano detto da un imp, ma vorrei un famiglio tutto mio. Davvero. Non è giusto che Niby abbia me e io non abbia niente!\n\nAnzi, non c'è nemmeno bisogno che sia un famiglio vivo. Mi servirebbe qualcosa con cui cominciare a costruirlo, tipo un po' di telavile. I satiri qui a ⟦Felwood=Vilbosco⟧ a volte hanno della telavile, quindi dovresti solo ucciderne abbastanza finché non ne trovi un po'. Non sembra poi così male, vero?", "Hai la mia telavile?", "Wow! Sei troppo gentile. Soprattutto per <uno/una> <stregone/strega>!\n\n<Impsy si porta la telavile al viso.>\n\nOh, come adoro sentirla, il modo in cui ti brucia la pelle e intreccia pensieri malvagi nella mente...", 0x7df22def, 0xcaccde4e, 0x787ec5c0, 0xe4cd415e, 0x5abdaa3e, "....." },
  [8421] = { "La roba sbagliata", "Porta 10 ⟦Rotting Wood=Legno Marcio⟧ e 4 ⟦Bloodvenom Essence=Essenza di Sanguemarcio⟧ a Impsy, a ⟦Felwood=Vilbosco⟧.", "Ora che ho la mia telavile, posso davvero cominciare a costruire il *mio* famiglio.\n\nPerò gli serviranno degli occhi. Magari potresti strappare un po' di legno marcio alle creature di Troncoferro, così posso intagliarci degli occhi adorabili. Stanno su a nord, nel ⟦Irontree Woods=Bosco di Troncoferro⟧.\n\nMi servirà anche un po' di essenza di sanguemarcio per dargli quel profumo di demone nuovo. Ce l'hanno le melme corrotte, che se ne stanno proprio qui vicino a me e a Niby.", "Hai la roba?", "Questa roba andrà benissimo.", 0x40b3fba2, 0x1049c074, 0x8f984754, 0x62d2d1c5, 0xd0eb0948, "....." },
  [8422] = { "Troll dello stesso piumaggio", "Porta in tutto 6 Voodoo Feathers dei troll del Tempio di Atal'Hakkar.", "Il mio famiglio è quasi pronto. Ora mi serve solo qualcosa per imbottirlo.\n\nVanno bene soltanto le piume vudù dei troll del Tempio di Atal'Hakkar. Si chiamano Gasher, Mijan, Zolo, Hukku, Zul'lor e Loro. Uccidili. Uccidili tutti.\n\nNon è un compito da poco, {name}, quindi ti ricompenserò con qualcosa di Niby: tanto probabilmente non gli serve.", "Hai portato le piume? Questa bambola va imbottita!", "Magnifico, ora il mio famiglio è completo!\n\n<Impsy imbottisce in fretta la bambola e le dà un abbraccio demoniaco.>\n\nOh, che strano effetto collaterale hanno queste piume vudù...", 0xe11bf3ac, 0xfa3d0c11, 0x7f9ba851, 0x80d2b7f3, 0x46c09dc3, "....." },
  [8423] = { "Fratellanza tra guerrieri", "Uccidi 7 Helboar nelle ⟦Blasted Lands=Terre Devastate⟧ e torna dall'Eroe Caduto dell'⟦Horde=Orda⟧.", "<L'Eroe ti squadra.>\n\nSei <un/una> {class}, non c'è dubbio. Vorrei chiederti un compito onorevole, ma prima devo mettere alla prova la tua forza.\n\nSi dice che Rexxar misurasse l'affilatura delle sue lame uccidendo un Helboar con un solo, rapido colpo. Ora io misurerò la tua forza facendoteli uccidere.", "Gli aculei ardenti degli Helboar lasciano cicatrici orribili. Non temere il dolore e lo sfregio, <guerriero/guerriera>: non sono nulla in confronto alla prigione a cui sono legato.", "Non mi serve una prova per sapere ciò che hai fatto, {class}. Vedo la determinazione scolpita sul tuo volto.", 0xde7fa3a8, 0x39b7a605, 0x8f24b94b, 0x5be003e0, 0x2aacbdb4, "....." },
  [8424] = { "Guerra agli Shadowsworn", "Massacra gli Shadowsworn nelle ⟦Blasted Lands=Terre Devastate⟧ e torna dall'Eroe Caduto dell'⟦Horde=Orda⟧.", "La presenza costante degli Shadowsworn nelle ⟦Blasted Lands=Terre Devastate⟧ mi procura grande dolore. I loro rituali e incantesimi oscuri causano un'agonia che non ho mai provato da vivo.\n\nAttraverso di te posso consegnare il mio messaggio di dolore. Va' e porta la mia collera.", "Gli Shadowsworn non si sconfiggono facilmente, vero? Ma tu sei <un/una> <guerriero/guerriera>, e trionferai o morirai provandoci.", "Hai già placato il mio dolore e mi hai reso onore. Grazie, {class}.", 0x7e21c995, 0xe2db1389, 0x7336323a, 0xdecd09a7, 0x41506fda, "....." },
  [8425] = { "Piume vudù", "Porta le Voodoo Feathers dei troll del Tempio di Atal'Hakkar all'Eroe Caduto dell'⟦Horde=Orda⟧.", "Il tuo onore mi ha dato un po' di pace. È giusto che io ti offra qualcosa in cambio.\n\nLe mie armi e la mia armatura erano splendide in vita, ma ora non mi servono a nulla. Sarebbero più utili nelle tue mani.\n\nRecati al Tempio di Atal'Hakkar e distruggi i troll guardiani Gasher, Mijan, Zolo, Hukku, Zul'lor e Loro. Portano con sé piume magiche che possono ridare forma al mio corpo fisico abbastanza a lungo da concederti una ricompensa.", "Sei già di ritorno? Il tempo non è più lo stesso, per me: forse per te è stato davvero un lungo viaggio...", "Finalmente posso sentire di nuovo il freddo tocco dell'acciaio, anche se solo per un istante.", 0xbb860a9b, 0x4f5e1843, 0x400f79cc, 0x05e22a31, 0x1afd1e5f, "....." },
  [8426] = { "La battaglia della ⟦Warsong Gulch=Forra dei Cantaguerra⟧", "Porta 3 Marchi d'Onore della ⟦Warsong Gulch=Forra dei Cantaguerra⟧ a un araldo di guerra dell'⟦Horde=Orda⟧ fuori dai campi di battaglia.", "La battaglia nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ contro le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ è di grande importanza. Con il pretesto di proteggere una foresta che non le appartiene, l'⟦Alliance=Alleanza⟧ cerca di negare all'⟦Horde=Orda⟧ una delle nostre maggiori fonti di legname.\n\nNon permettere che accada, {name}! Torna da me con la prova di aver servito l'⟦Horde=Orda⟧ in modo degno!", "La battaglia nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ contro le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ è di grande importanza. Con il pretesto di proteggere una foresta che non le appartiene, l'⟦Alliance=Alleanza⟧ cerca di negare all'⟦Horde=Orda⟧ una delle nostre maggiori fonti di legname.\n\nNon permettere che accada, {name}! Torna da me con la prova di aver servito l'⟦Horde=Orda⟧ in modo degno!", "Eccellente! Hai dimostrato il tuo valore difendendo le nostre operazioni nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧! Che la fama del tuo onore si diffonda in lungo e in largo per le nostre terre.", 0x6925d544, 0xcff9743e, 0x134a3898, 0x134a3898, 0xf832f61b, "....." },
  [8427] = { "La battaglia della ⟦Warsong Gulch=Forra dei Cantaguerra⟧", "Porta 3 Marchi d'Onore della ⟦Warsong Gulch=Forra dei Cantaguerra⟧ a un araldo di guerra dell'⟦Horde=Orda⟧ fuori dai campi di battaglia.", "La battaglia nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ contro le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ è di grande importanza. Con il pretesto di proteggere una foresta che non le appartiene, l'⟦Alliance=Alleanza⟧ cerca di negare all'⟦Horde=Orda⟧ una delle nostre maggiori fonti di legname.\n\nNon permettere che accada, {name}! Torna da me con la prova di aver servito l'⟦Horde=Orda⟧ in modo degno!", "Porti notizie dalla ⟦Warsong Gulch=Forra dei Cantaguerra⟧, {name}?", "Eccellente! Hai dimostrato il tuo valore difendendo le nostre operazioni nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧! Che la fama del tuo onore si diffonda in lungo e in largo per le nostre terre.", 0x6925d544, 0xcff9743e, 0x134a3898, 0x5bb7b09a, 0xf832f61b, "....." },
