  [8430] = { "La battaglia della ⟦Warsong Gulch=Forra dei Cantaguerra⟧", "Porta 3 Marchi d'Onore della ⟦Warsong Gulch=Forra dei Cantaguerra⟧ a un araldo di guerra dell'⟦Horde=Orda⟧ fuori dai campi di battaglia.", "La battaglia nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ contro le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ è di grande importanza. Con il pretesto di proteggere una foresta che non le appartiene, l'⟦Alliance=Alleanza⟧ cerca di negare all'⟦Horde=Orda⟧ una delle nostre maggiori fonti di legname.\n\nNon permettere che accada, {name}! Torna da me con la prova di aver servito l'⟦Horde=Orda⟧ in modo degno!", "Porti notizie dalla ⟦Warsong Gulch=Forra dei Cantaguerra⟧, {name}?", "Eccellente! Hai dimostrato il tuo valore difendendo le nostre operazioni nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧! Che la fama del tuo onore si diffonda in lungo e in largo per le nostre terre.", 0x6925d544, 0xcff9743e, 0x134a3898, 0x5bb7b09a, 0xf832f61b, "....." },
  [8436] = { "Conquistare il ⟦Arathi Basin=Bacino d'Arathi⟧", "Porta 3 Contrassegni d'Onore del Bacino d'Arathi a un araldo della guerra dell'⟦Horde=Orda⟧ fuori dai campi di battaglia.", "Il nostro conflitto con l'⟦Alliance=Alleanza⟧ è diventato una vera guerra. Ormai nessuna delle due parti usa o si aspetta falsi pretesti per scendere in battaglia.\n\nLa battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧ è una questione di risorse, né più né meno. O l'⟦Alliance=Alleanza⟧ ottiene le risorse e le usa contro di noi, o le otteniamo noi e le usiamo per sostenere il nostro sforzo bellico. Aiuta i Profanatori a mantenere il flusso di risorse di cui abbiamo bisogno, {name}!", "Sei tornat<o/a> con notizie da Arathi, {class}?", "Mettere al sicuro le nostre risorse ad Arathi è un compito importante! Hai fatto un buon lavoro, {name}.", 0xc2935afd, 0xf88113df, 0x67a7e231, 0x294fb6ca, 0xb1dc9ed2, "....." },
  [8437] = { "Conquistare il ⟦Arathi Basin=Bacino d'Arathi⟧", "Porta 3 Contrassegni d'Onore del Bacino d'Arathi a un araldo della guerra dell'⟦Horde=Orda⟧ fuori dai campi di battaglia.", "Il nostro conflitto con l'⟦Alliance=Alleanza⟧ è diventato una vera guerra. Ormai nessuna delle due parti usa o si aspetta falsi pretesti per scendere in battaglia.\n\nLa battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧ è una questione di risorse, né più né meno. O l'⟦Alliance=Alleanza⟧ ottiene le risorse e le usa contro di noi, o le otteniamo noi e le usiamo per sostenere il nostro sforzo bellico. Aiuta i Profanatori a mantenere il flusso di risorse di cui abbiamo bisogno, {name}!", "Sei tornat<o/a> con notizie da Arathi, {class}?", "Mettere al sicuro le nostre risorse ad Arathi è un compito importante! Hai fatto un buon lavoro, {name}.", 0xc2935afd, 0xf88113df, 0x67a7e231, 0x294fb6ca, 0xb1dc9ed2, "....." },
  [8438] = { "Conquistare il ⟦Arathi Basin=Bacino d'Arathi⟧", "Porta 3 Contrassegni d'Onore del Bacino d'Arathi a un araldo della guerra dell'⟦Horde=Orda⟧ fuori dai campi di battaglia.", "Il nostro conflitto con l'⟦Alliance=Alleanza⟧ è diventato una vera guerra. Ormai nessuna delle due parti usa o si aspetta falsi pretesti per scendere in battaglia.\n\nLa battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧ è una questione di risorse, né più né meno. O l'⟦Alliance=Alleanza⟧ ottiene le risorse e le usa contro di noi, o le otteniamo noi e le usiamo per sostenere il nostro sforzo bellico. Aiuta i Profanatori a mantenere il flusso di risorse di cui abbiamo bisogno, {name}!", "Sei tornat<o/a> con notizie da Arathi, {class}?", "Mettere al sicuro le nostre risorse ad Arathi è un compito importante! Hai fatto un buon lavoro, {name}.", 0xc2935afd, 0xf88113df, 0x67a7e231, 0x294fb6ca, 0xb1dc9ed2, "....." },
  [8439] = { "Conquistare il ⟦Arathi Basin=Bacino d'Arathi⟧", "Porta 3 Contrassegni d'Onore del Bacino d'Arathi a un araldo della guerra dell'⟦Horde=Orda⟧ fuori dai campi di battaglia.", "Il nostro conflitto con l'⟦Alliance=Alleanza⟧ è diventato una vera guerra. Ormai nessuna delle due parti usa o si aspetta falsi pretesti per scendere in battaglia.\n\nLa battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧ è una questione di risorse, né più né meno. O l'⟦Alliance=Alleanza⟧ ottiene le risorse e le usa contro di noi, o le otteniamo noi e le usiamo per sostenere il nostro sforzo bellico. Aiuta i Profanatori a mantenere il flusso di risorse di cui abbiamo bisogno, {name}!", "Sei tornat<o/a> con notizie da Arathi, {class}?", "Mettere al sicuro le nostre risorse ad Arathi è un compito importante! Hai fatto un buon lavoro, {name}.", 0xc2935afd, 0xf88113df, 0x67a7e231, 0x294fb6ca, 0xb1dc9ed2, "....." },
  [8446] = { nil, nil, nil, "Sì, {race}?", nil, nil, nil, nil, 0x98b629a5, nil, "mmm.m" },
  [8460] = { "Alleato dei Mordilegno", "Grazle vuole che tu dimostri il tuo valore uccidendo 6 Deadwood Warrior, 6 Deadwood Pathfinder e 6 Deadwood Gardener. Quando avrai finito, torna da lui nel ⟦Felwood=Vilbosco⟧ meridionale, vicino al ⟦Emerald Sanctuary=Santuario di Smeraldo⟧.", "I Mordilegno sono l'unica tribù di mezzorsi sfuggita alla corruzione. Eppure oggi molte altre razze uccidono i mezzorsi alla cieca, senza curarsi di capire se sono amici o nemici. Per questo i mezzorsi Mordilegno si fidano di pochissimi.\n\nVuoi dimostrare il tuo valore? Respingi la corrotta tribù dei Legnomorto del ⟦Felwood=Vilbosco⟧ e un giorno potremmo considerarti <alleato/alleata>. Troverai la prima tribù dei Legnomorto, guerrieri, esploratori e giardinieri, a ovest di qui.", "Continua così, {name}. Se vuoi guadagnarti la nostra fiducia, dovrai dimostrarci il tuo valore.", "Soffriamo molto per gli eventi del passato. Grazie per ciò che hai fatto per proteggere i Mordilegno. In segno della nostra crescente amicizia, ti prego di accettare questa umile offerta.", 0x69fcebb2, 0x62b5ba95, 0xa2401007, 0x4cc9b0e3, 0xaa7a3b99, "....." },
  [8461] = { "I Legnomorto del nord", "Nafien vuole che tu uccida 6 Deadwood Den Watcher, 6 Deadwood Avenger e 6 Deadwood Shaman. Torna da lui nel nord di ⟦Felwood=Vilbosco⟧, vicino all'ingresso del ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧.", "C'è un accampamento di mezzorsi Legnomorto proprio a sud-ovest di qui. La corruzione pervade l'accampamento, e vorrei porvi fine prima che diventino un problema.\n\nLa tribù dei Legnomorto è malvagia, ma è l'energia vile che inquina le loro menti. La loro ostilità non è davvero innata, eppure non si può fare nulla per aiutarli. Mi rattrista dover combattere i nostri stessi fratelli.\n\nTi prego, {name}: ti chiedo di fare ciò che va fatto. Risparmiami solo i dettagli; immagini tanto penose mi turbano troppo.", "Quando avrai conquistato la fiducia dei Mordilegno, sono certo che potremo fare qualcosa per te. I Mordilegno non dimenticano i loro alleati, specialmente in tempi bui come questi.", "Percepisco che hai ottenuto la vittoria. Vittoria... una parola così vuota, considerando ciò che si è dovuto fare. In ogni caso, hai dimostrato di essere <degno/degna> della nostra fiducia.\n\nPotrebbe volerci del tempo prima che i Mordilegno ti accolgano senza ostilità nel Rifugio. Tuttavia, la tua perseveranza eroderà ogni sospetto che i miei fratelli possano nutrire su di te. Finché non ci tradirai e non alzerai le armi contro di noi, troveremo un terreno comune.", 0xb6acb3ae, 0xb30acb50, 0x71d91a00, 0x8424c8e2, 0xbd4d6d31, "....." },
  [8462] = { "Parla con Nafien", "Percorri verso nord la strada principale di ⟦Felwood=Vilbosco⟧ e parla con il mezzorso di nome Nafien. Fa la guardia fuori dall'ingresso del ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧.", "Forse sei in grado di affrontare una minaccia più grande che noi Mordilegno dobbiamo fronteggiare. Di certo qui hai dimostrato di esserne capace...\n\nUn altro della mia specie fa la guardia fuori dall'ingresso del ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧, lungo questa strada, molto più a nord. Si chiama Nafien; anche se può sembrare una bestia selvaggia e poco raccomandabile, non temerlo. Cerca solo aiuto contro le forze maligne che minacciano la nostra casa.", nil, "Ah... Ho sentito la voce portata dal vento su coloro che, pur non appartenendo alla nostra tribù, cercano di allearsi con i mezzorsi Mordilegno. Ti do il benvenuto, ma devi sapere che la mia tribù reagisce male agli estranei.\n\nQuesti sono tempi difficili, e possiamo fidarci solo di chi sceglie di combattere al nostro fianco la corruzione della terra... e ce lo ha dimostrato di conseguenza. Chi non lo ha fatto sarà accolto con aperta ostilità se entrerà nel Rifugio.", 0x1e7cf150, 0xfd94d1c5, 0x16e63df0, nil, 0x08837f6c, "...m." },
  [8464] = { "Attività dei Freddinverno", "Salfa vuole che tu uccida 8 Winterfall Shaman, 8 Winterfall Den Watcher e 8 Winterfall Ursa. Salfa si trova appena fuori dall'ingresso del ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧, a ⟦Winterspring=Fontefredda⟧.", "I Mordilegno tendono a stare per conto loro, {name}. Pur concedendo un passaggio sicuro a chi riteniamo degno di fiducia, cerchiamo di evitare le altre tribù di mezzorsi, se appena possibile.\n\nUltimamente la tribù dei Freddinverno è diventata sempre più ostile nei nostri confronti. Sembrano in preda alla furia, completamente divorati dalla paura e dall'odio per tutto ciò che non capiscono.\n\nDevo chiederti di sfoltire le loro file, per ridurre la minaccia contro di noi. Cercali al ⟦Winterfall Village=Villaggio dei Freddinverno⟧, molto a est di qui.", "Apprezziamo molto ciò che hai fatto per i Mordilegno, {name}. Se continuerai così, ti guadagnerai di certo la fiducia e il rispetto della mia tribù.", "Grazie per ciò che hai fatto, per quanto sia triste. Accetta questo come segno di gratitudine.\n\nTi chiedo di continuare ad aiutarci, {name}. Abbiamo pochissimi alleati a cui rivolgerci e, senza il tuo aiuto, le minacce contro la mia tribù sarebbero di certo troppo grandi da affrontare da soli.", 0xfa0ccfbc, 0x15a35934, 0x10d61732, 0x369719ad, 0x3375f923, "....." },
  [8465] = { "Parla con Salfa", "Attraversa il ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧ ed esci a ⟦Winterspring=Fontefredda⟧. Parla con Salfa, che fa la guardia fuori dall'ingresso del ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧.", "La minaccia della corruzione non viene solo dai mezzorsi Legnomorto a sud, ma anche da est, dai mezzorsi Freddinverno di ⟦Winterspring=Fontefredda⟧. Se vuoi aiutarci ancora, parla con Salfa dall'altra parte del Rifugio, presso l'ingresso di ⟦Winterspring=Fontefredda⟧. Segui il sentiero a sinistra per raggiungerlo.\n\nStai in guardia: se i miei simili all'interno ti considerano Ostile o Odiato, ti attaccheranno. Viaggia più in fretta che puoi, evitando gli scontri. Uccidere un Mordilegno, anche per legittima difesa, non farà che renderti ancora più inviso.", nil, "Salute, {class}. Sto di guardia qui sia come portavoce dei Mordilegno qui a ⟦Winterspring=Fontefredda⟧, sia come difensore della tribù.\n\nI nostri fratelli Freddinverno, qui in questa terra gelida, sono caduti sotto lo stesso influsso corruttore dei mezzorsi di ⟦Felwood=Vilbosco⟧. Se sei <venuto/venuta> a offrire aiuto ai mezzorsi Mordilegno, allora siamo pronti ad accettare la tua offerta.", 0x0bcafcf5, 0xd998c3b3, 0x0eda6305, nil, 0x61b7f62d, "...m." },
  [8470] = { "⟦Deadwood Ritual Totem=Totem Rituale dei Legnomorto⟧", "Porta il ⟦Deadwood Ritual Totem=Totem Rituale dei Legnomorto⟧ all'interno del ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧ e vedi se uno dei mezzorsi può trovargli un uso. I Mordilegno non ti parleranno se la tua reputazione con loro non è almeno Neutrale.", "Hai trovato uno dei totem rituali dei mezzorsi Legnomorto. Il totem in sé è di fattura anonima, ma emana un palpabile senso di disperazione. Se esiste un oggetto che possa rappresentare al meglio la corruzione di cui soffrono i mezzorsi Legnomorto, questo è senza dubbio quello.\n\nUno dei mezzorsi all'interno del ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧ potrebbe trovare un uso per un oggetto simile... sempre che tu abbia conquistato la loro fiducia quanto basta perché ti parlino.", "Sì, {class}, in cosa posso aiutarti? Cammini tra noi in pace, eppure c'è di sicuro qualcosa che non va. Percepisco qualcosa... qualcosa di inquietante...", "Questo totem... Lo riconosco come uno dei totem dei Legnomorto, ma è impregnato del fetore della decomposizione. Qualunque male abbia messo i nostri fratelli contro di noi è di certo presente in questo oggetto.\n\nHai fatto bene a portarcelo, {name}. Forse, con lo studio e i rituali, potremo scoprire che cosa inquina le menti dei nostri fratelli. Grazie, <amico/amica>; accetta queste offerte in cambio della tua scoperta.", 0x835827c1, 0x38da6b11, 0x05bee739, 0x400a0c34, 0x499bdd47, "....." },
  [8471] = { "⟦Winterfall Ritual Totem=Totem Rituale dei Freddinverno⟧", "Porta il ⟦Winterfall Ritual Totem=Totem Rituale dei Freddinverno⟧ nel ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧ e scopri se uno dei mezzorsi che vi abitano saprà farne uso. I Mordilegno non ti parleranno finché la tua reputazione presso di loro non sarà almeno Neutrale.", "Hai trovato uno dei totem rituali dei mezzorsi Freddinverno. Il totem in sé è di fattura anonima, ma sembra emanare un senso quasi tangibile di terrore e disperazione. Se davvero molti mezzorsi Freddinverno ne portano uno, questo spiegherebbe in buona parte il loro stato attuale.\n\nUno dei mezzorsi del ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧ potrebbe trovare un uso per un oggetto simile... sempre che tu ti sia <guadagnato/guadagnata> abbastanza la loro fiducia da farli parlare con te.", "{class}, ti avvicini a noi in modo pacifico, ma sento che sei qui per questioni gravi e serie... per i mezzorsi come per ogni {race}. Che cosa sei venut<o/a> a dirci?", "Questa cosa... ha la forma di un ⟦Winterfall Ritual Totem=Totem Rituale dei Freddinverno⟧, ma è stata distorta da forze che non riesco nemmeno a immaginare. Qualunque contaminazione abbia messo i Freddinverno contro di noi è di certo presente in questo oggetto.\n\nUna saggezza divina ha portato sia questo sia te da noi, {name}. Studieremo attentamente questo oggetto; forse un giorno i Freddinverno smetteranno di infuriare contro di noi.\n\nGrazie, amico: accetta queste offerte in cambio della tua benevolenza.", 0x1a9e7597, 0x8901cc35, 0x095bc630, 0x5a6ecea3, 0x92c5d348, "....." },
  [8499] = { "L'⟦Alliance=Alleanza⟧ ha bisogno di barre di torio!", "Porta 20 Lingotto di Torio a dama Twinbraid nel Military Ward di ⟦Ironforge=Forgiardente⟧.", "È molto gentile da parte tua informarti sulle necessità dell'⟦Alliance=Alleanza⟧. Oltre a tutte le altre raccolte in corso, abbiamo bisogno di una grande quantità di barre di torio, ed è questo il compito di cui sono responsabile. Il torio servirà a creare molte cose diverse per la guerra, prima fra tutte la costruzione di un battaglione di carri armati a vapore da trasportare in volo a ⟦Silithus=Silitus⟧ non appena saranno completati. Puoi aiutarci in questa impresa, {class}?", "Oh, un carico da parte di mio fratello? Splendido! Oggi la fortuna mi sorride davvero!", "Quindi Gnoarn non si fida delle mie capacità di ricognizione? Chissà perché...", 0xbc047bca, 0x3b0fb51a, 0xde56c2df, 0x89b01d8f, 0x8c8ff225, "....." },
  [8551] = { "Lo scrigno del capitano", "Porta lo ⟦Smotts' Chest=Scrigno di Smotts⟧ a Hecklebury Smotts, alla ⟦Booty Bay=Baia del Bottino⟧.", "Un tempo navigavo da qui fino a ⟦Ratchet=Porto Paranco⟧, a Kalimdor. Ero un capitano di successo, con una reputazione impeccabile.\n\nFinché...\n\nQuei maledetti giganti marini mi hanno rovinato! Hanno sfasciato la mia nave, ucciso il mio equipaggio e mi hanno messo su una scialuppa diretta alla ⟦Booty Bay=Baia del Bottino⟧. E uno dei giganti, Gorlash, mi ha rubato lo scrigno del capitano. Ha detto che gli serviva come tabacchiera. Che faccia tosta!\n\nPare che Gorlash vaghi lungo la costa a est di qui. Trovalo e riprenditi il mio scrigno! Fallo, e avrai guadagnato la gratitudine di un capitano.", "Ehilà, {name}! Hai trovato Gorlash? Quello scrigno era il mio preferito, e ha uno scomparto segreto dove tenevo i miei tesori più preziosi!", "L'hai trovato! Oh, che giorno felice! Grazie, {name}. Riavere il mio scrigno placa un po' il fuoco che ho dentro.\n\nMa la mia vendetta non è completa...", 0xba51aa97, 0x91038538, 0x167e029a, 0x06215b45, 0x6b909651, "....." },
  [8552] = { "La ⟦Monogrammed Sash=Fascia con Iniziali⟧", "Restituisci la ⟦Monogrammed Sash=Fascia con Iniziali⟧ al suo proprietario.", "Questa bella fascia ha le lettere \"HS\" ricamate lungo l'orlo.", "Salve. Hai affari da sbrigare con me?", "Hai recuperato la mia fascia? Allora... devi aver ucciso Mok'rash, il gigante marino! Evviva!\n\nSono contento che quel lurido furfante sia morto. Mok'rash era uno dei tre giganti marini che hanno distrutto le mie navi e ucciso il mio equipaggio.\n\nTre volte.\n\nSei <un/una> {class} di valore, {name}.", 0xf25f7e16, 0xaf626a54, 0xd7b275b4, 0x48a14437, 0xd35d9f2e, "....." },
  [8553] = { "La scimitarra del capitano", "Parla con Sprogger.", "Dopo aver perso la mia prima nave per colpa di quei giganti, ne ho comprata un'altra. L'ho chiamata Smotts' Revenge, l'ho riempita di provviste e di marinai e sono partito a caccia di quei furfanti. Li ho trovati, ma... mi hanno battuto. Hanno distrutto la Smotts' Revenge, ucciso il mio secondo equipaggio e mi hanno messo su un'altra scialuppa.\n\nStavolta un altro dei giganti, Negolash, mi ha rubato la scimitarra.\n\nAffronta Negolash e riportami la mia scimitarra!\n\nParla con Sprogger. Era il mio cuoco sulla Smotts' Revenge ed è sopravvissuto all'ultimo attacco. Può aiutarti a trovare il gigante.", nil, "Ehilà, ehilà, {name}. Il capitano mi ha detto che vai a caccia di Negolash, eh?", 0xb8962084, 0x114316b6, 0xb86aff68, nil, 0x2c14bb44, "...m." },
  [8554] = { "Affrontare Negolash", "Porta 10 Ala di Condor alla Griglia e 5 bottiglie di ⟦Junglevine Wine=Vino di Liana⟧ alla scialuppa del capitano Smotts.\n\nUccidi Negolash e porta la ⟦Smotts' Cutlass=Scimitarra di Smotts⟧ al capitano Smotts, a Rovotorto.", "Negolash è un gigante affamato.\n\nQuando i giganti hanno distrutto la nostra nave, Negolash è andato dritto nella mia cucina. Non aveva fame di marinai come gli altri giganti. Negolash voleva vino... e le mie Ali di Condor alla Griglia. Sono la mia specialità, e sono dovuto andare fino alle ⟦Badlands=Maleterre⟧ per la ricetta!\n\nSe vuoi attirare il gigante, procurati un po' di vino e un mucchio di ali di condor. Mettili nella nostra vecchia scialuppa, a sud-est di qui lungo la costa. Quando Negolash sentirà l'odore di tutto quel cibo, arriverà di sicuro!", "Hai recuperato la mia scimitarra, {name}?", "Hai recuperato la mia scimitarra da Negolash! Non posso credere alla mia fortuna, {name}! Incontrarti mi ha girato la sorte in meglio, puoi starne certo!\n\nGrazie! E se mai avrò una nuova nave e tu vorrai solcare i mari, sarai mio ospite d'onore.", 0x73a04fad, 0x63b34724, 0xcd78a826, 0x224ded7e, 0x423de715, "....." },
  [8556] = { nil, nil, "Si dice che gli anelli portati dai luogotenenti Qiraji conferiscano loro capacità formidabili. Le gemme corrotte che li adornano potrebbero, in teoria, essere sostituite con materiali più puri, per creare versioni incorrotte degli anelli.\n\nLe gemme che adornano gli idoli Qiraji andrebbero benissimo, perché la loro qualità è superiore.\n\nPortami l'anello e gli idoli e creerò per te un anello potente, {class}.", "Mi hai portato l'anello e i materiali, {name}?", "Sostituirò la gemma dell'anello per te. Vedrai che l'effetto è molto più... gradevole.", nil, nil, 0x1bf57e0d, 0x43a13b9a, 0x31e56a0d, "mm..." },
  [8557] = { nil, nil, "Mi fa piacere sapere che ci aiuterai nel nostro attacco ad ⟦Ahn'Qiraj=Ahn'qiraj⟧, {name}. Posso prepararti un oggetto protettivo che ti sarà d'aiuto nella lotta contro il nostro nemico, {class}.\n\nMi servirà un drappo Qiraji, che naturalmente adatterò alla tua misura. Mi serviranno anche idoli e scarabei, con cui creerò un fermaglio adatto.\n\nTi prometto che non resterai delus<o/a>.", "Hai portato i materiali per il mantello, {name}?", "Ah, sì... questo drappo è immacolato.\n\nPrendi questo mantello, {name}. Che ti protegga dalla magia immonda dei Qiraji.", nil, nil, 0x841bdde5, 0xde8b9b39, 0x67472b1a, "mm..." },
  [8558] = { nil, nil, "I Qiraji e i loro servitori impugnano oggetti fatti con i materiali più rari e pregiati: ossa di antiche creature gigantesche, gemme dalle profondità della terra, metalli puri e resistenti.\n\nLa sola vista dei manufatti Qiraji mi fa venire voglia di esercitare il mio mestiere sui loro frammenti spezzati e fusi. Dimostra la tua fedeltà al Circolo, {name}, e ti forgerò un'arma potente con i migliori materiali Qiraji.", "Mi hai portato i componenti che mi servono, {name}?", "Hai fatto un ottimo lavoro, {class}. Quest'elsa è un capolavoro... l'equilibrio è perfetto.\n\nPrendi la tua arma, {name}. Impugnala con grande sicurezza e sconfiggi i nostri nemici!", nil, nil, 0xbec045e9, 0x31fe20fc, 0xebafe37f, "mm..." },
  [8565] = { "Vittorie passate ad Arathi", nil, nil, nil, "Ah, sì! Certo che non ci saremmo dimenticati delle tue imprese passate nel ⟦Arathi Basin=Bacino d'Arathi⟧.", 0x1b6fa606, nil, nil, nil, 0x84b7e476, ".mmm." },
  [8566] = { "Vittorie passate ad Arathi", nil, nil, nil, "Ah, sì! Certo che non ci saremmo dimenticati delle tue imprese passate nel ⟦Arathi Basin=Bacino d'Arathi⟧.", 0x1b6fa606, nil, nil, nil, 0x84b7e476, ".mmm." },
  [8567] = { "Vittorie passate nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧", nil, nil, nil, "Ah, sì! Certo che non ci saremmo dimenticati delle tue imprese passate nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧.", 0x2097f0b6, nil, nil, nil, 0xbc373b8c, ".mmm." },
  [8568] = { "Vittorie passate nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧", nil, nil, nil, "Ah, sì! Certo che non ci saremmo dimenticati delle tue imprese passate nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧.", 0x2097f0b6, nil, nil, nil, 0xbc373b8c, ".mmm." },
  [8569] = { "Sforzi passati nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧", nil, nil, nil, "Ah, sì! Certo che non ci saremmo dimenticati delle tue imprese passate nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧.", 0xddd58d46, nil, nil, nil, 0xbc373b8c, ".mmm." },
  [8570] = { "Sforzi passati nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧", nil, nil, nil, "Ah, sì! Certo che non ci saremmo dimenticati delle tue imprese passate nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧.", 0xddd58d46, nil, nil, nil, 0xbc373b8c, ".mmm." },
  [8615] = { nil, nil, nil, "I draghi fatati possono essere bestiole pericolose, se provocati. Sta' attent<o/a> quando hai a che fare con loro, {class}. E sta' ancora più attent<o/a> agli elfi della notte della zona. Quegli sciocchi seccatori tendono a rintanarsi anche loro nelle foreste.\n\nQuando avrai abbastanza ali, fammelo sapere: ti ricompenserò bene, puoi starne cert<o/a>!", "Magnifico, {class}! Andranno benissimo. Ce n'è abbastanza per fare un mantello a Korrin, e forse anche di più! Grazie.\n\nSpero che il viaggio non sia stato troppo pericoloso. Feralas non è nota per essere clemente, ma evidentemente te la sei cavata bene.\n\nGrazie ancora, {class}.", nil, nil, nil, 0xeb9d3196, 0x75713903, "mmm.." },
  [8619] = { nil, nil, nil, nil, "È bello sapere che la gente di questa terra rende ancora omaggio alle razze antiche. Ti saluto, {name}, e ti offro questo pegno...", nil, nil, nil, nil, 0xdc5611ad, "mmmm." },
  [8642] = { nil, nil, nil, nil, "È bello sapere che la gente di questa terra rende ancora omaggio alle razze antiche. Ti saluto, {name}, e ti offro questo pegno...", nil, nil, nil, nil, 0xdc5611ad, "mmmm." },
