  [8688] = { "L'anziano Windrun", nil, nil, nil, "I cieli, con le loro innumerevoli stelle, custodiscono le risposte ai misteri terreni, {name}. Possono dunque i saggi, e i fortunati, alzare lo sguardo e trovare la verità?", 0x204f5248, nil, nil, nil, 0x3da1f0cc, ".mmm." },
  [8689] = { "⟦Shroud of Infinite Wisdom=Manto della Saggezza Infinita⟧", "Porta 1 ⟦Qiraji Martial Drape=Drappo Marziale Qiraji⟧, 2 Idolo di Diaspro, 5 Scarabeo d'Oro e 5 Scarabeo d'Argilla a Keyl Swiftclaw a ⟦Silithus=Silitus⟧. Per completare la missione devi anche ottenere la reputazione Reverito con il ⟦Cenarion Circle=Circolo Cenariano⟧.", "Mi fa piacere sapere che ci aiuterai nel nostro attacco ad ⟦Ahn'Qiraj=Ahn'qiraj⟧, {name}. Posso prepararti un oggetto protettivo che ti sarà d'aiuto nella lotta contro il nostro nemico, {class}.\n\nMi servirà un drappo Qiraji, che naturalmente adatterò alla tua misura. Mi serviranno anche idoli e scarabei, con cui creerò un fermaglio adatto.\n\nTi prometto che non resterai delus<o/a>.", "Hai portato i materiali per il mantello, {name}?", "Ah, sì... questo drappo è immacolato.\n\nPrendi questo mantello, {name}. Che ti protegga dalla magia immonda dei Qiraji.", 0x7213a736, 0x5493a2f1, 0x841bdde5, 0xde8b9b39, 0x67472b1a, "....." },
