  [8696] = { "⟦Cloak of the Unseen Path=Mantello del Sentiero Invisibile⟧", "Porta 1 ⟦Qiraji Regal Drape=Drappo Regale Qiraji⟧, 2 Idolo Brillante, 5 Scarabeo di Pietra e 5 Scarabeo di Cristallo a Keyl Swiftclaw a ⟦Silithus=Silitus⟧. Per completare la missione devi anche ottenere la reputazione Reverito con il ⟦Cenarion Circle=Circolo Cenariano⟧.", "Mi fa piacere sapere che ci aiuterai nel nostro attacco ad ⟦Ahn'Qiraj=Ahn'qiraj⟧, {name}. Posso prepararti un oggetto protettivo che ti sarà d'aiuto nella lotta contro il nostro nemico, {class}.\n\nMi servirà un drappo Qiraji, che naturalmente adatterò alla tua misura. Mi serviranno anche idoli e scarabei, con cui creerò un fermaglio adatto.\n\nTi prometto che non resterai delus<o/a>.", "Hai portato i materiali per il mantello, {name}?", "Ah, sì... questo drappo è immacolato.\n\nPrendi questo mantello, {name}. Che ti protegga dalla magia immonda dei Qiraji.", 0x68e6acd8, 0xe0504731, 0x841bdde5, 0xde8b9b39, 0x67472b1a, "....." },
  [8697] = { "⟦Ring of Infinite Wisdom=Anello della Saggezza Infinita⟧", "Porta 1 ⟦Qiraji Ceremonial Ring=Anello Cerimoniale Qiraji⟧, 2 Idolo d'Ossidiana, 5 Scarabeo d'Argento e 5 Scarabeo d'Ossa all'invocatrice dei venti Yessendra a ⟦Silithus=Silitus⟧. Per completare la missione devi anche ottenere la reputazione Onorato con il ⟦Cenarion Circle=Circolo Cenariano⟧.", "Si dice che gli anelli portati dai luogotenenti Qiraji conferiscano loro capacità formidabili. Le gemme corrotte che li adornano potrebbero, in teoria, essere sostituite con materiali più puri, per creare versioni incorrotte degli anelli.\n\nLe gemme che adornano gli idoli Qiraji andrebbero benissimo, perché la loro qualità è superiore.\n\nPortami l'anello e gli idoli e creerò per te un anello potente, {class}.", "Mi hai portato l'anello e i materiali, {name}?", "Sostituirò la gemma dell'anello per te. Vedrai che l'effetto è molto più... gradevole.", 0x6bd8ae8b, 0x51ba3fa2, 0x1bf57e0d, 0x43a13b9a, 0x31e56a0d, "....." },
