  [8704] = { "⟦Signet of the Unseen Path=Sigillo del Sentiero Invisibile⟧", "Porta 1 ⟦Qiraji Ceremonial Ring=Anello Cerimoniale Qiraji⟧, 2 Idolo d'Ambra, 5 Scarabeo d'Oro e 5 Scarabeo d'Argilla all'invocatrice dei venti Yessendra a ⟦Silithus=Silitus⟧. Per completare la missione devi anche ottenere la reputazione Onorato con il ⟦Cenarion Circle=Circolo Cenariano⟧.", "Si dice che gli anelli portati dai luogotenenti Qiraji conferiscano loro capacità formidabili. Le gemme corrotte che li adornano potrebbero, in teoria, essere sostituite con materiali più puri, per creare versioni incorrotte degli anelli.\n\nLe gemme che adornano gli idoli Qiraji andrebbero benissimo, perché la loro qualità è superiore.\n\nPortami l'anello e gli idoli e creerò per te un anello potente, {class}.", "Mi hai portato l'anello e i materiali, {name}?", "Sostituirò la gemma dell'anello per te. Vedrai che l'effetto è molto più... gradevole.", 0xc90436d6, 0xb6333055, 0x1bf57e0d, 0x43a13b9a, 0x31e56a0d, "....." },
  [8705] = { "⟦Gavel of Infinite Wisdom=Martellaccio della Saggezza Infinita⟧", "Porta 1 ⟦Qiraji Ornate Hilt=Elsa Ornata Qiraji⟧, 2 Idolo Brillante, 5 Scarabeo di Bronzo e 5 Scarabeo d'Avorio al custode Haro a ⟦Silithus=Silitus⟧. Per completare la missione devi anche ottenere la reputazione Osannato con il ⟦Cenarion Circle=Circolo Cenariano⟧.", "I Qiraji e i loro servitori impugnano oggetti fatti con i materiali più rari e pregiati: ossa di antiche creature gigantesche, gemme dalle profondità della terra, metalli puri e resistenti.\n\nLa sola vista dei manufatti Qiraji mi fa venire voglia di esercitare il mio mestiere sui loro frammenti spezzati e fusi. Dimostra la tua fedeltà al Circolo, {name}, e ti forgerò un'arma potente con i migliori materiali Qiraji.", "Mi hai portato i componenti che mi servono, {name}?", "Hai fatto un ottimo lavoro, {class}. Quest'elsa è un capolavoro... l'equilibrio è perfetto.\n\nPrendi la tua arma, {name}. Impugnala con grande sicurezza e sconfiggi i nostri nemici!", 0x231ff20f, 0x98737e38, 0xbec045e9, 0x31fe20fc, 0xebafe37f, "....." },
  [8706] = { "⟦Hammer of the Gathering Storm=Martello della Tempesta Crescente⟧", "Porta 1 ⟦Qiraji Spiked Hilt=Elsa Chiodata Qiraji⟧, 2 Idolo d'Ambra, 5 Scarabeo d'Avorio e 5 Scarabeo di Bronzo al custode Haro a ⟦Silithus=Silitus⟧. Per completare la missione devi anche ottenere la reputazione Osannato con il ⟦Cenarion Circle=Circolo Cenariano⟧.", "I Qiraji e i loro servitori impugnano oggetti fatti con i materiali più rari e pregiati: ossa di antiche creature gigantesche, gemme dalle profondità della terra, metalli puri e resistenti.\n\nLa sola vista dei manufatti Qiraji mi fa venire voglia di esercitare il mio mestiere sui loro frammenti spezzati e fusi. Dimostra la tua fedeltà al Circolo, {name}, e ti forgerò un'arma potente con i migliori materiali Qiraji.", "Mi hai portato i componenti che mi servono, {name}?", "Hai fatto un ottimo lavoro, {class}. Quest'elsa è un capolavoro... l'equilibrio è perfetto.\n\nPrendi la tua arma, {name}. Impugnala con grande sicurezza e sconfiggi i nostri nemici!", 0xc48609b5, 0x8244fda2, 0xbec045e9, 0x31fe20fc, 0xebafe37f, "....." },
